class RequestError(Exception):
    def __init__(self, message: str, status: int = 400):
        super().__init__(message)
        self.status = status


class DataIntegrityError(RuntimeError):
    """Raised when a durable JSON store exists but cannot be trusted."""


def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat()


def utc_after(minutes: int) -> str:
    return (datetime.now(timezone.utc) + timedelta(minutes=minutes)).isoformat()


def parse_iso(value: str | None) -> datetime | None:
    if not value:
        return None
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
        return parsed if parsed.tzinfo else parsed.replace(tzinfo=timezone.utc)
    except (TypeError, ValueError):
        return None


def clamp_int(value, default: int, minimum: int, maximum: int) -> int:
    try:
        number = int(value)
    except (TypeError, ValueError, OverflowError):
        number = default
    return max(minimum, min(maximum, number))


def contains_potential_secret(value: str) -> bool:
    text = str(value or "")
    return any(pattern.search(text) for pattern in SECRET_PATTERNS)


def is_sensitive_field_name(value: object) -> bool:
    compact = re.sub(r"[^a-z0-9]", "", str(value or "").lower())
    return bool(compact) and compact not in SENSITIVE_FIELD_METADATA and compact.endswith(SENSITIVE_FIELD_SUFFIXES)


def json_contains_potential_secret(value, depth: int = 0) -> bool:
    if depth > 8:
        return False
    if isinstance(value, str):
        return contains_potential_secret(value)
    if isinstance(value, list):
        return any(json_contains_potential_secret(item, depth + 1) for item in value[:500])
    if isinstance(value, dict):
        return any(
            (is_sensitive_field_name(key) and item is not None)
            or json_contains_potential_secret(item, depth + 1)
            for key, item in list(value.items())[:500]
        )
    return False


def redact_text(value: str, limit: int = 8000) -> str:
    text = str(value or "")
    for pattern in SECRET_PATTERNS:
        text = pattern.sub("[REDACTED_SECRET]", text)
    text = re.sub(r"(?i)\b(?:pid|process[_ .-]?id)\b\s*[:=#-]?\s*\d+\b", "[REDACTED_SECRET]", text)
    text = re.sub(
        r"(?i)\b(?:account[_ .-]?(?:number|no|id|login)|broker[_ .-]?server|terminal[_ .-]?path|process[_ .-]?id|pid)\b\s*[\"']?\s*(?::|=|#|\bis\b)\s*(?:\"[^\"]*\"|'[^']*'|[^,;|\n]+)",
        "[REDACTED_SECRET]",
        text,
    )
    text = re.sub(r"(?i)\b[A-Z]:\\[^,;|\"'\n]+", "[REDACTED_PATH]", text)
    text = re.sub(r"\\\\[^,;|\"'\n]+", "[REDACTED_PATH]", text)
    text = re.sub(r"(?i)(?<!\w)/(?:Users|home|root|var|etc|tmp|opt|srv)/[^,;|\"'\n]+", "[REDACTED_PATH]", text)
    home = str(Path.home())
    if home:
        text = text.replace(home, "%USERPROFILE%")
    return text[:limit]


def _redact_text_fail_closed(value: object, limit: int, field_name: str) -> str:
    """Redact secrets and paths while refusing to silently clip trusted input."""

    text = redact_text(str(value or ""), limit + 1)
    if len(text) > limit:
        raise DataIntegrityError(f"{field_name} exceeds its bounded envelope.")
    return text


def _validated_interactive_meeting_implementation_proposal(value: object) -> dict:
    """Return the one exact, bounded structured packet allowed to authorize code work."""

    if (
        not isinstance(value, dict)
        or set(value) != INTERACTIVE_MEETING_IMPLEMENTATION_PROPOSAL_FIELDS
        or value.get("schemaVersion")
        != INTERACTIVE_MEETING_IMPLEMENTATION_PROPOSAL_SCHEMA
    ):
        raise DataIntegrityError(
            "Meeting implementation proposal has an invalid structured schema."
        )
    meeting_id = safe_reference(value.get("meetingId"))
    proposal_turn_id = safe_reference(value.get("proposalTurnId"))
    proposal_digest_value = str(value.get("proposalDigest") or "")
    if (
        not meeting_id
        or not proposal_turn_id
        or not re.fullmatch(r"[0-9a-f]{64}", proposal_digest_value)
    ):
        raise DataIntegrityError(
            "Meeting implementation proposal has an invalid visible binding."
        )

    def exact_text(
        field_name: str,
        limit: int,
        *,
        allow_empty: bool = False,
    ) -> str:
        raw = value.get(field_name)
        if not isinstance(raw, str):
            raise DataIntegrityError(
                f"Meeting implementation proposal {field_name} must be text."
            )
        cleaned = _redact_text_fail_closed(
            raw,
            limit,
            f"Meeting implementation proposal {field_name}",
        )
        if cleaned != raw or (not allow_empty and not cleaned.strip()):
            raise DataIntegrityError(
                f"Meeting implementation proposal {field_name} is not exact sanitized text."
            )
        return cleaned

    risks_value = value.get("risks")
    checks_value = value.get("acceptanceChecks")
    if (
        not isinstance(risks_value, list)
        or len(risks_value) > INTERACTIVE_MEETING_RISK_MAX_ITEMS
        or not isinstance(checks_value, list)
        or len(checks_value) > INTERACTIVE_MEETING_ACCEPTANCE_MAX_ITEMS
    ):
        raise DataIntegrityError(
            "Meeting implementation proposal list bounds are invalid."
        )

    def exact_list(items: list, field_name: str) -> list[str]:
        result: list[str] = []
        for item in items:
            if not isinstance(item, str):
                raise DataIntegrityError(
                    f"Meeting implementation proposal {field_name} items must be text."
                )
            cleaned = _redact_text_fail_closed(
                item,
                INTERACTIVE_MEETING_LIST_ITEM_MAX_CHARS,
                f"Meeting implementation proposal {field_name} item",
            )
            if cleaned != item or not cleaned.strip():
                raise DataIntegrityError(
                    f"Meeting implementation proposal {field_name} item is not exact sanitized text."
                )
            result.append(cleaned)
        return result

    manager_decision = value.get("managerDecision")
    if not isinstance(manager_decision, dict) or set(manager_decision) != {
        "status",
        "summary",
    }:
        raise DataIntegrityError(
            "Meeting implementation proposal Manager decision schema is invalid."
        )
    decision_status = str(manager_decision.get("status") or "")
    decision_summary_raw = manager_decision.get("summary")
    if (
        decision_status not in INTERACTIVE_MEETING_MANAGER_DECISION_STATUSES
        or decision_status == "not_applicable"
        or not isinstance(decision_summary_raw, str)
    ):
        raise DataIntegrityError(
            "Meeting implementation proposal Manager decision is not actionable."
        )
    decision_summary = _redact_text_fail_closed(
        decision_summary_raw,
        INTERACTIVE_MEETING_MANAGER_DECISION_MAX_CHARS,
        "Meeting implementation proposal Manager decision summary",
    )
    if decision_summary != decision_summary_raw or not decision_summary.strip():
        raise DataIntegrityError(
            "Meeting implementation proposal Manager decision summary is not exact sanitized text."
        )
    return {
        "schemaVersion": INTERACTIVE_MEETING_IMPLEMENTATION_PROPOSAL_SCHEMA,
        "meetingId": meeting_id,
        "proposalDigest": proposal_digest_value,
        "proposalTurnId": proposal_turn_id,
        "agenda": exact_text("agenda", 2400),
        "developmentGoal": exact_text("developmentGoal", 2400),
        "proposal": exact_text(
            "proposal",
            INTERACTIVE_MEETING_PROPOSAL_MAX_CHARS,
        ),
        "risks": exact_list(risks_value, "risks"),
        "acceptanceChecks": exact_list(
            checks_value,
            "acceptanceChecks",
        ),
        "managerDecision": {
            "status": decision_status,
            "summary": decision_summary,
        },
        "approvalNote": exact_text("approvalNote", 1200, allow_empty=True),
    }


def sanitize_json_value(value, depth: int = 0, collection_limit: int = 100, string_limit: int = 8000):
    # Dashboard responses contain nested action metadata such as
    # workflowDashboard.actions[].formFields[].options[].  A depth limit of
    # six replaced those harmless select values with "[TRUNCATED]" at the
    # final HTTP projection and also clipped deeper report evidence.  Keep a
    # finite ceiling for hostile or accidental nesting, but allow the public
    # read model to survive the second sanitization performed by send_json().
    if depth > 12:
        return "[TRUNCATED]"
    if isinstance(value, str):
        return redact_text(value, string_limit)
    if isinstance(value, list):
        return [sanitize_json_value(item, depth + 1, collection_limit, string_limit) for item in value[:collection_limit]]
    if isinstance(value, dict):
        cleaned = {}
        for key, item in list(value.items())[:collection_limit]:
            safe_key = str(key)[:120]
            cleaned[safe_key] = (
                None if item is None else "[REDACTED_SECRET]"
            ) if is_sensitive_field_name(safe_key) else sanitize_json_value(item, depth + 1, collection_limit, string_limit)
        return cleaned
    if value is None or isinstance(value, (bool, int, float)):
        return value
    return redact_text(str(value), 1000)


def is_visual_simulation(payload: dict) -> bool:
    if bool(payload.get("simulation", False)) or str(payload.get("kind") or "").lower() == "autonomy":
        return True
    sample = json.dumps(payload, ensure_ascii=False)[:12000].lower()
    return "autonomous status sync" in sample or "autonomous patrol" in sample


def safe_id(value: str | None, prefix: str = "item") -> str:
    candidate = str(value or "").strip()
    if candidate and SAFE_ID_PATTERN.fullmatch(candidate):
        return candidate
    return f"{prefix}-{int(time.time() * 1000)}-{secrets.token_hex(3)}"


def safe_reference(value: object) -> str | None:
    candidate = str(value or "").strip()
    return candidate if candidate and SAFE_ID_PATTERN.fullmatch(candidate) else None


def safe_codex_artifact_reference(value: object) -> str | None:
    candidate = str(value or "").strip().replace("\\", "/")
    if not candidate or Path(candidate).is_absolute() or ".." in Path(candidate).parts:
        return None
    resolved = (PROJECT_ROOT / Path(candidate)).resolve(strict=False)
    allowed_root = (RUNTIME_DIR / "codex-runs").resolve(strict=False)
    try:
        resolved.relative_to(allowed_root)
    except ValueError:
        return None
    return resolved.relative_to(PROJECT_ROOT.resolve(strict=False)).as_posix()


def payload_digest(*parts: str) -> str:
    joined = "\n".join(str(part or "") for part in parts)
    return hashlib.sha256(joined.encode("utf-8", errors="replace")).hexdigest()


def mission_payload_digest(mission: dict) -> str:
    """Bind one approval or Backend auto policy to the execution packet."""
    execution = mission.get("execution") if isinstance(mission.get("execution"), dict) else {}
    packet = {
        "owner": str(mission.get("owner") or ""),
        "toolId": str(mission.get("toolId") or ""),
        "targetId": str(mission.get("targetId") or ""),
        "detail": str(mission.get("detail") or ""),
        "modelTier": str(mission.get("modelTier") or ""),
        "budget": mission.get("budget") if isinstance(mission.get("budget"), dict) else {},
        "risk": str(mission.get("risk") or ""),
        "reportType": str(mission.get("reportType") or ""),
        "idempotencyKey": str(mission.get("idempotencyKey") or ""),
        "idempotencyScopeDigest": str(
            mission.get("idempotencyScopeDigest") or ""
        ),
        "executionAuthorization": {
            "executionMode": str(mission.get("executionMode") or ""),
            "autoEligible": mission.get("autoEligible") is True,
            "autoQueuedAt": str(mission.get("autoQueuedAt") or ""),
            "requiresHumanApproval": mission.get("requiresHumanApproval") is True,
            "schema": str(execution.get("schema") or ""),
            "authorizationId": str(execution.get("authorizationId") or ""),
            "authorizationIssuedAt": str(execution.get("authorizationIssuedAt") or ""),
            "authorizationSource": str(execution.get("authorizationSource") or ""),
            "authorizationDecision": str(execution.get("authorizationDecision") or ""),
            "authorizationPolicyVersion": str(
                execution.get("authorizationPolicyVersion") or ""
            ),
            "authorizationReason": str(execution.get("authorizationReason") or ""),
        },
        # Trusted workflow lineage selects the bounded intent, quota reserve,
        # sandbox and output validator. It is authorization material too.
        "workflowContext": _workflow_context_storage(
            mission.get("workflowContext")
        ),
        "radarBatchRepair": (
            mission.get("radarBatchRepair")
            if isinstance(mission.get("radarBatchRepair"), dict)
            else None
        ),
    }
    meeting_binding = (
        mission.get("meetingApprovalBinding")
        if isinstance(mission.get("meetingApprovalBinding"), dict)
        else {}
    )
    if meeting_binding:
        packet["meetingApprovalBinding"] = {
            "schemaVersion": str(meeting_binding.get("schemaVersion") or ""),
            "meetingId": str(meeting_binding.get("meetingId") or ""),
            "proposalDigest": str(meeting_binding.get("proposalDigest") or ""),
            "proposalTurnId": str(meeting_binding.get("proposalTurnId") or ""),
        }
    meeting_implementation_proposal = mission.get(
        "meetingImplementationProposal"
    )
    if isinstance(meeting_implementation_proposal, dict) and meeting_implementation_proposal:
        # This packet carries the complete operator intent and frozen Manager
        # decision. Bind the exact validated structure, not merely the rendered
        # prompt or the three visible approval identifiers.
        packet["meetingImplementationProposal"] = (
            _validated_interactive_meeting_implementation_proposal(
                meeting_implementation_proposal
            )
        )
    analysis_context = mission.get("analysisContext")
    if isinstance(analysis_context, dict) and analysis_context:
        packet["analysisContext"] = sanitize_json_value(analysis_context)
    canonical = json.dumps(packet, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(canonical.encode("utf-8", errors="replace")).hexdigest()


def tail_jsonl(path: Path, limit: int = 80, max_bytes: int = 262144) -> list[dict]:
    if not path.exists():
        return []
    with path.open("rb") as handle:
        handle.seek(0, os.SEEK_END)
        size = handle.tell()
        handle.seek(max(0, size - max_bytes), os.SEEK_SET)
        raw = handle.read().decode("utf-8", errors="replace")
    rows = raw.splitlines()
    if size > max_bytes and rows:
        rows = rows[1:]
    records = []
    for row in rows[-limit:]:
        try:
            item = json.loads(row)
            if isinstance(item, dict):
                records.append(item)
        except json.JSONDecodeError:
            records.append({"type": "log_parse_warning", "detail": "A legacy malformed log line was skipped."})
    return records


def rotate_jsonl_segment(path: Path, max_bytes: int = JSONL_SEGMENT_MAX_BYTES) -> Path | None:
    """Archive a full append-only segment without deleting history."""
    if not path.exists() or path.stat().st_size < max_bytes:
        return None
    if path == MEETING_TRANSCRIPTS_PATH:
        archive_dir = path.parent / "archive"
    else:
        archive_dir = RUNTIME_DIR / "archive" / path.stem
    archive_dir.mkdir(parents=True, exist_ok=True)
    stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ")
    destination = archive_dir / f"{path.stem}-{stamp}-{secrets.token_hex(3)}{path.suffix}"
    os.replace(path, destination)
    return destination


def ensure_runtime_dir() -> None:
    RUNTIME_DIR.mkdir(parents=True, exist_ok=True)
    RUNTIME_REPORTS_DIR.mkdir(parents=True, exist_ok=True)


def acquire_bridge_process_guard() -> bool:
    """Acquire one OS-level bridge lease per project checkout.

    The PowerShell launcher already serializes its own start operation, but a
    user can still invoke ``bridge_server.py`` directly on another port.  The
    backend scheduler and JSON stores are project-wide, so two bridge processes
    for the same checkout are unsafe even when their HTTP ports differ.
    """

    global BRIDGE_PROCESS_GUARD
    if BRIDGE_PROCESS_GUARD is not None:
        return True
    ensure_runtime_dir()
    if os.name == "nt":
        import ctypes
        from ctypes import wintypes

        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        create_mutex = kernel32.CreateMutexW
        create_mutex.argtypes = (wintypes.LPVOID, wintypes.BOOL, wintypes.LPCWSTR)
        create_mutex.restype = wintypes.HANDLE
        close_handle = kernel32.CloseHandle
        close_handle.argtypes = (wintypes.HANDLE,)
        close_handle.restype = wintypes.BOOL
        mutex_name = f"Local\\MetafxAgentHQBridge-{BRIDGE_PROCESS_GUARD_STATE['nameDigest']}"
        handle = create_mutex(None, False, mutex_name)
        if not handle:
            raise OSError(ctypes.get_last_error(), "CreateMutexW failed")
        if ctypes.get_last_error() == 183:  # ERROR_ALREADY_EXISTS
            close_handle(handle)
            return False
        BRIDGE_PROCESS_GUARD = {
            "kind": "windows_named_mutex",
            "handle": handle,
            "closeHandle": close_handle,
        }
    else:
        import fcntl

        lock_path = RUNTIME_DIR / ".bridge-process.lock"
        handle = lock_path.open("a+", encoding="utf-8")
        try:
            fcntl.flock(handle.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            handle.close()
            return False
        BRIDGE_PROCESS_GUARD = {
            "kind": "posix_flock",
            "handle": handle,
        }
    BRIDGE_PROCESS_GUARD_STATE.update(
        acquired=True,
        kind=str(BRIDGE_PROCESS_GUARD.get("kind") or "unknown"),
    )
    return True


def release_bridge_process_guard() -> None:
    global BRIDGE_PROCESS_GUARD
    guard = BRIDGE_PROCESS_GUARD
    BRIDGE_PROCESS_GUARD = None
    BRIDGE_PROCESS_GUARD_STATE.update(acquired=False, kind=None)
    if not isinstance(guard, dict):
        return
    try:
        if guard.get("kind") == "windows_named_mutex":
            close_handle = guard.get("closeHandle")
            if callable(close_handle):
                close_handle(guard.get("handle"))
        elif guard.get("kind") == "posix_flock":
            import fcntl

            handle = guard.get("handle")
            if handle is not None:
                fcntl.flock(handle.fileno(), fcntl.LOCK_UN)
                handle.close()
    except (OSError, ValueError):
        # Process termination releases both guard types.  Cleanup failures must
        # not hide the original bridge shutdown outcome.
        pass


def write_bridge_control_file(host: str, port: int) -> None:
    """Publish a backend-only shutdown credential for the local launcher."""

    write_json(
        BRIDGE_CONTROL_PATH,
        {
            "schemaVersion": "1.0.0",
            "projectRoot": str(PROJECT_ROOT),
            "processId": os.getpid(),
            "port": int(port),
            "host": str(host),
            "startedAt": SERVER_STARTED_AT,
            "shutdownToken": BRIDGE_SHUTDOWN_TOKEN,
        },
        keep_backup=False,
    )


def remove_bridge_control_file() -> None:
    """Remove only the control file owned by this process and token."""

    try:
        payload = read_json(BRIDGE_CONTROL_PATH, {})
        owns_file = bool(
            isinstance(payload, dict)
            and int(payload.get("processId") or 0) == os.getpid()
            and secrets.compare_digest(
                str(payload.get("shutdownToken") or ""),
                BRIDGE_SHUTDOWN_TOKEN,
            )
        )
        if owns_file:
            BRIDGE_CONTROL_PATH.unlink(missing_ok=True)
    except (OSError, ValueError, TypeError, DataIntegrityError):
        pass


def read_json(path: Path, fallback):
    if not path.exists():
        return fallback
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        relative_path = path.relative_to(PROJECT_ROOT) if path.is_relative_to(PROJECT_ROOT) else path.name
        raise DataIntegrityError(f"JSON integrity check failed for {relative_path}.") from error


def _bounded_atomic_replace(
    source: Path,
    destination: Path,
    *,
    max_attempts: int = 1,
    initial_delay_seconds: float = 0.0,
) -> None:
    """Atomically replace a file, retrying only transient Windows access denial."""
    attempts = max(1, min(8, int(max_attempts)))
    initial_delay = max(0.0, min(0.25, float(initial_delay_seconds)))
    for attempt in range(attempts):
        try:
            os.replace(source, destination)
            return
        except PermissionError:
            if attempt + 1 >= attempts:
                raise
            time.sleep(min(0.25, initial_delay * (2**attempt)))


def write_json(
    path: Path,
    payload,
    *,
    keep_backup: bool = False,
    replace_max_attempts: int = 1,
    replace_initial_delay_seconds: float = 0.0,
) -> None:
    ensure_runtime_dir()
    path.parent.mkdir(parents=True, exist_ok=True)
    # Thread IDs repeat across processes and may be reused after a thread
    # exits.  Include process identity plus a random nonce so a test runner,
    # launcher, or short-lived maintenance process can never share a staging
    # filename with the live Bridge.
    staging_id = f"{os.getpid()}.{threading.get_ident()}.{secrets.token_hex(8)}"
    temporary = path.with_name(f".{path.name}.{staging_id}.tmp")
    backup = path.with_name(f"{path.name}.bak")
    backup_temporary = path.with_name(f".{path.name}.bak.{staging_id}.tmp")
    serialized = json.dumps(payload, ensure_ascii=False, indent=2)
    try:
        if keep_backup and path.exists():
            try:
                json.loads(path.read_text(encoding="utf-8"))
            except (OSError, UnicodeError, json.JSONDecodeError) as error:
                relative_path = path.relative_to(PROJECT_ROOT) if path.is_relative_to(PROJECT_ROOT) else path.name
                raise DataIntegrityError(
                    f"Refusing to overwrite corrupt JSON store {relative_path}; restore its .bak copy first."
                ) from error
            shutil.copyfile(path, backup_temporary)
            _bounded_atomic_replace(
                backup_temporary,
                backup,
                max_attempts=replace_max_attempts,
                initial_delay_seconds=replace_initial_delay_seconds,
            )
        with temporary.open("w", encoding="utf-8", newline="\n") as handle:
            handle.write(serialized)
            handle.flush()
            if keep_backup:
                os.fsync(handle.fileno())
        _bounded_atomic_replace(
            temporary,
            path,
            max_attempts=replace_max_attempts,
            initial_delay_seconds=replace_initial_delay_seconds,
        )
    finally:
        for leftover in (temporary, backup_temporary):
            try:
                leftover.unlink(missing_ok=True)
            except OSError:
                pass


def ui_session_dashboard_version(session) -> int:
    if not isinstance(session, dict):
        return 0
    modal = session.get("modal")
    if not isinstance(modal, dict):
        return 0
    try:
        return max(0, int(modal.get("signalDashboardVersion") or 0))
    except (TypeError, ValueError):
        return 0


def store_ui_session(session) -> dict:
    # Browser tabs can persist the same session at nearly the same time. Keep
    # the read/version-check/write transaction serialized so an older tab can
    # never overwrite a newer dashboard version. Windows security scanners can
    # briefly deny an atomic replace, so this low-risk UI store uses a small,
    # bounded backoff while the last-good file and backup remain untouched.
    with UI_SESSION_LOCK:
        existing = read_json(UI_SESSION_PATH, {"session": None, "updatedAt": None})
        existing_session = existing.get("session") if isinstance(existing, dict) else None
        existing_version = ui_session_dashboard_version(existing_session)
        incoming_version = ui_session_dashboard_version(session)
        if existing_version > incoming_version:
            return {
                "ok": True,
                "ignored": True,
                "reason": "older_dashboard_version",
                "updatedAt": existing.get("updatedAt") if isinstance(existing, dict) else None,
                "storedDashboardVersion": existing_version,
            }
        updated_at = utc_now()
        write_json(
            UI_SESSION_PATH,
            {"updatedAt": updated_at, "session": session},
            keep_backup=UI_SESSION_PATH.exists(),
            replace_max_attempts=UI_SESSION_REPLACE_MAX_ATTEMPTS,
            replace_initial_delay_seconds=UI_SESSION_REPLACE_INITIAL_DELAY_SECONDS,
        )
        return {
            "ok": True,
            "ignored": False,
            "updatedAt": updated_at,
            "storedDashboardVersion": incoming_version,
        }


def load_tool_permissions() -> dict:
    return read_json(TOOL_PERMISSION_PATH, {"tools": [], "blocked_everywhere": []})


def load_orchestration_contract() -> dict:
    return read_json(ORCHESTRATION_CONTRACT_PATH, {"modelTiers": {}, "costRateGuard": {}})


def operator_mode_policy() -> dict:
    contract = load_orchestration_contract()
    policy = contract.get("operatorMode") if isinstance(contract.get("operatorMode"), dict) else {}
    return policy


def _operator_mode_default() -> str:
    configured = str(operator_mode_policy().get("defaultMode") or "auto_guarded")
    return configured if configured in {"auto_guarded", "manual_guarded"} else "auto_guarded"


def load_operator_mode_record() -> dict:
    default_mode = _operator_mode_default()
    if not OPERATOR_MODE_PATH.exists():
        return {"mode": default_mode, "updatedAt": SERVER_STARTED_AT, "source": "contract_default"}
    stored = read_json(OPERATOR_MODE_PATH, {})
    if not isinstance(stored, dict):
        raise DataIntegrityError("Operator mode store has an invalid shape.")
    mode = str(stored.get("mode") or "")
    if mode not in {"auto_guarded", "manual_guarded"}:
        raise DataIntegrityError("Operator mode store contains an unsupported mode.")
    return {
        "mode": mode,
        "updatedAt": stored.get("updatedAt") or SERVER_STARTED_AT,
        "source": "runtime_store",
    }


def ensure_operator_mode_store() -> dict:
    record = load_operator_mode_record()
    if OPERATOR_MODE_PATH.exists():
        return record
    persisted = {
        "version": "operator-mode-store-v1",
        "mode": record["mode"],
        "updatedAt": utc_now(),
        "source": "contract_default",
    }
    write_json(OPERATOR_MODE_PATH, persisted)
    return persisted


def mission_worker_read_model(*, include_queue_count: bool = True) -> dict:
    with MISSION_WORKER_LOCK:
        state = dict(MISSION_WORKER_STATE)
    queued: int | None = None
    if include_queue_count:
        try:
            missions = load_missions()
        except (DataIntegrityError, OSError):
            missions = []
        queued = sum(
            1
            for mission in missions
            if mission.get("status") == "queued"
            and mission.get("autoEligible") is True
            and mission.get("executionMode") == "auto_guarded"
            and isinstance(mission.get("execution"), dict)
            and mission["execution"].get("schema") == "auto-guarded-execution-v1"
            and mission["execution"].get("dispatchState") in {"queued", "deferred"}
        )
    worker_alive = bool(
        MISSION_WORKER_THREAD
        and MISSION_WORKER_THREAD.is_alive()
        and not MISSION_WORKER_STOP.is_set()
    )
    watchdog_alive = bool(
        MISSION_WORKER_WATCHDOG_THREAD
        and MISSION_WORKER_WATCHDOG_THREAD.is_alive()
        and not MISSION_WORKER_STOP.is_set()
    )
    status = str(state.get("status") or "stopped").strip().lower()
    heartbeat = parse_iso(str(state.get("heartbeatAt") or ""))
    heartbeat_age = None
    if heartbeat is not None:
        heartbeat_age = max(
            0.0,
            (datetime.now(timezone.utc) - heartbeat.astimezone(timezone.utc)).total_seconds(),
        )
    heartbeat_stale = bool(
        heartbeat_age is None
        or heartbeat_age > MISSION_WORKER_MAX_HEARTBEAT_AGE_SECONDS
    )
    operational_statuses = {"starting", "idle", "running"}
    operational = bool(
        worker_alive
        and watchdog_alive
        and not heartbeat_stale
        and status in operational_statuses
    )
    if not worker_alive:
        operational_reason = "worker_thread_not_alive"
    elif not watchdog_alive:
        operational_reason = "watchdog_not_alive"
    elif heartbeat_stale:
        operational_reason = "heartbeat_stale"
    elif status not in operational_statuses:
        operational_reason = f"runtime_{status or 'unknown'}"
    else:
        operational_reason = None
    return {
        "status": redact_text(status, 40),
        "alive": worker_alive,
        "operational": operational,
        "operationalReason": operational_reason,
        "workerId": safe_reference(state.get("workerId")),
        "currentMissionId": safe_reference(state.get("currentMissionId")),
        "startedAt": state.get("startedAt"),
        "heartbeatAt": state.get("heartbeatAt"),
        "queued": queued,
        "queueCountAvailable": include_queue_count,
        "watchdogAlive": watchdog_alive,
        "heartbeatStale": heartbeat_stale,
        "heartbeatAgeSeconds": round(heartbeat_age, 1) if heartbeat_age is not None else None,
        "maxHeartbeatAgeSeconds": MISSION_WORKER_MAX_HEARTBEAT_AGE_SECONDS,
        "lastError": redact_text(str(state.get("lastError") or ""), 240) or None,
    }


def operator_mode_read_model() -> dict:
    policy = operator_mode_policy()
    record = load_operator_mode_record()
    mode = str(record.get("mode") or _operator_mode_default())
    auto_tools = [
        value
        for value in (safe_reference(item) for item in (policy.get("autoEligibleTools") or ["codex_cli_task"]))
        if value
    ]
    always_gated = [
        redact_text(str(item), 120)
        for item in (policy.get("alwaysRequireHumanApprovalFor") or [])
        if str(item).strip()
    ]
    return {
        "mode": mode,
        "labelTh": "ทำงานอัตโนมัติแบบมีระบบป้องกัน" if mode == "auto_guarded" else "ยืนยันงานจริงด้วยตนเอง",
        "autoExecute": mode == "auto_guarded",
        "guardrails": {
            "autoEligibleTools": auto_tools,
            "maxRisk": redact_text(str(policy.get("maxRisk") or "medium"), 20),
            "alwaysRequireHumanApprovalFor": always_gated,
        },
        "worker": mission_worker_read_model(),
        "updatedAt": record.get("updatedAt") or SERVER_STARTED_AT,
    }


def set_operator_mode(payload: dict) -> dict:
    if not isinstance(payload, dict) or set(payload) != {"mode"}:
        return {
            "ok": False,
            "kind": "invalid_operator_mode_request",
            "message": "Operator mode accepts only the mode field.",
            "_httpStatus": 422,
        }
    mode = str(payload.get("mode") or "")
    if mode not in {"auto_guarded", "manual_guarded"}:
        return {
            "ok": False,
            "kind": "invalid_operator_mode",
            "message": "Mode must be auto_guarded or manual_guarded.",
            "_httpStatus": 422,
        }
    previous = load_operator_mode_record()
    changed_at = utc_now()
    write_json(
        OPERATOR_MODE_PATH,
        {
            "version": "operator-mode-store-v1",
            "mode": mode,
            "updatedAt": changed_at,
            "source": "local_operator_api",
        },
        keep_backup=OPERATOR_MODE_PATH.exists(),
    )
    with BRIDGE_STATUS_CACHE_CONDITION:
        BRIDGE_STATUS_CACHE.update({
            "payload": None,
            "fetchedMonotonic": 0.0,
        })
        BRIDGE_STATUS_CACHE_CONDITION.notify_all()
    with EQUIPMENT_CONNECTION_CENTER_CACHE_CONDITION:
        EQUIPMENT_CONNECTION_CENTER_CACHE.update({
            "storedAtMonotonic": 0.0,
            "value": None,
            "generation": int(
                EQUIPMENT_CONNECTION_CENTER_CACHE.get("generation") or 0
            ) + 1,
        })
        EQUIPMENT_CONNECTION_CENTER_CACHE_CONDITION.notify_all()
    append_audit({
        "type": "operator_mode.changed",
        "previousMode": previous.get("mode"),
        "mode": mode,
        "autoExecute": mode == "auto_guarded",
        "source": "local_operator_api",
    })
    MISSION_WORKER_WAKE.set()
    COLLABORATION_SCHEDULER_WAKE.set()
    AI_TRADE_COUNCIL_AUTOMATION_WAKE.set()
    DASHBOARD_WORKFLOW_SCHEDULER_WAKE.set()
    return {"ok": True, "kind": "operator_mode", **operator_mode_read_model()}


THAILAND_TIMEZONE = timezone(timedelta(hours=7))
COLLABORATION_CONFIG_FIELDS = frozenset({
    "enabled",
    "topic",
    "startTime",
    "endTime",
    "intervalMinutes",
    "maxTurns",
    "maxDailyRuns",
    "minRemainingPercent",
})
COLLABORATION_DEFAULT_PARTICIPANTS = (
    "ea_developer",
    "backtest_analyst",
    "optimization_agent",
    "manager",
)


def _collaboration_default_store() -> dict:
    return {
        "version": "agent-collaboration-store-v1",
        "config": {
            "enabled": False,
            "topic": "ช่วยกันทบทวนและเสนอวิธีพัฒนา Product ของ Metafxclub ให้ใช้งานง่าย ปลอดภัย และวัดผลได้ดีขึ้น",
            "timezone": "Asia/Bangkok",
            "startTime": "09:00",
            "endTime": "18:00",
            "intervalMinutes": 120,
            "maxTurns": 3,
            "maxDailyRuns": 3,
            "minRemainingPercent": AUTOMATION_MIN_REMAINING_PERCENT,
            "participants": list(COLLABORATION_DEFAULT_PARTICIPANTS),
            "maxParticipants": 4,
            "perTurnTimeoutSeconds": 90,
            "perTurnOutputChars": 1800,
            "targetPropId": MISSION_STRATEGY_TABLE_PROP_ID,
            "autoCreateFollowup": False,
        },
        "state": {
            "dailyRunDate": None,
            "dailyRunCount": 0,
            "lastRunAt": None,
            "lastCompletedAt": None,
            "lastStatus": "idle",
            "lastReason": None,
            "lastMeetingId": None,
            "lastMissionId": None,
        },
        "updatedAt": utc_now(),
    }


def _valid_collaboration_time(value: object) -> str | None:
    candidate = str(value or "").strip()
    if not re.fullmatch(r"(?:[01]\d|2[0-3]):[0-5]\d", candidate):
        return None
    return candidate


def _collaboration_local_now() -> datetime:
    return datetime.now(THAILAND_TIMEZONE)


def _collaboration_day_key(now_local: datetime | None = None) -> str:
    return (now_local or _collaboration_local_now()).date().isoformat()


def _collaboration_store_shape(value: object) -> dict:
    defaults = _collaboration_default_store()
    if not isinstance(value, dict):
        raise DataIntegrityError("Agent collaboration store has an invalid shape.")
    raw_config = value.get("config")
    raw_state = value.get("state")
    if not isinstance(raw_config, dict) or not isinstance(raw_state, dict):
        raise DataIntegrityError("Agent collaboration store is missing config or state.")
    config = {**defaults["config"], **raw_config}
    state = {**defaults["state"], **raw_state}
    participants = [
        item
        for item in (safe_reference(entry) for entry in (config.get("participants") or []))
        if item in EXPECTED_AGENT_IDS
    ]
    if "manager" not in participants:
        participants.append("manager")
    config["participants"] = list(dict.fromkeys(participants))[:4] or list(COLLABORATION_DEFAULT_PARTICIPANTS)
    config["timezone"] = "Asia/Bangkok"
    config["targetPropId"] = MISSION_STRATEGY_TABLE_PROP_ID
    config["autoCreateFollowup"] = False
    config["maxParticipants"] = 4
    config["perTurnTimeoutSeconds"] = clamp_int(config.get("perTurnTimeoutSeconds"), 90, 30, 120)
    config["perTurnOutputChars"] = clamp_int(config.get("perTurnOutputChars"), 1800, 800, 3000)
    config["intervalMinutes"] = clamp_int(config.get("intervalMinutes"), 120, 30, 1440)
    config["maxTurns"] = clamp_int(config.get("maxTurns"), 3, 2, 4)
    config["maxDailyRuns"] = clamp_int(config.get("maxDailyRuns"), 3, 1, 6)
    # One global automation reserve applies everywhere.  Persisted legacy
    # values above 15% must not silently pause a subsystem after the operator
    # has explicitly chosen the global "run when remaining > 15%" policy.
    config["minRemainingPercent"] = AUTOMATION_MIN_REMAINING_PERCENT
    config["enabled"] = bool(config.get("enabled", False))
    config["topic"] = redact_text(str(config.get("topic") or defaults["config"]["topic"]), 600)
    config["startTime"] = _valid_collaboration_time(config.get("startTime")) or "09:00"
    config["endTime"] = _valid_collaboration_time(config.get("endTime")) or "18:00"
    state["dailyRunCount"] = clamp_int(state.get("dailyRunCount"), 0, 0, 1000)
    for key in ("dailyRunDate", "lastRunAt", "lastCompletedAt", "lastStatus", "lastReason", "lastMeetingId", "lastMissionId"):
        if state.get(key) is not None:
            state[key] = redact_text(str(state.get(key)), 240)
    return {
        "version": "agent-collaboration-store-v1",
        "config": config,
        "state": state,
        "updatedAt": value.get("updatedAt") or defaults["updatedAt"],
    }


def load_collaboration_schedule_store() -> dict:
    with COLLABORATION_SCHEDULE_LOCK:
        if not COLLABORATION_SCHEDULE_PATH.exists():
            return _collaboration_default_store()
        return _collaboration_store_shape(read_json(COLLABORATION_SCHEDULE_PATH, {}))


def ensure_collaboration_schedule_store() -> dict:
    with COLLABORATION_SCHEDULE_LOCK:
        store = load_collaboration_schedule_store()
        if not COLLABORATION_SCHEDULE_PATH.exists():
            write_json(COLLABORATION_SCHEDULE_PATH, store)
        return store


def _save_collaboration_schedule_store(store: dict) -> dict:
    normalized = _collaboration_store_shape(store)
    normalized["updatedAt"] = utc_now()
    with COLLABORATION_SCHEDULE_LOCK:
        write_json(
            COLLABORATION_SCHEDULE_PATH,
            normalized,
            keep_backup=COLLABORATION_SCHEDULE_PATH.exists(),
        )
    return normalized


def _mutate_collaboration_schedule_store(mutator) -> dict:
    """Apply one in-process read/modify/write transaction to the schedule store."""
    with COLLABORATION_SCHEDULE_LOCK:
        if COLLABORATION_SCHEDULE_PATH.exists():
            store = _collaboration_store_shape(read_json(COLLABORATION_SCHEDULE_PATH, {}))
        else:
            store = _collaboration_default_store()
        updated = mutator(store)
        if updated is not None:
            store = updated
        normalized = _collaboration_store_shape(store)
        normalized["updatedAt"] = utc_now()
        write_json(
            COLLABORATION_SCHEDULE_PATH,
            normalized,
            keep_backup=COLLABORATION_SCHEDULE_PATH.exists(),
        )
        return normalized


def _update_collaboration_store_state(**values: object) -> dict:
    def apply_state(store: dict) -> dict:
        store["state"] = {**store["state"], **values}
        return store

    return _mutate_collaboration_schedule_store(apply_state)


def _rollover_collaboration_daily_state(store: dict, now_local: datetime | None = None) -> tuple[dict, bool]:
    current_day = _collaboration_day_key(now_local)
    state = store["state"]
    if state.get("dailyRunDate") == current_day:
        return store, False
    state["dailyRunDate"] = current_day
    state["dailyRunCount"] = 0
    return store, True


def _collaboration_inside_window(config: dict, now_local: datetime | None = None) -> bool:
    now_local = now_local or _collaboration_local_now()
    start_text = _valid_collaboration_time(config.get("startTime")) or "09:00"
    end_text = _valid_collaboration_time(config.get("endTime")) or "18:00"
    start_hour, start_minute = (int(part) for part in start_text.split(":"))
    end_hour, end_minute = (int(part) for part in end_text.split(":"))
    current = now_local.hour * 60 + now_local.minute
    start = start_hour * 60 + start_minute
    end = end_hour * 60 + end_minute
    if start == end:
        return True
    if start < end:
        return start <= current < end
    return current >= start or current < end


def _collaboration_quota_gate(
    config: dict,
    *,
    refresh: bool,
    quota: dict | None = None,
) -> dict:
    quota = (
        quota
        if isinstance(quota, dict)
        else (codex_rate_limits(force=True) if refresh else peek_codex_rate_limits())
    )
    if quota.get("ok") is not True:
        return {
            "allowed": False,
            "reason": "quota_unavailable",
            "messageTh": "พักไว้ก่อน เพราะยังอ่าน Rate Limit ของ Codex ไม่ได้",
            "remainingPercent": None,
            "quota": quota,
        }
    if quota.get("stale") is True:
        return {
            "allowed": False,
            "reason": "quota_stale",
            "messageTh": "พักไว้ก่อน เพราะข้อมูล Rate Limit เก่าเกินไป",
            "remainingPercent": None,
            "quota": quota,
        }
    if quota.get("limitReached") is True:
        return {
            "allowed": False,
            "reason": "quota_limit_reached",
            "messageTh": "พักไว้ก่อน เพราะ Codex ถึง Rate Limit แล้ว",
            "remainingPercent": 0,
            "quota": quota,
        }
    remaining_values = []
    for key in ("primary", "secondary"):
        window = quota.get(key)
        if not isinstance(window, dict):
            continue
        try:
            remaining_values.append(float(window.get("remainingPercent")))
        except (TypeError, ValueError, OverflowError):
            continue
    if not remaining_values:
        return {
            "allowed": False,
            "reason": "quota_incomplete",
            "messageTh": "พักไว้ก่อน เพราะข้อมูล Rate Limit ยังไม่ครบ",
            "remainingPercent": None,
            "quota": quota,
        }
    remaining = min(remaining_values)
    # This is one system-wide Backend policy, not a caller preference.  Keep
    # the final gate fixed as well as the persisted/read-model values so a
    # stale in-memory payload cannot silently restore an older 20-80% reserve.
    threshold = AUTOMATION_MIN_REMAINING_PERCENT
    if remaining <= threshold:
        return {
            "allowed": False,
            "reason": "quota_below_reserve",
            "messageTh": f"พักงานไว้ เพราะ Codex เหลือ {remaining:g}% และต้องเหลือมากกว่า {threshold}%",
            "remainingPercent": remaining,
            "quota": quota,
        }
    return {
        "allowed": True,
        "reason": "ready",
        "messageTh": f"Rate Limit พร้อม เหลือ {remaining:g}% ซึ่งมากกว่า {threshold}%",
        "remainingPercent": remaining,
        "quota": quota,
    }


def _collaboration_next_run_at(store: dict, now_local: datetime | None = None) -> str | None:
    config = store["config"]
    state = store["state"]
    if not config.get("enabled"):
        return None
    now_local = now_local or _collaboration_local_now()
    start_hour, start_minute = (int(part) for part in str(config.get("startTime") or "09:00").split(":"))
    candidate = now_local
    if not _collaboration_inside_window(config, now_local):
        start_today = now_local.replace(hour=start_hour, minute=start_minute, second=0, microsecond=0)
        if now_local < start_today:
            candidate = start_today
        else:
            candidate = start_today + timedelta(days=1)
    last_run = parse_iso(state.get("lastRunAt"))
    if last_run:
        interval_candidate = last_run.astimezone(THAILAND_TIMEZONE) + timedelta(
            minutes=clamp_int(config.get("intervalMinutes"), 120, 30, 1440)
        )
        if interval_candidate > candidate:
            candidate = interval_candidate
            if not _collaboration_inside_window(config, candidate):
                next_start = candidate.replace(hour=start_hour, minute=start_minute, second=0, microsecond=0)
                if candidate >= next_start:
                    next_start += timedelta(days=1)
                candidate = next_start
    return candidate.astimezone(timezone.utc).isoformat().replace("+00:00", "Z")


def _collaboration_gate(
    trigger: str,
    *,
    refresh_quota: bool,
    now_local: datetime | None = None,
) -> tuple[dict, dict]:
    now_local = now_local or _collaboration_local_now()
    with COLLABORATION_SCHEDULE_LOCK:
        store = load_collaboration_schedule_store()
        store, rolled = _rollover_collaboration_daily_state(store, now_local)
        if rolled and COLLABORATION_SCHEDULE_PATH.exists():
            store = _save_collaboration_schedule_store(store)
    config = store["config"]
    state = store["state"]
    with COLLABORATION_STATE_LOCK:
        runtime_state = dict(COLLABORATION_STATE)
    if runtime_state.get("status") in {"starting", "running"}:
        return store, {"allowed": False, "reason": "already_running", "messageTh": "Agent กำลังประชุมกันอยู่"}
    if load_operator_mode_record().get("mode") != "auto_guarded":
        return store, {"allowed": False, "reason": "full_access_required", "messageTh": "ต้องเปิด Full Access ก่อนจึงจะปล่อยให้ Agent ประชุมอัตโนมัติได้"}
    if contains_potential_secret(config.get("topic")):
        return store, {"allowed": False, "reason": "potential_secret", "messageTh": "หัวข้อประชุมมีข้อมูลที่อาจเป็นความลับ กรุณาแก้หัวข้อก่อน"}
    if trigger == "schedule" and not config.get("enabled"):
        return store, {"allowed": False, "reason": "disabled", "messageTh": "ปิดการประชุมอัตโนมัติอยู่"}
    if trigger == "schedule" and not _collaboration_inside_window(config, now_local):
        return store, {"allowed": False, "reason": "outside_time_window", "messageTh": "ยังไม่ถึงช่วงเวลาที่อนุญาตให้ Agent ประชุม"}
    if state.get("dailyRunCount", 0) >= config.get("maxDailyRuns", 3):
        return store, {"allowed": False, "reason": "daily_cap_reached", "messageTh": "ครบจำนวนการประชุมสูงสุดของวันนี้แล้ว"}
    last_run = parse_iso(state.get("lastRunAt"))
    if last_run:
        elapsed_seconds = max(0.0, (datetime.now(timezone.utc) - last_run.astimezone(timezone.utc)).total_seconds())
        minimum_gap = config.get("intervalMinutes", 120) * 60 if trigger == "schedule" else 5 * 60
        if elapsed_seconds < minimum_gap:
            return store, {
                "allowed": False,
                "reason": "cooldown",
                "messageTh": "ยังอยู่ในช่วงพักเพื่อลดการใช้ Rate Limit",
                "retryAfterSeconds": int(minimum_gap - elapsed_seconds),
            }
    quota_gate = _collaboration_quota_gate(config, refresh=refresh_quota)
    if not quota_gate.get("allowed"):
        return store, quota_gate
    if not CODEX_RUNNER_PYTHON.is_file() or not CODEX_RUNNER_SCRIPT.is_file():
        return store, {"allowed": False, "reason": "runner_unavailable", "messageTh": "Codex Runner ยังไม่พร้อมสำหรับการประชุม"}
    return store, quota_gate


def collaboration_schedule_read_model() -> dict:
    store = load_collaboration_schedule_store()
    now_local = _collaboration_local_now()
    store, _ = _rollover_collaboration_daily_state(store, now_local)
    config = store["config"]
    state = store["state"]
    _, gate = _collaboration_gate("schedule", refresh_quota=False, now_local=now_local)
    with COLLABORATION_STATE_LOCK:
        runtime_state = dict(COLLABORATION_STATE)
    runtime_status = str(runtime_state.get("status") or "")
    status = runtime_status if runtime_status in {"starting", "running"} else (
        "scheduled" if config.get("enabled") and gate.get("allowed") else (
            "paused" if config.get("enabled") else "disabled"
        )
    )
    return {
        "ok": True,
        "version": "agent-collaboration-read-model-v1",
        "status": status,
        "enabled": bool(config.get("enabled")),
        "topic": redact_text(str(config.get("topic") or ""), 600),
        "timezone": "Asia/Bangkok",
        "startTime": config.get("startTime"),
        "endTime": config.get("endTime"),
        "intervalMinutes": config.get("intervalMinutes"),
        "maxTurns": config.get("maxTurns"),
        "maxDailyRuns": config.get("maxDailyRuns"),
        "dailyRunCount": state.get("dailyRunCount", 0),
        "minRemainingPercent": config.get("minRemainingPercent"),
        "participants": [
            item for item in config.get("participants", [])
            if item in EXPECTED_AGENT_IDS
        ],
        "targetPropId": MISSION_STRATEGY_TABLE_PROP_ID,
        "nextRunAt": _collaboration_next_run_at(store, now_local),
        "pausedReason": None if gate.get("allowed") else gate.get("reason"),
        "messageTh": "พร้อมเริ่มประชุมตามเวลา" if gate.get("allowed") else gate.get("messageTh"),
        "remainingPercent": gate.get("remainingPercent"),
        "lastRunAt": state.get("lastRunAt"),
        "lastCompletedAt": state.get("lastCompletedAt"),
        "lastStatus": state.get("lastStatus"),
        "lastMeetingId": safe_reference(state.get("lastMeetingId")),
        "lastMissionId": safe_reference(state.get("lastMissionId")),
        "activeMeetingId": safe_reference(runtime_state.get("activeMeetingId")),
        "activeMissionId": safe_reference(runtime_state.get("activeMissionId")),
        "updatedAt": store.get("updatedAt"),
        "guardrails": {
            "toolsEnabledDuringMeeting": False,
            "autoCreateFollowup": False,
            "freshRateLimitRequired": True,
            "fullAccessRequired": True,
            "externalActionsAllowed": False,
        },
    }


def set_collaboration_schedule(payload: dict) -> dict:
    if not isinstance(payload, dict) or not payload or not set(payload).issubset(COLLABORATION_CONFIG_FIELDS):
        return {
            "ok": False,
            "kind": "invalid_collaboration_schedule_request",
            "messageTh": "รับเฉพาะการเปิดใช้งาน หัวข้อ ช่วงเวลา ความถี่ จำนวนรอบ และโควตาสำรอง",
            "_httpStatus": 422,
        }
    integer_rules = {
        "intervalMinutes": (30, 1440),
        "maxTurns": (2, 4),
        "maxDailyRuns": (1, 6),
        "minRemainingPercent": (
            AUTOMATION_MIN_REMAINING_PERCENT,
            AUTOMATION_MIN_REMAINING_PERCENT,
        ),
    }
    validated: dict[str, object] = {}
    if "enabled" in payload:
        if not isinstance(payload.get("enabled"), bool):
            return {"ok": False, "kind": "invalid_enabled", "messageTh": "สถานะเปิดใช้งานต้องเป็น true หรือ false", "_httpStatus": 422}
        validated["enabled"] = payload["enabled"]
    if "topic" in payload:
        if not isinstance(payload.get("topic"), str):
            return {"ok": False, "kind": "invalid_topic", "messageTh": "หัวข้อประชุมต้องเป็นข้อความ", "_httpStatus": 422}
        topic = payload["topic"].strip()
        if not 10 <= len(topic) <= 600 or contains_potential_secret(topic):
            return {"ok": False, "kind": "invalid_topic", "messageTh": "หัวข้อต้องยาว 10-600 ตัวอักษรและไม่มีข้อมูลลับ", "_httpStatus": 422}
        validated["topic"] = topic
    for field in ("startTime", "endTime"):
        if field not in payload:
            continue
        value = _valid_collaboration_time(payload.get(field))
        if not value:
            return {"ok": False, "kind": "invalid_time", "messageTh": "เวลาใช้รูปแบบ HH:MM เท่านั้น", "_httpStatus": 422}
        validated[field] = value
    for field, (minimum, maximum) in integer_rules.items():
        if field not in payload:
            continue
        value = payload.get(field)
        if isinstance(value, bool) or not isinstance(value, int) or not minimum <= value <= maximum:
            return {
                "ok": False,
                "kind": f"invalid_{field}",
                "messageTh": f"ค่า {field} ต้องเป็นจำนวนเต็มระหว่าง {minimum}-{maximum}",
                "_httpStatus": 422,
            }
        validated[field] = value

    def apply_config(store: dict) -> dict:
        store["config"] = {**store["config"], **validated}
        return store

    store = _mutate_collaboration_schedule_store(apply_config)
    config = store["config"]
    append_audit({
        "type": "collaboration.schedule_changed",
        "enabled": config.get("enabled"),
        "topicDigest": payload_digest(str(config.get("topic") or ""))[:16],
        "startTime": config.get("startTime"),
        "endTime": config.get("endTime"),
        "intervalMinutes": config.get("intervalMinutes"),
        "maxTurns": config.get("maxTurns"),
        "maxDailyRuns": config.get("maxDailyRuns"),
        "minRemainingPercent": config.get("minRemainingPercent"),
    })
    COLLABORATION_SCHEDULER_WAKE.set()
    return {"ok": True, "kind": "collaboration_schedule", "collaboration": collaboration_schedule_read_model()}


def _high_impact_reasons(tool_id: str, detail: str, risk: str) -> list[str]:
    policy = operator_mode_policy()
    reasons: list[str] = []
    gated_tools = {
        str(item)
        for item in (policy.get("alwaysRequireHumanApprovalTools") or [])
        if str(item).strip()
    }
    if tool_id in gated_tools:
        reasons.append(f"tool:{tool_id}")
    blocked_keywords = [
        str(item).strip().lower()
        for item in (policy.get("blockedIntentKeywords") or [])
        if str(item).strip()
    ]
    lower_detail = str(detail or "").lower()
    for keyword in blocked_keywords:
        if keyword_matches(lower_detail, keyword):
            reasons.append(f"intent:{keyword}")
    for label, pattern in HIGH_IMPACT_INTENT_PATTERNS:
        if pattern.search(str(detail or "")):
            reasons.append(f"intent_pattern:{label}")
    if str(risk or "").lower() == "high":
        reasons.append("risk:high")
    if contains_potential_secret(detail):
        reasons.append("potential_secret")
    return list(dict.fromkeys(reasons))


AUTO_SAFE_WORKFLOW_EXECUTION_SCOPES = frozenset({
    "public_web_read_only",
    "workspace_analysis_only",
    "analysis_plan_only",
    "workspace_source_only",
    "local_read_only",
})
EA_FACTORY_BACKEND_AUTO_STAGE_ACTIONS = {
    "build_strategy_code": "generate_source",
    "review_source_code": "source_review",
}
TRUSTED_PUBLIC_READ_ONLY_WORKFLOWS = frozenset({
    ("codex_mcp_portal", "discover_trading_systems"),
    ("left_server_racks", "deep_research_system"),
    ("left_audit_crystals", "discover_new_indicators"),
})
PUBLIC_READ_ONLY_SCOPE_ERROR = (
    "Public research accepts only read-only searches of public web pages. "
    "Remove requests to trade, deploy, send, publish, authenticate, download/install, "
    "execute code, or change files/systems; no Mission was created."
)


def _is_trusted_public_read_only_workflow(
    prop_id: object,
    action_id: object,
    *,
    tool_id: object | None = None,
    owner_agent_id: object | None = None,
) -> bool:
    identity = (str(prop_id or ""), str(action_id or ""))
    if identity not in TRUSTED_PUBLIC_READ_ONLY_WORKFLOWS:
        return False
    action = DASHBOARD_WORKFLOW_ACTIONS.get(identity[1])
    if (
        not isinstance(action, dict)
        or action.get("propId") != identity[0]
        or action.get("analysisOnly") is not True
        or action.get("executionScope") != "public_web_read_only"
        or action.get("toolId") != "codex_web_research"
    ):
        return False
    if tool_id is not None and str(tool_id or "") != str(action.get("toolId") or ""):
        return False
    if (
        owner_agent_id is not None
        and str(owner_agent_id or "") != str(action.get("ownerAgentId") or "")
    ):
        return False
    return True


def _public_read_only_intent_reasons(tool_id: object, detail: object) -> list[str]:
    text = str(detail or "")
    reasons = _high_impact_reasons(str(tool_id or ""), text, "low")
    for label, pattern in PUBLIC_READ_ONLY_OUT_OF_SCOPE_INTENT_PATTERNS:
        if pattern.search(text):
            reasons.append(f"public_read_only_scope:{label}")
    return list(dict.fromkeys(reasons))


def _trusted_backend_ea_factory_stage_guard_intent(context: object) -> str | None:
    """Recognize only the two Backend-bound, source-only EA Factory stages.

    ``advance_ea_factory_build`` constructs these forms after the operator has
    explicitly pressed the stage button. Their immutable safety prose contains
    words such as ``deploy`` and ``trade`` in a negative sentence. Feeding that
    Backend prose back into the generic high-impact keyword scanner creates a
    false approval gate. This helper accepts the empty user-intent projection
    only when every Factory marker, source binding, action and trigger matches.
    Frontend workflow requests can never opt into this private Backend trigger.
    """

    if not isinstance(context, dict):
        return None
    prop_id = str(context.get("propId") or "")
    action_id = str(context.get("actionId") or "")
    stage_id = EA_FACTORY_BACKEND_AUTO_STAGE_ACTIONS.get(action_id)
    if (
        prop_id != "right_server_racks"
        or not stage_id
        or context.get("triggerSource") != "backend"
    ):
        return None
    action = DASHBOARD_WORKFLOW_ACTIONS.get(action_id)
    expected_scope = (
        "workspace_source_only"
        if stage_id == "generate_source"
        else "workspace_analysis_only"
    )
    if (
        not isinstance(action, dict)
        or action.get("propId") != prop_id
        or action.get("analysisOnly") is not True
        or action.get("executionScope") != expected_scope
        or action.get("toolId") != "codex_cli_task"
        or action.get("ownerAgentId") != "ea_developer"
    ):
        return None
    inputs = context.get("inputs") if isinstance(context.get("inputs"), dict) else {}
    if set(inputs) != {"sourceReportId", "platform", "brief"}:
        return None
    source_report_id = safe_reference(inputs.get("sourceReportId"))
    platform = str(inputs.get("platform") or "")
    brief = str(inputs.get("brief") or "")
    source = context.get("source") if isinstance(context.get("source"), dict) else {}
    if (
        not source_report_id
        or source.get("reportId") != source_report_id
        or platform not in EA_FACTORY_PLATFORMS
        or not brief
        or len(brief) > 2400
    ):
        return None
    build_match = re.match(r"^\[EA_FACTORY_BUILD_ID:(ea-build-[A-Za-z0-9_-]+)\]", brief)
    if not build_match:
        return None
    build_id = safe_reference(build_match.group(1))
    if (
        not build_id
        or f"[EA_FACTORY_PLATFORM:{platform}]" not in brief
        or f"ea-factory/{build_id}/Source/strategy-spec-v01.json" not in brief
    ):
        return None
    digest_markers = (
        "EA_FACTORY_SOURCE_RECORD_DIGEST",
        "EA_FACTORY_STRATEGY_SPEC_DIGEST",
    )
    if any(
        re.search(rf"\[{marker}:[0-9a-f]{{64}}\]", brief) is None
        for marker in digest_markers
    ):
        return None
    if stage_id == "generate_source":
        if (
            f"[EA_FACTORY_SOURCE_REPORT_ID:{source_report_id}]" not in brief
            or re.search(r"\[EA_FACTORY_SOURCE_RECORD_ID:[A-Za-z0-9_-]+\]", brief) is None
            or brief.count("[USER_BUILD_REQUIREMENTS]") != 1
            or brief.count("[/USER_BUILD_REQUIREMENTS]") != 1
            or "SOURCE-ONLY/UNCOMPILED" not in brief
        ):
            return None
    else:
        if (
            f"[EA_FACTORY_GENERATION_REPORT_ID:{source_report_id}]" not in brief
            or re.search(
                r"\[EA_FACTORY_IMMUTABLE_DIGESTS:[0-9a-f]{64}(?:,[0-9a-f]{64})*\]",
                brief,
            )
            is None
            or "Do not change files" not in brief
        ):
            return None
    return "{}"


def _trusted_backend_ea_factory_worker_sandbox(
    mission: object,
) -> dict | None:
    """Derive one fail-closed worker sandbox from exact Factory lineage."""

    if not isinstance(mission, dict):
        return None
    context = _workflow_context_storage(mission.get("workflowContext"))
    if (
        not context
        or _trusted_backend_ea_factory_stage_guard_intent(context) != "{}"
        or _trusted_workflow_guard_intent(mission) != "{}"
    ):
        return None
    action_id = str(context.get("actionId") or "")
    stage_id = EA_FACTORY_BACKEND_AUTO_STAGE_ACTIONS.get(action_id)
    inputs = context.get("inputs") if isinstance(context.get("inputs"), dict) else {}
    brief = str(inputs.get("brief") or "")
    build_match = re.match(
        r"^\[EA_FACTORY_BUILD_ID:(ea-build-[A-Za-z0-9_-]+)\]",
        brief,
    )
    build_id = safe_reference(build_match.group(1)) if build_match else None
    if (
        not stage_id
        or not build_id
        or brief.count("[EA_FACTORY_BUILD_ID:") != 1
    ):
        return None
    if stage_id == "source_review":
        return {
            "buildId": build_id,
            "stageId": stage_id,
            "readOnly": True,
            "writeRoots": [],
            "scopedWorkspaceWriteRoot": None,
        }
    if stage_id == "generate_source":
        scoped_root = f"ea-factory/{build_id}/Source"
        return {
            "buildId": build_id,
            "stageId": stage_id,
            # Codex itself remains read-only.  The trusted Runner validates
            # the structured fileName/content result and is the sole writer
            # inside this one Build's Source folder.
            "readOnly": True,
            "writeRoots": [scoped_root],
            "scopedWorkspaceWriteRoot": scoped_root,
            "resultProfile": EA_FACTORY_SOURCE_RESULT_PROFILE,
            "structuredWriterVersion": (
                EA_FACTORY_STRUCTURED_SOURCE_WRITER_VERSION
            ),
        }
    return None


def _ea_factory_structured_source_writer_capability(
    value: object,
) -> dict | None:
    """Project only the exact trusted Runner source-writer capability.

    A version string alone is not sufficient: recovery may proceed only when
    the Runner advertises the read-only Codex sandbox, atomic materializer,
    strict result profile and the complete output/evidence contract.
    """

    expected = {
        "version": EA_FACTORY_STRUCTURED_SOURCE_WRITER_VERSION,
        "resultProfile": EA_FACTORY_SOURCE_RESULT_PROFILE,
        "codexSandbox": "read-only",
        "atomicWriter": True,
        "outputFields": list(EA_FACTORY_STRUCTURED_SOURCE_OUTPUT_FIELDS),
        "evidenceKinds": list(EA_FACTORY_STRUCTURED_SOURCE_EVIDENCE_KINDS),
    }
    return copy.deepcopy(expected) if value == expected else None


def _ea_factory_structured_source_writer_ready(value: object) -> bool:
    row = value if isinstance(value, dict) else {}
    return bool(
        row.get("status") in {"ready", "ready_guarded"}
        and row.get("stale") is not True
        and row.get("refreshInProgress") is not True
        and _ea_factory_structured_source_writer_capability(
            row.get("eaFactorySourceWriter")
        )
        is not None
    )


def _trusted_workflow_guard_intent(mission: object) -> str | None:
    """Return only user-controlled intent for a trusted bounded workflow.

    Generated workflow prompts deliberately contain phrases such as "do not
    deploy" and "never expose a token". Scanning that immutable safety text as
    user intent creates false high-risk gates. The Backend may isolate inputs
    only after every lineage binding and the input digest are revalidated.
    Any mismatch returns ``None`` and restores the conservative full-prompt
    scan.
    """

    if not isinstance(mission, dict):
        return None
    context = _workflow_context_storage(mission.get("workflowContext"))
    if not context:
        return None
    prop_id = str(context.get("propId") or "")
    action_id = str(context.get("actionId") or "")
    action = DASHBOARD_WORKFLOW_ACTIONS.get(action_id)
    if (
        not isinstance(action, dict)
        or action.get("propId") != prop_id
        or action.get("analysisOnly") is not True
        or str(action.get("executionScope") or "")
        not in AUTO_SAFE_WORKFLOW_EXECUTION_SCOPES
        or str(action.get("toolId") or "") != str(mission.get("toolId") or "")
        or str(action.get("ownerAgentId") or "")
        != str(mission.get("owner") or mission.get("agentId") or "")
    ):
        return None
    inputs = context.get("inputs") if isinstance(context.get("inputs"), dict) else {}
    user_editable_fields = {
        str(field.get("id") or "")
        for field in (action.get("formFields") or ())
        if isinstance(field, dict) and str(field.get("id") or "")
    }
    plugin_profile = _trusted_workflow_plugin_profile(prop_id, action_id, inputs)
    if plugin_profile.get("contractVersion") == "unavailable":
        return None
    stored_procedure = (
        context.get("pluginProcedure")
        if isinstance(context.get("pluginProcedure"), dict)
        else {}
    )
    for binding in (
        "contractVersion",
        "pluginSkillId",
        "pluginVersion",
        "procedureKind",
        "pluginInvocationMode",
        "selectedBy",
        "selectedValue",
    ):
        if stored_procedure.get(binding) != plugin_profile.get(binding):
            return None
    preset = (
        sanitize_json_value(plugin_profile.get("inputPreset"))
        if isinstance(plugin_profile.get("inputPreset"), dict)
        else {}
    )
    if not isinstance(preset, dict):
        return None
    allowed_input_fields = user_editable_fields | set(preset)
    if set(inputs) - allowed_input_fields:
        return None
    # Backend-only preset fields must remain present and byte-for-byte equal.
    # A preset that is also a form field may be overridden by the user; only
    # that differing value is user intent and is scanned by the impact guard.
    for field_id, preset_value in preset.items():
        if field_id not in user_editable_fields and inputs.get(field_id) != preset_value:
            return None
    expected_digest = payload_digest(
        "dashboard-workflow-input-v1",
        prop_id,
        action_id,
        json.dumps(inputs, ensure_ascii=False, sort_keys=True),
    )
    stored_digest = str(context.get("inputDigest") or "")
    if not stored_digest or not secrets.compare_digest(stored_digest, expected_digest):
        return None
    ea_factory_intent = _trusted_backend_ea_factory_stage_guard_intent(context)
    if ea_factory_intent is not None:
        return ea_factory_intent
    if action_id == "deep_research_system":
        selected_record_id = safe_reference(inputs.get("sourceRecordId"))
        source = context.get("source") if isinstance(context.get("source"), dict) else {}
        if (
            not selected_record_id
            or source.get("recordId") != selected_record_id
            or safe_reference(inputs.get("sourceReportId")) != source.get("reportId")
        ):
            return None
    user_intent = {
        field_id: inputs[field_id]
        for field_id in user_editable_fields
        if field_id in inputs
        and (field_id not in preset or inputs[field_id] != preset[field_id])
    }
    return json.dumps(user_intent, ensure_ascii=False, sort_keys=True)


def auto_guarded_eligibility(
    mission: dict,
    *,
    require_operator_mode: bool = True,
    allow_legacy_radar_without_reservation: bool = False,
) -> dict:
    policy = operator_mode_policy()
    operator = load_operator_mode_record()
    tool_id = str(mission.get("toolId") or "")
    agent_id = str(mission.get("owner") or mission.get("agentId") or "")
    risk = str(mission.get("risk") or "medium").lower()
    detail = str(mission.get("detail") or mission.get("prompt") or "")
    trusted_workflow_intent = _trusted_workflow_guard_intent(mission)
    guard_intent = (
        trusted_workflow_intent
        if trusted_workflow_intent is not None
        else detail
    )
    tool_policy = get_tool_policy(tool_id) or {}
    reasons: list[str] = []
    if require_operator_mode and operator.get("mode") != "auto_guarded":
        reasons.append("operator_mode_manual")
    allowlist = {
        str(item)
        for item in (policy.get("autoEligibleTools") or ["codex_cli_task"])
        if str(item).strip()
    }
    if tool_id not in allowlist:
        reasons.append("tool_not_allowlisted")
    if not bool(tool_policy.get("autoRunnable", False)):
        reasons.append("tool_contract_auto_run_disabled")
    max_risk = str(policy.get("maxRisk") or "medium").lower()
    risk_order = {"low": 0, "medium": 1, "high": 2}
    if risk_order.get(risk, 2) > risk_order.get(max_risk, 1):
        reasons.append("risk_above_auto_limit")
    allowed_modes = {
        str(item)
        for item in (policy.get("allowedToolModes") or ["read_only_diagnostic"])
        if str(item).strip()
    }
    if str(tool_policy.get("defaultMode") or "") not in allowed_modes:
        reasons.append("tool_mode_not_allowlisted")
    adapter_status = str(tool_policy.get("adapterStatus") or "unimplemented").lower()
    if not adapter_status.startswith("implemented"):
        reasons.append("adapter_not_implemented")
    if not bool(tool_policy.get("realExecutionAvailable", False)):
        reasons.append("real_execution_unavailable")
    workflow_context = _workflow_context_storage(mission.get("workflowContext"))
    trusted_radar_workflow = bool(
        trusted_workflow_intent is not None
        and workflow_context
        and workflow_context.get("propId") == "left_audit_crystals"
        and workflow_context.get("actionId") == "discover_new_indicators"
    )
    if (
        trusted_radar_workflow
        and not isinstance(workflow_context.get("executionReservation"), dict)
        and not allow_legacy_radar_without_reservation
    ):
        reasons.append("radar_execution_reservation_missing")
    permission = evaluate_tool_permission(agent_id, tool_id)
    if not permission.get("allowed"):
        reasons.append(str(permission.get("reason") or "permission_denied"))
    analysis_context = (
        mission.get("analysisContext")
        if isinstance(mission.get("analysisContext"), dict)
        else {}
    )
    council_context_valid = (
        analysis_context.get("kind") == "ai_trade_council_vote"
        and analysis_context.get("agentId") == agent_id
        and analysis_context.get("roleId") == AI_TRADE_COUNCIL_AGENT_ROLES.get(agent_id)
        and tool_id == AI_TRADE_COUNCIL_ALLOWED_TOOLS.get(agent_id)
        and re.fullmatch(r"[0-9a-f]{64}", str(analysis_context.get("snapshotId") or "")) is not None
        and re.fullmatch(
            r"[0-9a-f]{64}",
            str(analysis_context.get("snapshotArtifactDigest") or ""),
        )
        is not None
        and analysis_context.get("snapshotArtifact")
        == ai_trade_council_snapshot_reference(
            str(analysis_context.get("snapshotId") or ""),
            str(analysis_context.get("snapshotArtifactDigest") or ""),
        )
        and analysis_context.get("readOnly") is True
    )
    reasons.extend(
        _ai_trade_council_high_impact_reasons(tool_id, detail)
        if council_context_valid
        else _high_impact_reasons(tool_id, guard_intent, risk)
    )
    return {
        "eligible": not reasons,
        "mode": "auto_guarded" if not reasons else "manual_guarded",
        "reasons": list(dict.fromkeys(reasons)),
    }


def backend_auto_guard_review(mission: dict, approval: dict) -> tuple[str, str]:
    """Approve only a digest-bound, allowlisted local mission in operator auto mode."""
    expected_digest = str(approval.get("payloadDigest") or "")
    actual_digest = mission_payload_digest(mission)
    eligibility = auto_guarded_eligibility(mission, require_operator_mode=True)
    if not expected_digest or not secrets.compare_digest(expected_digest, actual_digest):
        decision, reason = "rejected", "mission_digest_mismatch"
    elif not eligibility.get("eligible"):
        decision = "rejected"
        reason = str((eligibility.get("reasons") or ["auto_guard_policy_denied"])[0])
    else:
        decision, reason = "approved", "backend_auto_review_allowlisted_local_workspace"
    reviewed_at = utc_now()
    decisions = [
        item
        for item in (approval.get("decisions") or [])
        if isinstance(item, dict) and item.get("actorId") != "risk_guard"
    ]
    decisions.append({
        "actorId": "risk_guard",
        "actorProvenance": "backend_auto_review",
        "decision": decision,
        "note": reason,
        "time": reviewed_at,
        "payloadDigest": expected_digest,
        "ruleVersion": "auto-guard-v1",
    })
    approval["decisions"] = decisions
    mission["riskGuardReview"] = {
        "decision": decision,
        "reason": reason,
        "ruleVersion": "auto-guard-v1",
        "payloadDigest": expected_digest,
        "reviewedAt": reviewed_at,
    }
    append_audit({
        "type": "mission.auto_guard_review",
        "missionId": mission.get("id"),
        "approvalId": approval.get("id"),
        "actorId": "risk_guard",
        "actorProvenance": "backend_auto_review",
        "decision": decision,
        "reason": reason,
        "payloadDigest": expected_digest,
    })
    return decision, reason


def load_report_contract() -> dict:
    return read_json(REPORT_CONTRACT_PATH, {"report_targets": {}})


def load_agent_contracts() -> list[dict]:
    payload = read_json(AGENTS_PATH, {"agents": []})
    return [item for item in payload.get("agents", []) if isinstance(item, dict)]


def get_tool_policy(tool_id: str) -> dict | None:
    tools = load_tool_permissions().get("tools", [])
    return next((item for item in tools if isinstance(item, dict) and item.get("id") == tool_id), None)


def evaluate_tool_permission(agent_id: str, tool_id: str) -> dict:
    agent_ids = {str(item.get("id")) for item in load_agent_contracts()}
    if agent_id not in agent_ids:
        return {"allowed": False, "reason": "unknown_agent", "message": "Unknown agent id."}
    policy = get_tool_policy(tool_id)
    if not policy:
        return {"allowed": False, "reason": "unknown_tool", "message": "Unknown tools are denied by default."}
    allowed_agents = policy.get("allowedAgents") if isinstance(policy.get("allowedAgents"), list) else []
    if agent_id not in allowed_agents:
        return {"allowed": False, "reason": "agent_not_allowed", "message": f"Agent {agent_id} is not permitted to use {tool_id}."}
    return {"allowed": True, "reason": "allowed", "policy": policy}


def tool_execution_capability_unavailable(policy: object) -> bool:
    if not isinstance(policy, dict):
        return True
    adapter_status = str(policy.get("adapterStatus") or "").strip().lower()
    unavailable_markers = ("missing", "unimplemented", "not_implemented", "disabled", "coming_soon")
    return (
        policy.get("realExecutionAvailable") is not True
        and any(marker in adapter_status for marker in unavailable_markers)
    )


def mark_mission_capability_unavailable(mission: dict, tool_policy: dict) -> dict:
    tool_id = str(mission.get("toolId") or "unknown_tool")
    adapter_status = str(tool_policy.get("adapterStatus") or "adapter_missing")
    completed_at = utc_now()
    mission["status"] = "blocked"
    mission["phase"] = "capability_unavailable"
    mission["workStatus"] = "blocked"
    mission["errorCode"] = "capability_unavailable"
    mission["result"] = (
        f"{tool_id} ยังไม่มี Adapter สำหรับงานจริง ({adapter_status}) "
        "การอนุมัติหรือ Full Access ไม่สามารถปลดล็อกความสามารถนี้ได้"
    )
    mission["updatedAt"] = completed_at
    mission["completedAt"] = completed_at
    replace_mission(mission)
    append_audit({
        "type": "adapter.capability_unavailable",
        "missionId": mission.get("id"),
        "ownerAgentId": mission.get("owner"),
        "toolId": tool_id,
        "adapterStatus": adapter_status,
        "approvalRequested": False,
        "realToolExecuted": False,
    })
    return mission


def role_default_model_tier(agent_id: str) -> str:
    if agent_id in {"manager", "ceo"}:
        return "manager_quality"
    if agent_id == "risk_guard":
        return "risk_quality"
    if agent_id in {"ea_developer", "backtest_analyst", "optimization_agent"}:
        return "specialist_balanced"
    return "specialist_fast"


def resolve_model_tier(
    agent_id: str,
    requested_tier: str | None = None,
    tool_policy: dict | None = None,
    allow_requested: bool = False,
) -> tuple[str, dict]:
    contract = load_orchestration_contract()
    tiers = contract.get("modelTiers") if isinstance(contract.get("modelTiers"), dict) else {}
    policy_tier = str((tool_policy or {}).get("modelTier") or "")
    tier_id = policy_tier if policy_tier and policy_tier != "role_default" else role_default_model_tier(agent_id)
    if allow_requested and requested_tier and requested_tier in tiers:
        tier_id = requested_tier
    if tier_id not in tiers:
        tier_id = "specialist_fast" if "specialist_fast" in tiers else next(iter(tiers), "specialist_fast")
    tier = tiers.get(tier_id) if isinstance(tiers.get(tier_id), dict) else {}
    return tier_id, tier


def resolve_budget(
    payload: dict,
    agent_id: str,
    tool_policy: dict | None = None,
    allow_model_override: bool = False,
    allow_budget_override: bool = False,
) -> tuple[str, dict]:
    tier_id, tier = resolve_model_tier(agent_id, payload.get("modelTier"), tool_policy, allow_model_override)
    contract = load_orchestration_contract()
    guard = contract.get("costRateGuard") if isinstance(contract.get("costRateGuard"), dict) else {}
    hard_timeout = guard.get("hardTimeoutSeconds") if isinstance(guard.get("hardTimeoutSeconds"), dict) else {}
    minimum = clamp_int(hard_timeout.get("min"), 15, 1, 600)
    maximum = clamp_int(hard_timeout.get("max"), 600, minimum, 3600)
    default_timeout = clamp_int(tier.get("maxSeconds"), 120, minimum, maximum)
    hard_output = clamp_int(guard.get("hardOutputChars"), 20000, 1000, 100000)
    default_output = clamp_int(tier.get("maxOutputChars"), 7000, 1000, hard_output)
    budget_payload = payload.get("budget") if allow_budget_override and isinstance(payload.get("budget"), dict) else {}
    requested_timeout = payload.get("timeout") if allow_budget_override else None
    budget = {
        "timeoutSeconds": clamp_int(requested_timeout if requested_timeout is not None else budget_payload.get("timeoutSeconds"), default_timeout, minimum, maximum),
        "outputLimitChars": clamp_int(budget_payload.get("outputLimitChars"), default_output, 1000, hard_output),
        "maxRuns": 1,
    }
    if allow_budget_override:
        # Codex CLI does not currently expose an enforceable token ceiling.  Keep
        # the requested value as an audited advisory budget, while timeout and
        # outputLimitChars remain hard Backend-enforced limits.
        budget["tokenBudget"] = clamp_int(budget_payload.get("tokenBudget"), 12000, 256, 100000)
        budget["tokenBudgetMode"] = "advisory"
        budget["rateReservePercent"] = AUTOMATION_MIN_REMAINING_PERCENT
    return tier_id, budget


def _persisted_rate_limit_path() -> Path:
    """Keep cost-guard evidence beside the mission store used by this Bridge."""
    return MISSIONS_PATH.parent / "local-rate-limit-state.json"


def _load_persisted_rate_limits_unlocked() -> dict[str, list[float]]:
    path = _persisted_rate_limit_path()
    data = read_json(
        path,
        {"schemaVersion": PERSISTED_RATE_LIMIT_SCHEMA, "buckets": {}},
    )
    if (
        not isinstance(data, dict)
        or data.get("schemaVersion") != PERSISTED_RATE_LIMIT_SCHEMA
        or not isinstance(data.get("buckets"), dict)
    ):
        raise DataIntegrityError("Local rate-limit state has an invalid schema.")
    buckets: dict[str, list[float]] = {}
    for raw_key, raw_rows in data["buckets"].items():
        if (
            not isinstance(raw_key, str)
            or not raw_key.startswith(PERSISTED_RATE_LIMIT_PREFIXES)
            or len(raw_key) > 240
            or not isinstance(raw_rows, list)
        ):
            raise DataIntegrityError("Local rate-limit state contains an invalid bucket.")
        rows: list[float] = []
        for raw_stamp in raw_rows:
            if (
                isinstance(raw_stamp, bool)
                or not isinstance(raw_stamp, (int, float))
                or not math.isfinite(float(raw_stamp))
                or float(raw_stamp) <= 0
            ):
                raise DataIntegrityError("Local rate-limit state contains an invalid timestamp.")
            rows.append(float(raw_stamp))
        buckets[raw_key] = rows
    return buckets


def _save_persisted_rate_limits_unlocked(buckets: dict[str, list[float]]) -> None:
    write_json(
        _persisted_rate_limit_path(),
        {
            "schemaVersion": PERSISTED_RATE_LIMIT_SCHEMA,
            "updatedAt": utc_now(),
            "buckets": {
                key: list(rows)
                for key, rows in sorted(buckets.items())
                if key.startswith(PERSISTED_RATE_LIMIT_PREFIXES) and rows
            },
        },
        keep_backup=True,
    )


def check_rate_limit(key: str, max_per_hour: int, cooldown_seconds: int = 0, consume: bool = True) -> tuple[bool, int]:
    now = time.time()
    with RATE_LIMIT_LOCK:
        persisted = key.startswith(PERSISTED_RATE_LIMIT_PREFIXES)
        persisted_buckets = _load_persisted_rate_limits_unlocked() if persisted else {}
        combined_rows = [
            *persisted_buckets.get(key, []),
            *RATE_LIMIT_STATE.get(key, []),
        ]
        # The in-memory row is also present in the durable store after a consume.
        # De-duplicate exact timestamps so one run is never counted twice.
        rows = sorted({
            float(stamp)
            for stamp in combined_rows
            if now - float(stamp) < 3600
        })
        if rows and cooldown_seconds > 0 and now - rows[-1] < cooldown_seconds:
            retry_after = max(1, int(cooldown_seconds - (now - rows[-1]) + 0.999))
            RATE_LIMIT_STATE[key] = rows
            if persisted:
                persisted_buckets[key] = rows
                _save_persisted_rate_limits_unlocked(persisted_buckets)
            return False, retry_after
        if len(rows) >= max(1, max_per_hour):
            retry_after = max(1, int(3600 - (now - rows[0]) + 0.999))
            RATE_LIMIT_STATE[key] = rows
            if persisted:
                persisted_buckets[key] = rows
                _save_persisted_rate_limits_unlocked(persisted_buckets)
            return False, retry_after
        if consume:
            rows.append(now)
            RATE_LIMIT_STATE[key] = rows
        elif rows:
            RATE_LIMIT_STATE[key] = rows
        else:
            RATE_LIMIT_STATE.pop(key, None)
        if persisted:
            if rows:
                persisted_buckets[key] = rows
            else:
                persisted_buckets.pop(key, None)
            _save_persisted_rate_limits_unlocked(persisted_buckets)
    return True, 0


def reserve_rate_limit_slots(
    key: str,
    max_per_hour: int,
    slot_count: int,
    *,
    consume: bool,
) -> tuple[bool, int, list[float]]:
    """Atomically check or reserve several durable hourly model-run slots."""

    if (
        not isinstance(slot_count, int)
        or isinstance(slot_count, bool)
        or not 1 <= slot_count <= 20
    ):
        raise ValueError("Invalid hourly rate-limit slot count.")
    now = time.time()
    with RATE_LIMIT_LOCK:
        persisted = key.startswith(PERSISTED_RATE_LIMIT_PREFIXES)
        persisted_buckets = (
            _load_persisted_rate_limits_unlocked() if persisted else {}
        )
        rows = sorted({
            float(stamp)
            for stamp in [
                *persisted_buckets.get(key, []),
                *RATE_LIMIT_STATE.get(key, []),
            ]
            if now - float(stamp) < 3600
        })
        limit = max(1, int(max_per_hour))
        available = max(0, limit - len(rows))
        if available < slot_count:
            # Wait until enough of the oldest rows have expired for the whole
            # bounded packet. With two existing rows and a six-slot request,
            # both must expire; retrying after only the oldest would spin.
            required_expirations = min(
                len(rows),
                slot_count - available,
            )
            retry_after = 3600
            if required_expirations:
                blocking_stamp = rows[required_expirations - 1]
                retry_after = max(
                    1,
                    int(3600 - (now - blocking_stamp) + 0.999),
                )
            RATE_LIMIT_STATE[key] = rows
            if persisted:
                if rows:
                    persisted_buckets[key] = rows
                else:
                    persisted_buckets.pop(key, None)
                _save_persisted_rate_limits_unlocked(persisted_buckets)
            return False, retry_after, []
        if not consume:
            if rows:
                RATE_LIMIT_STATE[key] = rows
            else:
                RATE_LIMIT_STATE.pop(key, None)
            if persisted:
                if rows:
                    persisted_buckets[key] = rows
                else:
                    persisted_buckets.pop(key, None)
                _save_persisted_rate_limits_unlocked(persisted_buckets)
            return True, 0, []

        existing = set(rows)
        reserved: list[float] = []
        candidate = now
        while len(reserved) < slot_count:
            if candidate > 0 and candidate not in existing:
                reserved.append(candidate)
                existing.add(candidate)
            candidate = math.nextafter(candidate, 0.0)
        rows = sorted([*rows, *reserved])
        RATE_LIMIT_STATE[key] = rows
        if persisted:
            persisted_buckets[key] = rows
            _save_persisted_rate_limits_unlocked(persisted_buckets)
    return True, 0, reserved


def release_rate_limit_slots(key: str, reservation_stamps: object) -> int:
    """Idempotently release only the exact unused slots from one reservation."""

    if not isinstance(reservation_stamps, list) or len(reservation_stamps) > 20:
        raise ValueError("Invalid hourly rate-limit reservation stamps.")
    release_stamps: set[float] = set()
    for value in reservation_stamps:
        if (
            isinstance(value, bool)
            or not isinstance(value, (int, float))
            or not math.isfinite(float(value))
            or float(value) <= 0
        ):
            raise ValueError("Invalid hourly rate-limit reservation stamp.")
        release_stamps.add(float(value))
    if len(release_stamps) != len(reservation_stamps):
        raise ValueError("Duplicate hourly rate-limit reservation stamp.")
    now = time.time()
    with RATE_LIMIT_LOCK:
        persisted = key.startswith(PERSISTED_RATE_LIMIT_PREFIXES)
        persisted_buckets = (
            _load_persisted_rate_limits_unlocked() if persisted else {}
        )
        rows = sorted({
            float(stamp)
            for stamp in [
                *persisted_buckets.get(key, []),
                *RATE_LIMIT_STATE.get(key, []),
            ]
            if now - float(stamp) < 3600
        })
        released = len(set(rows).intersection(release_stamps))
        rows = [stamp for stamp in rows if stamp not in release_stamps]
        if rows:
            RATE_LIMIT_STATE[key] = rows
        else:
            RATE_LIMIT_STATE.pop(key, None)
        if persisted:
            if rows:
                persisted_buckets[key] = rows
            else:
                persisted_buckets.pop(key, None)
            _save_persisted_rate_limits_unlocked(persisted_buckets)
    return released


def _corrective_open_hourly_reservation_digest(
    rate_key: str,
    mission_id: str,
    lease_id: str,
    candidate_url_digest: str,
    stamps: list[float],
) -> str:
    return payload_digest(
        rate_key,
        mission_id,
        lease_id,
        candidate_url_digest,
        *(format(float(stamp), ".17g") for stamp in stamps),
    )


def _corrective_open_hourly_reservation_record(
    rate_key: str,
    model_tier: str,
    max_runs_per_hour: int,
    mission_id: str,
    lease_id: str,
    candidate_url_digest: str,
    stamps: object,
) -> dict | None:
    rows = stamps if isinstance(stamps, list) else []
    if (
        len(rows) != CORRECTIVE_OPEN_MAXIMUM_TOTAL_RUN_COUNT
        or any(
            isinstance(stamp, bool)
            or not isinstance(stamp, (int, float))
            or not math.isfinite(float(stamp))
            or float(stamp) <= 0
            for stamp in rows
        )
        or len({float(stamp) for stamp in rows}) != len(rows)
        or not SAFE_ID_PATTERN.fullmatch(mission_id)
        or not SAFE_ID_PATTERN.fullmatch(lease_id)
        or re.fullmatch(r"[0-9a-f]{64}", candidate_url_digest) is None
    ):
        return None
    normalized = [float(stamp) for stamp in rows]
    return {
        "schemaVersion": CORRECTIVE_OPEN_HOURLY_RESERVATION_SCHEMA,
        "reservationId": safe_id(None, "hourly-reservation"),
        "kind": "corrective_required_open_url_model_calls",
        "state": "reserved",
        "missionId": mission_id,
        "leaseId": lease_id,
        "candidateUrlDigest": candidate_url_digest,
        "rateKeyDigest": payload_digest(rate_key),
        "modelTier": model_tier,
        "maximumRunsPerHour": int(max_runs_per_hour),
        "reservedRunCount": CORRECTIVE_OPEN_MAXIMUM_TOTAL_RUN_COUNT,
        "mainRunCount": CORRECTIVE_OPEN_MAIN_RUN_COUNT,
        "maximumChildRunCount": CORRECTIVE_OPEN_MAXIMUM_CHILD_RUN_COUNT,
        "mainSlotStamp": normalized[0],
        "childSlotStamps": normalized[1:],
        "reservationDigest": _corrective_open_hourly_reservation_digest(
            rate_key,
            mission_id,
            lease_id,
            candidate_url_digest,
            normalized,
        ),
        "reservedAt": utc_now(),
        "actualChildRunCount": None,
        "releasedUnusedChildRunCount": 0,
        "reconciledAt": None,
    }


def _corrective_open_hourly_release_plan(
    mission: object,
    receipt: object,
) -> dict | None:
    """Validate Backend reservation lineage before releasing unused slots."""

    row = mission if isinstance(mission, dict) else {}
    execution = (
        row.get("execution")
        if isinstance(row.get("execution"), dict)
        else {}
    )
    reservation = (
        execution.get("correctiveOpenHourlyReservation")
        if isinstance(
            execution.get("correctiveOpenHourlyReservation"),
            dict,
        )
        else {}
    )
    receipt_row = receipt if isinstance(receipt, dict) else {}
    deterministic_repair = (
        row.get("deterministicOpenRepair")
        if isinstance(row.get("deterministicOpenRepair"), dict)
        else {}
    )
    output_repair = (
        row.get("outputContractRepair")
        if isinstance(row.get("outputContractRepair"), dict)
        else {}
    )
    required_urls, required_urls_error = (
        _trading_system_required_open_urls_for_mission(row)
    )
    required_url_digest = (
        payload_digest(required_urls) if required_urls else ""
    )
    (
        radar_reservation_digest,
        radar_reservation_error,
        _radar_dynamic_reservation,
    ) = _radar_dynamic_open_reservation_digest(row)
    radar_receipt = bool(
        receipt_row.get("schemaVersion")
        == "radar-corrective-open-verification-receipt-v1"
    )
    expected_reservation_digest = (
        str(radar_reservation_digest or "")
        if radar_receipt
        else required_url_digest
    )
    agent_id = str(row.get("owner") or "manager")
    tool_id = str(row.get("toolId") or "")
    tier_id = str(row.get("modelTier") or role_default_model_tier(agent_id))
    rate_key = f"real:{agent_id}:{tool_id}:{tier_id}"
    tier = (
        (load_orchestration_contract().get("modelTiers") or {}).get(tier_id)
        or {}
    )
    max_runs = clamp_int(tier.get("maxRunsPerHour"), 12, 1, 200)
    main_stamp = reservation.get("mainSlotStamp")
    child_stamps = reservation.get("childSlotStamps")
    stamps = (
        [main_stamp, *child_stamps]
        if isinstance(child_stamps, list)
        else []
    )
    normalized_stamps = (
        [float(stamp) for stamp in stamps]
        if stamps
        and all(
            not isinstance(stamp, bool)
            and isinstance(stamp, (int, float))
            and math.isfinite(float(stamp))
            and float(stamp) > 0
            for stamp in stamps
        )
        else []
    )
    reserved_at = parse_iso(str(reservation.get("reservedAt") or ""))
    actual_child_runs = receipt_row.get("missingUrlVerificationCount")
    reservation_digest = str(
        reservation.get("reservationDigest") or ""
    ).lower()
    if not (
        reservation.get("schemaVersion")
        == CORRECTIVE_OPEN_HOURLY_RESERVATION_SCHEMA
        and SAFE_ID_PATTERN.fullmatch(
            str(reservation.get("reservationId") or "")
        )
        and reservation.get("kind")
        == "corrective_required_open_url_model_calls"
        and reservation.get("state") == "reserved"
        and reservation.get("missionId") == row.get("id")
        and reservation.get("leaseId") == execution.get("leaseId")
        and reservation.get("candidateUrlDigest")
        == expected_reservation_digest
        and reservation.get("rateKeyDigest") == payload_digest(rate_key)
        and reservation.get("modelTier") == tier_id
        and reservation.get("maximumRunsPerHour") == max_runs
        and reservation.get("reservedRunCount")
        == CORRECTIVE_OPEN_MAXIMUM_TOTAL_RUN_COUNT
        and reservation.get("mainRunCount")
        == CORRECTIVE_OPEN_MAIN_RUN_COUNT
        and reservation.get("maximumChildRunCount")
        == CORRECTIVE_OPEN_MAXIMUM_CHILD_RUN_COUNT
        and len(normalized_stamps)
        == CORRECTIVE_OPEN_MAXIMUM_TOTAL_RUN_COUNT
        and len(set(normalized_stamps)) == len(normalized_stamps)
        and normalized_stamps == sorted(normalized_stamps, reverse=True)
        and reserved_at is not None
        and all(
            abs(stamp - reserved_at.timestamp()) <= 5
            for stamp in normalized_stamps
        )
        and re.fullmatch(r"[0-9a-f]{64}", reservation_digest) is not None
        and secrets.compare_digest(
            reservation_digest,
            _corrective_open_hourly_reservation_digest(
                rate_key,
                str(row.get("id") or ""),
                str(execution.get("leaseId") or ""),
                expected_reservation_digest,
                normalized_stamps,
            ),
        )
        and execution.get("processStarted") is True
        and receipt_row.get("valid") is True
        and receipt_row.get("requiredUrlCoverageVerified") is True
        and receipt_row.get("manifestVerified") is True
        and isinstance(actual_child_runs, int)
        and not isinstance(actual_child_runs, bool)
        and 0 <= actual_child_runs <= CORRECTIVE_OPEN_MAXIMUM_CHILD_RUN_COUNT
        and (
            (
                not radar_receipt
                and required_urls_error is None
                and len(required_urls) == 6
                and receipt_row.get("requiredUrlDigest")
                == required_url_digest
                and deterministic_repair.get("schemaVersion")
                == "deterministic-open-repair-v1"
                and deterministic_repair.get("version")
                == TRADING_SYSTEM_DETERMINISTIC_OPEN_REPAIR_VERSION
                and deterministic_repair.get("kind")
                == TRADING_SYSTEM_DETERMINISTIC_OPEN_REPAIR_KIND
                and deterministic_repair.get("attemptCount") == 1
                and deterministic_repair.get("maximumAttempts")
                == TRADING_SYSTEM_DETERMINISTIC_OPEN_REPAIR_MAX_ATTEMPTS
                and deterministic_repair.get("candidateUrlCount") == 6
                and deterministic_repair.get("candidateUrlDigest")
                == required_url_digest
                and output_repair.get("version")
                == PUBLIC_RESEARCH_OUTPUT_REPAIR_VERSION
                and output_repair.get("kind")
                == "trading_system_evidence_open_deterministic_verification_repair"
                and execution.get("deterministicOpenRepairKind")
                == TRADING_SYSTEM_DETERMINISTIC_OPEN_REPAIR_KIND
            )
            or (
                radar_receipt
                and radar_reservation_error is None
                and re.fullmatch(
                    r"[0-9a-f]{64}",
                    str(radar_reservation_digest or ""),
                )
                is not None
                and _radar_complete_daily_batch_required(row)
                and receipt_row.get("requiredUrlCount")
                == RADAR_DAILY_BATCH_REQUIRED_ITEMS
                and receipt_row.get("candidateUrlSetMatched") is True
                and re.fullmatch(
                    r"[0-9a-f]{64}",
                    str(receipt_row.get("requiredUrlDigest") or ""),
                )
                is not None
                and re.fullmatch(
                    r"[0-9a-f]{64}",
                    str(receipt_row.get("manifestRequiredUrlDigest") or ""),
                )
                is not None
                and (
                    not isinstance(row.get("correctiveRetry"), dict)
                    or secrets.compare_digest(
                        str(receipt_row.get("requiredUrlDigest") or ""),
                        str(radar_reservation_digest or ""),
                    )
                )
            )
        )
    ):
        return None
    return {
        "rateKey": rate_key,
        "reservationId": reservation["reservationId"],
        "actualChildRunCount": actual_child_runs,
        "releaseStamps": normalized_stamps[
            CORRECTIVE_OPEN_MAIN_RUN_COUNT + actual_child_runs:
        ],
    }


def _settle_corrective_open_hourly_reservation(
    mission_id: str,
    lease_id: str,
) -> dict | None:
    """Release verified-unused child slots only after terminal receipt save."""

    plan = None
    pending = None
    with MISSIONS_LOCK:
        missions = load_missions()
        for mission in missions:
            execution = (
                mission.get("execution")
                if isinstance(mission.get("execution"), dict)
                else {}
            )
            root_receipt = (
                mission.get("correctiveOpenVerificationReceipt")
                if isinstance(
                    mission.get("correctiveOpenVerificationReceipt"),
                    dict,
                )
                else None
            )
            execution_receipt = execution.get(
                "correctiveOpenVerificationReceipt"
            )
            if not (
                mission.get("id") == mission_id
                and mission.get("status") in {"completed", "blocked", "failed"}
                and execution.get("leaseId") == lease_id
                and isinstance(root_receipt, dict)
                and root_receipt == execution_receipt
            ):
                continue
            plan = _corrective_open_hourly_release_plan(
                mission,
                root_receipt,
            )
            if not plan:
                return None
            reservation = execution["correctiveOpenHourlyReservation"]
            settlement_token = payload_digest(
                str(plan["reservationId"]),
                lease_id,
                str(plan["actualChildRunCount"]),
            )
            reservation.update({
                "state": "settlement_pending",
                "settlementToken": settlement_token,
                "actualChildRunCount": plan["actualChildRunCount"],
                "requestedUnusedChildReleaseCount": len(
                    plan["releaseStamps"]
                ),
                "settlementRequestedAt": utc_now(),
            })
            execution["correctiveOpenHourlyReservation"] = reservation
            mission["execution"] = execution
            pending = mission
            plan["settlementToken"] = settlement_token
            break
        if pending:
            save_missions(missions)
    if not pending or not plan:
        return None

    try:
        released_count = release_rate_limit_slots(
            str(plan["rateKey"]),
            list(plan["releaseStamps"]),
        )
    except (DataIntegrityError, OSError, ValueError):
        append_audit({
            "type": "mission.corrective_open_hourly_settlement_failed",
            "missionId": mission_id,
            "leaseId": lease_id,
            "reservationId": plan.get("reservationId"),
            "automaticRetry": False,
            "rateSlotsReleased": 0,
        })
        return pending
    if released_count != len(plan["releaseStamps"]):
        append_audit({
            "type": "mission.corrective_open_hourly_settlement_failed",
            "missionId": mission_id,
            "leaseId": lease_id,
            "reservationId": plan.get("reservationId"),
            "automaticRetry": False,
            "requestedRateSlotsReleased": len(plan["releaseStamps"]),
            "rateSlotsReleased": released_count,
            "reason": "reserved_slot_identity_missing",
        })
        return pending

    settled = None
    with MISSIONS_LOCK:
        missions = load_missions()
        for mission in missions:
            execution = (
                mission.get("execution")
                if isinstance(mission.get("execution"), dict)
                else {}
            )
            reservation = (
                execution.get("correctiveOpenHourlyReservation")
                if isinstance(
                    execution.get("correctiveOpenHourlyReservation"),
                    dict,
                )
                else {}
            )
            if not (
                mission.get("id") == mission_id
                and execution.get("leaseId") == lease_id
                and reservation.get("reservationId")
                == plan["reservationId"]
                and reservation.get("state") == "settlement_pending"
                and reservation.get("settlementToken")
                == plan["settlementToken"]
            ):
                continue
            reservation.update({
                "state": "reconciled",
                "releasedUnusedChildRunCount": released_count,
                "reconciledAt": utc_now(),
            })
            execution["correctiveOpenHourlyReservation"] = reservation
            mission["execution"] = execution
            settled = mission
            break
        if settled:
            save_missions(missions)
    append_audit({
        "type": "mission.corrective_open_hourly_reconciled",
        "missionId": mission_id,
        "leaseId": lease_id,
        "reservationId": plan.get("reservationId"),
        "reservedRunCount": CORRECTIVE_OPEN_MAXIMUM_TOTAL_RUN_COUNT,
        "actualRunCount": (
            CORRECTIVE_OPEN_MAIN_RUN_COUNT
            + int(plan["actualChildRunCount"])
        ),
        "actualChildRunCount": plan["actualChildRunCount"],
        "releasedUnusedChildRunCount": released_count,
        "automaticRetry": False,
    })
    return settled or pending


def ensure_memory_dir() -> None:
    for folder in [
        MEMORY_DIR,
        MEMORY_DIR / "agent-notes",
        MEMORY_DIR / "meetings",
        MEMORY_DIR / "summaries",
        MEMORY_DIR / "reports",
        MEMORY_DIR / "artifacts",
        MEMORY_DIR / "screenshots",
    ]:
        folder.mkdir(parents=True, exist_ok=True)


def load_memory_index() -> dict:
    ensure_memory_dir()
    data = read_json(MEMORY_INDEX_PATH, {"version": "memory-index-v001", "items": []})
    if not isinstance(data, dict):
        return {"version": "memory-index-v001", "items": []}
    data.setdefault("version", "memory-index-v001")
    data.setdefault("items", [])
    if not isinstance(data["items"], list):
        data["items"] = []
    return data


def save_memory_index(index: dict) -> None:
    ensure_memory_dir()
    index["updatedAt"] = utc_now()
    with MEMORY_INDEX_LOCK:
        write_json(MEMORY_INDEX_PATH, index, keep_backup=True)


def memory_item_text(item: dict) -> str:
    fields = [
        item.get("id"),
        item.get("kind"),
        item.get("title"),
        item.get("summary"),
        item.get("sourcePath"),
        " ".join(item.get("agents") or []),
        " ".join(item.get("tags") or []),
    ]
    return " ".join(str(field or "") for field in fields).lower()


def search_memory_items(query: str = "", limit: int = 12) -> list[dict]:
    index = load_memory_index()
    items = [item for item in index.get("items", []) if isinstance(item, dict)]
    text = " ".join(str(query or "").lower().split())
    if not text:
        return items[:limit]
    tokens = [token for token in text.replace("/", " ").replace("_", " ").split() if token]

    scored: list[tuple[int, dict]] = []
    for item in items:
        haystack = memory_item_text(item)
        score = sum(1 for token in tokens if token in haystack)
        if score:
            scored.append((score, item))
    scored.sort(key=lambda row: (row[0], row[1].get("updatedAt") or row[1].get("createdAt") or ""), reverse=True)
    return [item for _, item in scored[:limit]]


def memory_read_model_item(item: object) -> dict:
    """Project a memory card without returning a local filesystem path."""
    source = item if isinstance(item, dict) else {}
    raw_source_path = str(source.get("sourcePath") or "").strip()
    agents = source.get("agents") if isinstance(source.get("agents"), list) else []
    tags = source.get("tags") if isinstance(source.get("tags"), list) else []
    return {
        "id": safe_reference(source.get("id")),
        "kind": redact_text(str(source.get("kind") or "note"), 80),
        "title": redact_text(str(source.get("title") or "Memory"), 160),
        "summary": redact_text(str(source.get("summary") or ""), 2400),
        "agents": [
            value
            for value in (safe_reference(entry) for entry in agents[:20])
            if value
        ],
        "tags": [redact_text(str(entry), 80) for entry in tags[:30]],
        "hasLocalSource": bool(raw_source_path),
        "createdAt": source.get("createdAt"),
        "updatedAt": source.get("updatedAt"),
        "safety": {
            "containsSecret": False,
            "secretRedacted": bool((source.get("safety") or {}).get("secretRedacted", False))
            if isinstance(source.get("safety"), dict)
            else False,
            "localPathExposed": False,
        },
    }


def memory_index_read_model(index: object | None = None) -> dict:
    source = index if isinstance(index, dict) else load_memory_index()
    rows = source.get("items") if isinstance(source.get("items"), list) else []
    return {
        "version": redact_text(str(source.get("version") or "memory-index-v001"), 80),
        "items": [memory_read_model_item(item) for item in rows if isinstance(item, dict)],
        "updatedAt": source.get("updatedAt"),
        "readModel": "memory_index_frontend_v1",
    }


def upsert_memory_item(payload: dict) -> dict:
    ensure_memory_dir()
    with MEMORY_INDEX_LOCK:
        index = load_memory_index()
        item_id = str(payload.get("id") or f"mem-{int(time.time() * 1000)}")
        existing_items = [item for item in index.get("items", []) if isinstance(item, dict)]
        previous = next((item for item in existing_items if item.get("id") == item_id), {})
        raw_summary = str(payload.get("summary") or previous.get("summary") or "")
        secret_redacted = json_contains_potential_secret(payload)
        item = {
            **previous,
            "id": item_id,
            "kind": str(payload.get("kind") or previous.get("kind") or "note"),
            "title": redact_text(str(payload.get("title") or previous.get("title") or "Untitled Memory"), 160),
            "summary": redact_text(raw_summary, 2400),
            "sourcePath": redact_text(str(payload.get("sourcePath") or previous.get("sourcePath") or ""), 500),
            "agents": sanitize_json_value(payload.get("agents") if isinstance(payload.get("agents"), list) else previous.get("agents", [])),
            "tags": sanitize_json_value(payload.get("tags") if isinstance(payload.get("tags"), list) else previous.get("tags", [])),
            "createdAt": previous.get("createdAt") or utc_now(),
            "updatedAt": utc_now(),
            "safety": {
                "containsSecret": False,
                "secretRedacted": secret_redacted,
                "approvalRequired": False,
                "publicShareable": False,
            },
        }
        index["items"] = [item] + [row for row in existing_items if row.get("id") != item_id]
        save_memory_index(index)
    append_audit({"type": "memory.upsert", "memoryId": item["id"], "kind": item["kind"], "secretRedacted": secret_redacted})
    return item


def load_meeting_records(limit: int = 80) -> list[dict]:
    ensure_memory_dir()
    records = tail_jsonl(MEETING_TRANSCRIPTS_PATH, limit=max(limit * 3, limit), max_bytes=524288)[::-1]
    durable = [
        item for item in records
        if item.get("simulation") is not True
        and not str(item.get("source") or "").startswith("frontend.")
    ]
    return durable[:limit]


def append_meeting_record(payload: dict, kind: str = "meeting") -> dict:
    ensure_memory_dir()
    participants = payload.get("participants") if isinstance(payload.get("participants"), list) else []
    messages = payload.get("messages") if isinstance(payload.get("messages"), list) else []
    decisions = payload.get("decisions") if isinstance(payload.get("decisions"), list) else []
    next_actions = payload.get("nextActions") if isinstance(payload.get("nextActions"), list) else []
    record = {
        "id": str(payload.get("id") or f"meeting-{int(time.time() * 1000)}"),
        "kind": kind,
        "time": utc_now(),
        "title": redact_text(str(payload.get("title") or payload.get("agenda") or "Agent Meeting"), 160),
        "agenda": redact_text(str(payload.get("agenda") or ""), 1200),
        "participants": [item for item in (safe_reference(value) for value in participants[:20]) if item],
        "summary": redact_text(str(payload.get("summary") or payload.get("message") or ""), 2400),
        "messages": sanitize_json_value(messages[:80]),
        "decisions": sanitize_json_value(decisions[:20]),
        "nextActions": sanitize_json_value(next_actions[:20]),
        "source": redact_text(str(payload.get("source") or "frontend"), 160),
        "simulation": bool(payload.get("simulation", False)),
        "status": redact_text(str(payload.get("status") or "completed"), 40),
        "trigger": redact_text(str(payload.get("trigger") or "manual"), 40),
        "linkedMissionId": safe_reference(payload.get("linkedMissionId")),
        "linkedPropId": safe_reference(payload.get("linkedPropId")),
    }
    with MEETING_TRANSCRIPTS_LOCK:
        rotate_jsonl_segment(MEETING_TRANSCRIPTS_PATH)
        with MEETING_TRANSCRIPTS_PATH.open("a", encoding="utf-8") as handle:
            handle.write(json.dumps(record, ensure_ascii=False) + "\n")
    append_audit({"type": "meeting.recorded", "meetingId": record["id"], "kind": kind})
    return record


def _interactive_meeting_default_store() -> dict:
    return {
        "schemaVersion": INTERACTIVE_MEETING_SCHEMA,
        "sessions": [],
        "createIdempotency": {},
        "updatedAt": utc_now(),
    }


def _interactive_meeting_store_shape(payload: object) -> dict:
    if not isinstance(payload, dict):
        raise DataIntegrityError("Interactive meeting session store must be an object.")
    if payload.get("schemaVersion") != INTERACTIVE_MEETING_SCHEMA:
        raise DataIntegrityError("Interactive meeting session store schema is invalid.")
    raw_sessions = payload.get("sessions")
    if not isinstance(raw_sessions, list):
        raise DataIntegrityError("Interactive meeting sessions must be a list.")
    sessions = []
    seen_ids: set[str] = set()
    for raw_session in raw_sessions[:INTERACTIVE_MEETING_MAX_SESSIONS]:
        if not isinstance(raw_session, dict):
            raise DataIntegrityError("Interactive meeting session row must be an object.")
        session_id = safe_reference(raw_session.get("id"))
        status = str(raw_session.get("status") or "")
        participants = raw_session.get("participantAgentIds")
        if (
            not session_id
            or session_id in seen_ids
            or status not in INTERACTIVE_MEETING_STATUS_VALUES
            or not isinstance(participants, list)
            or not participants
            or len(participants) > INTERACTIVE_MEETING_MAX_PARTICIPANTS
            or participants[-1] != "manager"
            or any(item not in EXPECTED_AGENT_IDS for item in participants)
        ):
            raise DataIntegrityError("Interactive meeting session identity or participants are invalid.")
        turns = raw_session.get("turns")
        if not isinstance(turns, list) or len(turns) > INTERACTIVE_MEETING_MAX_TRANSCRIPT_TURNS:
            raise DataIntegrityError("Interactive meeting transcript is invalid.")
        round_count = clamp_int(raw_session.get("roundCount"), 0, 0, INTERACTIVE_MEETING_MAX_ROUNDS)
        if round_count != raw_session.get("roundCount"):
            raise DataIntegrityError("Interactive meeting round count is invalid.")
        session = copy.deepcopy(raw_session)
        # Persisted v1 sessions created before user-controlled meeting batches
        # did not store these fields.  Migrate them in memory without making a
        # previously valid local store unreadable after a Bridge upgrade.
        agenda = str(session.get("agenda") or "").strip()
        development_goal = str(session.get("developmentGoal") or "").strip()
        session["developmentGoal"] = development_goal or agenda
        raw_turn_count = session.get("aiTurnsPerRound")
        if raw_turn_count is None:
            raw_turn_count = len(participants)
        if (
            not isinstance(raw_turn_count, int)
            or isinstance(raw_turn_count, bool)
            or raw_turn_count < INTERACTIVE_MEETING_MIN_TURNS_PER_ROUND
            or raw_turn_count > INTERACTIVE_MEETING_MAX_TURNS_PER_ROUND
            or raw_turn_count < len(participants)
        ):
            raise DataIntegrityError("Interactive meeting AI turns per round are invalid.")
        session["aiTurnsPerRound"] = raw_turn_count
        sessions.append(session)
        seen_ids.add(session_id)
    create_idempotency = payload.get("createIdempotency")
    if not isinstance(create_idempotency, dict):
        raise DataIntegrityError("Interactive meeting idempotency store is invalid.")
    return {
        "schemaVersion": INTERACTIVE_MEETING_SCHEMA,
        "sessions": sessions,
        "createIdempotency": create_idempotency,
        "updatedAt": payload.get("updatedAt"),
    }


def ensure_interactive_meeting_sessions_store() -> dict:
    ensure_runtime_dir()
    with INTERACTIVE_MEETING_SESSIONS_LOCK:
        if not INTERACTIVE_MEETING_SESSIONS_PATH.exists():
            store = _interactive_meeting_default_store()
            write_json(INTERACTIVE_MEETING_SESSIONS_PATH, store)
            return store
        return _interactive_meeting_store_shape(
            read_json(INTERACTIVE_MEETING_SESSIONS_PATH, None)
        )


def _load_interactive_meeting_store_unlocked() -> dict:
    if not INTERACTIVE_MEETING_SESSIONS_PATH.exists():
        return _interactive_meeting_default_store()
    return _interactive_meeting_store_shape(
        read_json(INTERACTIVE_MEETING_SESSIONS_PATH, None)
    )


def _save_interactive_meeting_store_unlocked(store: dict) -> dict:
    store = _interactive_meeting_store_shape(store)
    retained_session_ids = {
        str(item.get("id") or "") for item in store.get("sessions", [])
    }
    store["createIdempotency"] = {
        key: value
        for key, value in list(store.get("createIdempotency", {}).items())[-200:]
        if isinstance(value, dict)
        and str(value.get("sessionId") or "") in retained_session_ids
    }
    store["updatedAt"] = utc_now()
    write_json(
        INTERACTIVE_MEETING_SESSIONS_PATH,
        store,
        keep_backup=INTERACTIVE_MEETING_SESSIONS_PATH.exists(),
    )
    return store


def _interactive_meeting_find_unlocked(store: dict, session_id: str) -> dict | None:
    return next(
        (item for item in store.get("sessions", []) if item.get("id") == session_id),
        None,
    )


def _interactive_meeting_session_read_model(session: dict) -> dict:
    proposal = (
        copy.deepcopy(session.get("proposal"))
        if isinstance(session.get("proposal"), dict)
        else None
    )
    implementation_mission_id = safe_reference(session.get("implementationMissionId"))
    implementation_mission = (
        find_mission(implementation_mission_id)
        if implementation_mission_id
        else None
    )
    implementation_summary = None
    if isinstance(implementation_mission, dict):
        implementation_approval = (
            implementation_mission.get("approval")
            if isinstance(implementation_mission.get("approval"), dict)
            else {}
        )
        implementation_summary = {
            "id": implementation_mission_id,
            "status": implementation_mission.get("status"),
            "approvalState": implementation_approval.get("state"),
            "readyToExecute": (
                implementation_mission.get("status") == "waiting_approval"
                and implementation_approval.get("state") == "approved"
            ),
            "result": redact_text(str(implementation_mission.get("result") or ""), 600),
            "updatedAt": implementation_mission.get("updatedAt"),
        }
    ready_to_execute = bool(
        implementation_summary
        and implementation_summary.get("readyToExecute") is True
        and session.get("status") == "approved"
    )
    if proposal is not None:
        proposal["status"] = session.get("status")
        proposal["implementationMissionId"] = implementation_mission_id
        proposal["readyToExecute"] = ready_to_execute
    manager_turn = _interactive_meeting_latest_manager_turn(session)
    round_count = int(session.get("roundCount") or 0)
    current_round_turns = [
        item
        for item in session.get("turns", [])
        if isinstance(item, dict)
        and int(item.get("roundNumber") or 0) == round_count
        and item.get("role") == "agent"
    ]
    result = {
        "id": session.get("id"),
        "agenda": session.get("agenda"),
        "developmentGoal": session.get("developmentGoal") or session.get("agenda"),
        "participantAgentIds": list(session.get("participantAgentIds") or []),
        "aiTurnsPerRound": int(
            session.get("aiTurnsPerRound")
            or len(session.get("participantAgentIds") or [])
        ),
        "status": session.get("status"),
        "roundCount": session.get("roundCount"),
        "maxRounds": INTERACTIVE_MEETING_MAX_ROUNDS,
        "minTurnsPerRound": INTERACTIVE_MEETING_MIN_TURNS_PER_ROUND,
        "maxTurnsPerRound": INTERACTIVE_MEETING_MAX_TURNS_PER_ROUND,
        "turns": list(session.get("turns") or []),
        "discussionMissionIds": list(session.get("discussionMissionIds") or []),
        "activeDiscussionMissionId": session.get("activeDiscussionMissionId"),
        "implementationMissionId": session.get("implementationMissionId"),
        "implementationMission": implementation_summary,
        "readyToExecute": ready_to_execute,
        "approvalNote": session.get("approvalNote"),
        "proposal": proposal,
        "managerDecision": (
            {
                "turnId": manager_turn.get("id"),
                "message": manager_turn.get("message"),
                "proposal": manager_turn.get("proposal"),
                "risks": list(manager_turn.get("risks") or []),
                "acceptanceChecks": list(manager_turn.get("acceptanceChecks") or []),
                "decision": manager_turn.get("managerDecision"),
                "createdAt": manager_turn.get("createdAt"),
            }
            if manager_turn
            else None
        ),
        "progress": {
            "currentRound": round_count,
            "totalRounds": INTERACTIVE_MEETING_MAX_ROUNDS,
            "currentTurn": len(current_round_turns),
            "totalTurns": int(
                session.get("aiTurnsPerRound")
                or len(session.get("participantAgentIds") or [])
            ),
        },
        "failureReason": session.get("failureReason"),
        "createdAt": session.get("createdAt"),
        "updatedAt": session.get("updatedAt"),
    }
    return sanitize_json_value(
        result,
        collection_limit=INTERACTIVE_MEETING_MAX_TRANSCRIPT_TURNS,
        string_limit=4000,
    )


def interactive_meeting_sessions_read_model() -> dict:
    with INTERACTIVE_MEETING_SESSIONS_LOCK:
        store = _load_interactive_meeting_store_unlocked()
        sessions = [
            _interactive_meeting_session_read_model(item)
            for item in store.get("sessions", [])
        ]
    return {
        "ok": True,
        "sessions": sessions,
        "limits": {
            "maxRoundsPerSession": INTERACTIVE_MEETING_MAX_ROUNDS,
            "maxParticipants": INTERACTIVE_MEETING_MAX_PARTICIPANTS,
            "minTurnsPerRound": INTERACTIVE_MEETING_MIN_TURNS_PER_ROUND,
            "maxTurnsPerRound": INTERACTIVE_MEETING_MAX_TURNS_PER_ROUND,
            "singleRoundInflight": True,
        },
        "updatedAt": store.get("updatedAt") or utc_now(),
        "readModel": "interactive_ai_meeting_sessions_v1",
    }


def interactive_meeting_session_read_model(session_id: str) -> dict:
    normalized_id = safe_reference(session_id)
    if not normalized_id:
        raise RequestError("Invalid meeting session id.", 422)
    with INTERACTIVE_MEETING_SESSIONS_LOCK:
        store = _load_interactive_meeting_store_unlocked()
        session = _interactive_meeting_find_unlocked(store, normalized_id)
        if not session:
            raise RequestError("Meeting session not found.", 404)
        result = _interactive_meeting_session_read_model(session)
    return {
        "ok": True,
        "session": result,
        "updatedAt": store.get("updatedAt") or utc_now(),
        "readModel": "interactive_ai_meeting_session_v1",
    }


def _interactive_meeting_idempotency_key(payload: dict) -> str:
    key = str(payload.get("idempotencyKey") or "").strip()
    if not key or not SAFE_IDEMPOTENCY_PATTERN.fullmatch(key):
        raise RequestError("A short safe idempotencyKey is required.", 422)
    return key


def _interactive_meeting_request_digest(operation: str, payload: dict) -> str:
    clean = {
        str(key): value
        for key, value in payload.items()
        if key != "idempotencyKey"
    }
    return payload_digest(
        "interactive-meeting-request-v1",
        operation,
        json.dumps(clean, ensure_ascii=False, sort_keys=True, separators=(",", ":")),
    )


def _interactive_meeting_idempotent_record(
    records: dict,
    *,
    key: str,
    operation: str,
    request_digest: str,
) -> dict | None:
    existing = records.get(key)
    if not isinstance(existing, dict):
        return None
    if (
        existing.get("operation") != operation
        or not secrets.compare_digest(
            str(existing.get("requestDigest") or ""),
            request_digest,
        )
    ):
        raise RequestError("Idempotency key is already used by a different meeting action.", 409)
    return existing


def _interactive_meeting_replay_response(session: dict, record: dict) -> dict:
    return {
        "ok": True,
        "kind": record.get("resultKind") or "interactive_meeting_updated",
        "session": _interactive_meeting_session_read_model(session),
        "idempotentReplay": True,
        "readyToExecute": bool(record.get("readyToExecute", False)),
        "implementationMissionId": record.get("implementationMissionId"),
        "_httpStatus": int(record.get("httpStatus") or 200),
    }


def _interactive_meeting_participants(value: object) -> list[str]:
    raw = value if isinstance(value, list) else ["ceo", "ea_developer", "risk_guard"]
    participants: list[str] = []
    for item in raw:
        agent_id = str(item or "").strip()
        if agent_id not in EXPECTED_AGENT_IDS:
            raise RequestError(f"Unknown participant Agent: {agent_id or 'empty'}.", 422)
        if agent_id not in participants and agent_id != "manager":
            participants.append(agent_id)
    if not participants:
        raise RequestError("At least one specialist Agent plus Manager is required.", 422)
    if len(participants) > INTERACTIVE_MEETING_MAX_PARTICIPANTS - 1:
        raise RequestError("At most three specialist Agents plus Manager may join one round.", 422)
    return [*participants, "manager"]


def _interactive_meeting_requested_turn_count(
    value: object,
    participants: list[str],
) -> int:
    if not isinstance(value, int) or isinstance(value, bool):
        raise RequestError(
            "aiTurnsPerRound must be an integer between 2 and 8.",
            422,
        )
    if not (
        INTERACTIVE_MEETING_MIN_TURNS_PER_ROUND
        <= value
        <= INTERACTIVE_MEETING_MAX_TURNS_PER_ROUND
    ):
        raise RequestError(
            "aiTurnsPerRound must be an integer between 2 and 8.",
            422,
        )
    if value < len(participants):
        raise RequestError(
            "aiTurnsPerRound must give every selected Agent one turn, including Manager.",
            422,
        )
    return value


def _interactive_meeting_round_speakers(session: dict) -> list[str]:
    participants = [
        item
        for item in session.get("participantAgentIds", [])
        if item in EXPECTED_AGENT_IDS
    ]
    specialists = [item for item in participants if item != "manager"]
    if not specialists or not participants or participants[-1] != "manager":
        raise DataIntegrityError("Interactive meeting speaker roster is invalid.")
    turn_count = int(
        session.get("aiTurnsPerRound")
        or len(participants)
    )
    if (
        turn_count < len(participants)
        or turn_count < INTERACTIVE_MEETING_MIN_TURNS_PER_ROUND
        or turn_count > INTERACTIVE_MEETING_MAX_TURNS_PER_ROUND
    ):
        raise DataIntegrityError("Interactive meeting turn count is invalid.")
    contributor_turns = turn_count - 1
    round_number = max(1, int(session.get("roundCount") or 1))
    offset = ((round_number - 1) * contributor_turns) % len(specialists)
    rotating = specialists[offset:] + specialists[:offset]
    speakers = [
        rotating[index % len(rotating)]
        for index in range(contributor_turns)
    ]
    return [*speakers, "manager"]


def _interactive_meeting_hourly_turn_cap() -> int:
    guard = load_orchestration_contract().get("costRateGuard") or {}
    return clamp_int(
        guard.get(
            "interactiveMeetingTurnsPerHour",
            guard.get("collaborationTurnsPerHour"),
        ),
        12,
        INTERACTIVE_MEETING_MIN_TURNS_PER_ROUND,
        40,
    )


def _interactive_meeting_require_full_access() -> None:
    if load_operator_mode_record().get("mode") != "auto_guarded":
        raise RequestError("Interactive AI meetings require Full Access mode.", 409)


def _interactive_meeting_admit_round(ai_turns_per_round: int) -> None:
    if not INTERACTIVE_MEETING_ROUND_LOCK.acquire(blocking=False):
        raise RequestError("Another interactive AI meeting round is already running.", 409)
    try:
        _interactive_meeting_require_full_access()
        quota_gate = _collaboration_quota_gate(
            {"minRemainingPercent": AUTOMATION_MIN_REMAINING_PERCENT},
            refresh=True,
        )
        if not quota_gate.get("allowed"):
            raise RequestError(
                str(quota_gate.get("messageTh") or "Fresh Codex quota must remain strictly above 15%."),
                429,
            )
        if not CODEX_RUNNER_PYTHON.is_file() or not CODEX_RUNNER_SCRIPT.is_file():
            raise RequestError("Codex collaboration Runner is not ready.", 503)
        available, turn_retry_after, _ = reserve_rate_limit_slots(
            "real:interactive-meeting-turn",
            _interactive_meeting_hourly_turn_cap(),
            ai_turns_per_round,
            consume=False,
        )
        if not available:
            error = RequestError(
                "Interactive meeting does not have enough hourly AI-turn capacity for the whole batch.",
                429,
            )
            error.retry_after_seconds = turn_retry_after
            raise error
        allowed, retry_after = check_rate_limit(
            "real:interactive-meeting-round",
            INTERACTIVE_MEETING_ROUNDS_PER_HOUR,
            INTERACTIVE_MEETING_ROUND_COOLDOWN_SECONDS,
            consume=True,
        )
        if not allowed:
            error = RequestError("Interactive meeting round rate limit reached.", 429)
            error.retry_after_seconds = retry_after
            raise error
    except Exception:
        INTERACTIVE_MEETING_ROUND_LOCK.release()
        raise


def _interactive_meeting_create_discussion_mission(
    *,
    session_id: str,
    agenda: str,
    development_goal: str,
    round_number: int,
    user_message: str | None = None,
) -> dict:
    prompt = (
        f"Meeting topic:\n{agenda}\n\n"
        f"Development goal:\n{development_goal}"
    )
    if user_message:
        prompt += f"\n\nLatest user interjection:\n{user_message}"
    mission = create_mission({
        "title": f"AI Meeting: {agenda[:90]}",
        "prompt": prompt,
        "agentId": "manager",
        "requester": "human",
        "toolId": "agent_collaboration",
        "targetId": MISSION_STRATEGY_TABLE_PROP_ID,
        "risk": "low",
        "modelTier": "manager_quality",
        "reportType": "collaboration_report",
        "idempotencyKey": f"meeting-round:{session_id}:{round_number}",
    }, status="queued", _trusted_discussion_only=True)
    mission["phase"] = "interactive_meeting_round_queued"
    mission["workStatus"] = "queued"
    mission["meetingSessionId"] = session_id
    mission["meetingRoundNumber"] = round_number
    mission["updatedAt"] = utc_now()
    replace_mission(mission)
    return mission


def _interactive_meeting_finish_discussion_mission(
    mission_id: str | None,
    *,
    status: str,
    result: str,
    report_id: str | None = None,
    error_code: str | None = None,
) -> None:
    if not mission_id:
        return
    mission = find_mission(mission_id)
    if not mission:
        return
    completed_at = utc_now()
    mission["status"] = status
    mission["workStatus"] = status
    mission["phase"] = f"interactive_meeting_round_{status}"
    mission["result"] = redact_text(result, 4000)
    mission["reportIds"] = [report_id] if report_id else []
    mission["errorCode"] = error_code
    mission["updatedAt"] = completed_at
    mission["completedAt"] = completed_at
    replace_mission(mission)


def _interactive_meeting_block_orphan_mission(
    mission_id: str | None,
    reason: str,
) -> None:
    if not mission_id:
        return
    mission = find_mission(mission_id)
    if not mission or mission.get("status") in {"completed", "archived"}:
        return
    approval = mission.get("approval") if isinstance(mission.get("approval"), dict) else {}
    if approval.get("required"):
        approval["state"] = "invalidated"
        approval["consumedAt"] = None
        mission["approval"] = approval
    mission["status"] = "blocked"
    mission["workStatus"] = "blocked"
    mission["phase"] = "interactive_meeting_orphan_blocked"
    mission["errorCode"] = reason
    mission["result"] = "Meeting state commit failed; this orphan Mission was blocked before execution."
    mission["updatedAt"] = utc_now()
    replace_mission(mission)
    append_audit({
        "type": "interactive_meeting.orphan_mission_blocked",
        "missionId": mission_id,
        "reason": reason,
        "executed": False,
    })


def _interactive_meeting_round_context(session: dict) -> str:
    turns = [item for item in session.get("turns", []) if isinstance(item, dict)]
    user_turns = [
        _redact_text_fail_closed(
            item.get("message"),
            INTERACTIVE_MEETING_USER_MESSAGE_MAX_CHARS,
            "Interactive meeting user interjection",
        )
        for item in turns
        if item.get("role") == "user"
    ][::-1]
    # The newest human direction remains first, but every same-session
    # interjection is preserved in full. The session has at most three rounds,
    # so at most two user turns can precede an active Agent batch.
    user_context = "\n".join(
        f"- {'ล่าสุด' if index == 0 else 'ก่อนหน้า'}: {item}"
        for index, item in enumerate(user_turns)
    ) or "- ยังไม่มีข้อความแทรกจากผู้ใช้"
    prior_manager_decisions: list[str] = []
    for item in turns:
        if not (
            item.get("role") == "agent"
            and item.get("speakerAgentId") == "manager"
            and item.get("intent") == "decision"
        ):
            continue
        manager_decision = (
            item.get("managerDecision")
            if isinstance(item.get("managerDecision"), dict)
            else {}
        )
        decision_status = _redact_text_fail_closed(
            manager_decision.get("status"),
            40,
            "Interactive meeting prior Manager decision status",
        )
        decision_summary = _redact_text_fail_closed(
            manager_decision.get("summary") or item.get("message"),
            INTERACTIVE_MEETING_MANAGER_DECISION_MAX_CHARS,
            "Interactive meeting prior Manager decision summary",
        )
        structured_proposal = _redact_text_fail_closed(
            item.get("proposal"),
            INTERACTIVE_MEETING_PROPOSAL_MAX_CHARS,
            "Interactive meeting prior Manager proposal",
        )
        prior_manager_decisions.append(json.dumps({
            "roundNumber": int(item.get("roundNumber") or 0),
            "proposal": structured_proposal,
            "managerDecision": {
                "status": decision_status,
                "summary": decision_summary,
            },
        }, ensure_ascii=False, sort_keys=True, separators=(",", ":")))
    prior_decision_context = "\n".join(
        f"- {item}" for item in prior_manager_decisions
    ) or "- ยังไม่มีข้อสรุปรอบก่อนของ Session นี้"
    return _redact_text_fail_closed(
        f"คำสั่งล่าสุดจากผู้ใช้ใน Session นี้ (สำคัญที่สุด):\n{user_context}\n\n"
        f"ข้อสรุปรอบก่อนจาก Session เดียวกันเท่านั้น:\n{prior_decision_context}",
        INTERACTIVE_MEETING_COLLABORATION_MESSAGE_MAX_CHARS,
        "Interactive meeting same-session context",
    )


def _interactive_meeting_agent_topic(session: dict) -> str:
    # Both user-owned fields are already bounded to 2,400 characters at the
    # HTTP boundary. Preserve their tails verbatim after redaction; the final
    # 12,000-character collaboration envelope is checked by the composer.
    agenda = _redact_text_fail_closed(
        session.get("agenda"),
        2400,
        "Interactive meeting agenda",
    ).strip()
    development_goal = _redact_text_fail_closed(
        session.get("developmentGoal") or session.get("agenda"),
        2400,
        "Interactive meeting development goal",
    ).strip()
    return _redact_text_fail_closed(
        f"เป้าหมายการพัฒนาที่ผู้ใช้กำหนด: {development_goal}\n"
        f"หัวข้อการประชุม: {agenda}",
        INTERACTIVE_MEETING_COLLABORATION_MESSAGE_MAX_CHARS,
        "Interactive meeting topic packet",
    )


def _interactive_meeting_record_turn(session_id: str, turn: dict) -> dict:
    with INTERACTIVE_MEETING_SESSIONS_LOCK:
        store = _load_interactive_meeting_store_unlocked()
        session = _interactive_meeting_find_unlocked(store, session_id)
        if not session or session.get("status") != "running":
            raise DataIntegrityError("Interactive meeting round lost its durable running state.")
        turns = list(session.get("turns") or [])
        if len(turns) >= INTERACTIVE_MEETING_MAX_TRANSCRIPT_TURNS:
            raise DataIntegrityError("Interactive meeting transcript limit reached.")
        turns.append(turn)
        session["turns"] = turns
        session["updatedAt"] = utc_now()
        _save_interactive_meeting_store_unlocked(store)
        return copy.deepcopy(session)


def _interactive_meeting_complete_round(
    session_id: str,
    *,
    status: str,
    failure_reason: str | None,
) -> dict | None:
    with INTERACTIVE_MEETING_SESSIONS_LOCK:
        store = _load_interactive_meeting_store_unlocked()
        session = _interactive_meeting_find_unlocked(store, session_id)
        if not session:
            return None
        session["status"] = status
        session["failureReason"] = failure_reason
        session["inflightRoundId"] = None
        session["updatedAt"] = utc_now()
        _save_interactive_meeting_store_unlocked(store)
        return copy.deepcopy(session)


def _run_interactive_meeting_round(session_id: str, round_id: str) -> None:
    semaphore_acquired = False
    failure_reason: str | None = None
    mission_id: str | None = None
    unused_turn_reservations: list[float] = []
    try:
        with INTERACTIVE_MEETING_SESSIONS_LOCK:
            initial_store = _load_interactive_meeting_store_unlocked()
            initial_session = _interactive_meeting_find_unlocked(
                initial_store,
                session_id,
            )
            if initial_session:
                mission_id = safe_reference(
                    initial_session.get("activeDiscussionMissionId")
                )
        if not REAL_RUN_SEMAPHORE.acquire(blocking=False):
            failure_reason = "runner_busy"
            _interactive_meeting_complete_round(
                session_id,
                status="blocked",
                failure_reason=failure_reason,
            )
            _interactive_meeting_finish_discussion_mission(
                mission_id,
                status="blocked",
                result="Interactive meeting round did not start because the Runner was busy.",
                error_code=failure_reason,
            )
            return
        semaphore_acquired = True
        with INTERACTIVE_MEETING_SESSIONS_LOCK:
            store = _load_interactive_meeting_store_unlocked()
            session = _interactive_meeting_find_unlocked(store, session_id)
            if (
                not session
                or session.get("status") != "running"
                or session.get("inflightRoundId") != round_id
            ):
                raise DataIntegrityError("Interactive meeting round binding changed before execution.")
            snapshot = copy.deepcopy(session)
        mission_id = safe_reference(snapshot.get("activeDiscussionMissionId"))
        mission = find_mission(mission_id) if mission_id else None
        if not mission or mission.get("status") != "queued":
            raise DataIntegrityError("Interactive meeting discussion Mission is not queued.")
        speakers = _interactive_meeting_round_speakers(snapshot)
        reserved, _, reservation_stamps = reserve_rate_limit_slots(
            "real:interactive-meeting-turn",
            _interactive_meeting_hourly_turn_cap(),
            len(speakers),
            consume=True,
        )
        if not reserved:
            failure_reason = "hourly_turn_batch_capacity"
            _interactive_meeting_complete_round(
                session_id,
                status="blocked",
                failure_reason=failure_reason,
            )
            _interactive_meeting_finish_discussion_mission(
                mission_id,
                status="blocked",
                result="Interactive meeting round did not start because the full AI-turn batch could not be reserved.",
                error_code=failure_reason,
            )
            return
        unused_turn_reservations = list(reservation_stamps)
        mission["status"] = "running"
        mission["phase"] = "interactive_meeting_round_running"
        mission["workStatus"] = "running"
        mission["startedAt"] = utc_now()
        mission["updatedAt"] = mission["startedAt"]
        replace_mission(mission)
        append_meeting_record({
            "id": round_id,
            "title": f"AI Meeting round {snapshot.get('roundCount')}",
            "agenda": snapshot.get("agenda"),
            "participants": snapshot.get("participantAgentIds"),
            "summary": (
                f"Interactive discussion round started for exactly {len(speakers)} AI turns "
                "with tools disabled."
            ),
            "source": "backend.interactive_meeting",
            "status": "running",
            "trigger": "interactive",
            "linkedMissionId": mission_id,
            "linkedPropId": MISSION_STRATEGY_TABLE_PROP_ID,
        }, "meeting.round.start")
        round_agent_turns: list[dict] = []
        context = _interactive_meeting_round_context(snapshot)
        topic = _interactive_meeting_agent_topic(snapshot)
        for index, speaker_agent_id in enumerate(speakers, start=1):
            _interactive_meeting_require_full_access()
            quota_gate = _collaboration_quota_gate(
                {"minRemainingPercent": AUTOMATION_MIN_REMAINING_PERCENT},
                refresh=True,
            )
            if not quota_gate.get("allowed"):
                failure_reason = str(quota_gate.get("reason") or "quota_guard")
                break
            if not unused_turn_reservations:
                raise DataIntegrityError("Interactive meeting turn reservation was exhausted early.")
            unused_turn_reservations.pop(0)
            turn_result = _run_collaboration_agent_turn(
                meeting_id=session_id,
                mission_id=mission_id,
                speaker_agent_id=speaker_agent_id,
                topic=topic,
                context=context,
                prior_turns=round_agent_turns,
                turn_number=index,
                final_turn=index == len(speakers),
                timeout_seconds=90,
                output_limit=1800,
            )
            invalidate_codex_rate_limit_cache()
            if turn_result.get("ok") is not True:
                failure_reason = str(turn_result.get("status") or "turn_failed")
                break
            now = utc_now()
            contribution = (
                turn_result.get("meetingContribution")
                if isinstance(turn_result.get("meetingContribution"), dict)
                else {}
            )
            turn = {
                "id": f"{round_id}-turn-{index}",
                "roundId": round_id,
                "roundNumber": snapshot.get("roundCount"),
                "role": "agent",
                "speakerAgentId": speaker_agent_id,
                "speakerName": _collaboration_agent_name(speaker_agent_id),
                "speakerRole": str(
                    (contribution.get("speaker") or {}).get("role") or "specialist"
                ),
                "message": turn_result["message"],
                "intent": "decision" if index == len(speakers) else "proposal",
                "proposal": contribution.get("proposal"),
                "risks": list(contribution.get("risks") or []),
                "acceptanceChecks": list(contribution.get("acceptanceChecks") or []),
                "managerDecision": contribution.get("managerDecision"),
                "createdAt": now,
            }
            round_agent_turns.append(turn)
            _interactive_meeting_record_turn(session_id, turn)
            append_meeting_record({
                "id": turn["id"],
                "title": f"{turn['speakerName']} spoke",
                "agenda": snapshot.get("agenda"),
                "participants": snapshot.get("participantAgentIds"),
                "summary": turn["message"],
                "messages": [turn],
                "source": "backend.interactive_meeting",
                "status": "completed",
                "trigger": "interactive",
                "linkedMissionId": mission_id,
                "linkedPropId": MISSION_STRATEGY_TABLE_PROP_ID,
            }, "meeting.turn")
        manager_turn = (
            round_agent_turns[-1]
            if round_agent_turns and round_agent_turns[-1].get("speakerAgentId") == "manager"
            else None
        )
        if (
            failure_reason
            or not manager_turn
            or len(round_agent_turns) != len(speakers)
            or len(speakers) != int(snapshot.get("aiTurnsPerRound") or 0)
        ):
            failure_reason = failure_reason or "manager_final_turn_missing"
            _interactive_meeting_complete_round(
                session_id,
                status="blocked",
                failure_reason=failure_reason,
            )
            _interactive_meeting_finish_discussion_mission(
                mission_id,
                status="blocked",
                result=f"Interactive meeting round stopped safely: {failure_reason}.",
                error_code=failure_reason,
            )
            return
        summary = str(manager_turn.get("message") or "")
        report = create_report({
            "type": "collaboration_report",
            "title": f"AI Meeting round {snapshot.get('roundCount')}",
            "summary": summary,
            "ownerAgentId": "manager",
            "linkedMissionId": mission_id,
            "linkedPropId": MISSION_STRATEGY_TABLE_PROP_ID,
            "status": "ready",
            "findings": [
                f"{item.get('speakerName')}: {item.get('message')}"
                for item in round_agent_turns
                if item.get("speakerAgentId") != "manager"
            ],
            "nextActions": ["User may interject, freeze the Manager proposal, or reject the session."],
            "risks": [],
            "metrics": {
                "roundNumber": snapshot.get("roundCount"),
                "turnCount": len(round_agent_turns),
                "configuredTurnsPerRound": len(speakers),
                "managerFinalTurn": True,
                "toolsExecuted": False,
                "taskCreated": False,
            },
        })
        completed = _interactive_meeting_complete_round(
            session_id,
            status="awaiting_user",
            failure_reason=None,
        )
        _interactive_meeting_finish_discussion_mission(
            mission_id,
            status="completed",
            result=summary,
            report_id=report.get("id"),
        )
        append_meeting_record({
            "id": round_id,
            "title": "Interactive AI meeting round completed",
            "agenda": snapshot.get("agenda"),
            "participants": snapshot.get("participantAgentIds"),
            "summary": summary,
            "messages": round_agent_turns,
            "decisions": [summary],
            "source": "backend.interactive_meeting",
            "status": "awaiting_user",
            "trigger": "interactive",
            "linkedMissionId": mission_id,
            "linkedPropId": MISSION_STRATEGY_TABLE_PROP_ID,
        }, "meeting.round.completed")
        append_audit({
            "type": "interactive_meeting.round_completed",
            "meetingId": session_id,
            "roundId": round_id,
            "missionId": mission_id,
            "turnCount": len(round_agent_turns),
            "configuredTurnsPerRound": len(speakers),
            "speakerSequence": speakers,
            "managerFinalTurn": True,
            "status": (completed or {}).get("status"),
            "toolsExecuted": False,
            "taskCreated": False,
        })
    except (DataIntegrityError, RequestError) as error:
        failure_reason = failure_reason or "meeting_round_guard_failed"
        _interactive_meeting_complete_round(
            session_id,
            status="blocked",
            failure_reason=failure_reason,
        )
        _interactive_meeting_finish_discussion_mission(
            mission_id,
            status="blocked",
            result="Interactive meeting round failed closed before completion.",
            error_code=failure_reason,
        )
        append_audit({
            "type": "interactive_meeting.round_blocked",
            "meetingId": session_id,
            "roundId": round_id,
            "missionId": mission_id,
            "reason": failure_reason,
            "errorType": type(error).__name__,
            "toolsExecuted": False,
        })
    except Exception as error:
        failure_reason = "internal_error"
        _interactive_meeting_complete_round(
            session_id,
            status="failed",
            failure_reason=failure_reason,
        )
        _interactive_meeting_finish_discussion_mission(
            mission_id,
            status="failed",
            result="Interactive meeting round encountered an internal error.",
            error_code=failure_reason,
        )
        append_audit({
            "type": "interactive_meeting.round_failed",
            "meetingId": session_id,
            "roundId": round_id,
            "missionId": mission_id,
            "reason": failure_reason,
            "errorType": type(error).__name__,
            "toolsExecuted": False,
        })
    finally:
        if unused_turn_reservations:
            try:
                release_rate_limit_slots(
                    "real:interactive-meeting-turn",
                    unused_turn_reservations,
                )
            except (OSError, ValueError) as error:
                try:
                    append_audit({
                        "type": "interactive_meeting.turn_reservation_release_failed",
                        "meetingId": session_id,
                        "roundId": round_id,
                        "unusedTurnCount": len(unused_turn_reservations),
                        "errorType": type(error).__name__,
                    })
                except OSError:
                    pass
        if semaphore_acquired:
            REAL_RUN_SEMAPHORE.release()
        with INTERACTIVE_MEETING_SESSIONS_LOCK:
            INTERACTIVE_MEETING_THREADS.pop(session_id, None)
        if INTERACTIVE_MEETING_ROUND_LOCK.locked():
            INTERACTIVE_MEETING_ROUND_LOCK.release()


def _interactive_meeting_start_round_thread(session_id: str, round_id: str) -> None:
    worker = threading.Thread(
        target=_run_interactive_meeting_round,
        args=(session_id, round_id),
        name=f"metafx-interactive-meeting-{session_id}",
        daemon=True,
    )
    with INTERACTIVE_MEETING_SESSIONS_LOCK:
        INTERACTIVE_MEETING_THREADS[session_id] = worker
    try:
        worker.start()
    except Exception:
        with INTERACTIVE_MEETING_SESSIONS_LOCK:
            INTERACTIVE_MEETING_THREADS.pop(session_id, None)
        if INTERACTIVE_MEETING_ROUND_LOCK.locked():
            INTERACTIVE_MEETING_ROUND_LOCK.release()
        _interactive_meeting_complete_round(
            session_id,
            status="failed",
            failure_reason="thread_start_failed",
        )
        raise


def create_interactive_meeting_session(payload: dict) -> dict:
    if not isinstance(payload, dict):
        raise RequestError("Meeting request must be an object.", 422)
    key = _interactive_meeting_idempotency_key(payload)
    request_digest = _interactive_meeting_request_digest("create", payload)
    agenda = str(payload.get("agenda") or "").strip()
    if len(agenda) < 8 or len(agenda) > 2400:
        raise RequestError("Meeting agenda must contain 8-2400 characters.", 422)
    if contains_potential_secret(agenda):
        raise RequestError("Potential secret detected in meeting agenda.", 422)
    development_goal = str(payload.get("developmentGoal") or "").strip()
    if len(development_goal) < 8 or len(development_goal) > 2400:
        raise RequestError("Meeting developmentGoal must contain 8-2400 characters.", 422)
    if contains_potential_secret(development_goal):
        raise RequestError("Potential secret detected in meeting developmentGoal.", 422)
    participants = _interactive_meeting_participants(payload.get("participantAgentIds"))
    ai_turns_per_round = _interactive_meeting_requested_turn_count(
        payload.get("aiTurnsPerRound"),
        participants,
    )
    with INTERACTIVE_MEETING_SESSIONS_LOCK:
        store = _load_interactive_meeting_store_unlocked()
        replay = _interactive_meeting_idempotent_record(
            store["createIdempotency"],
            key=key,
            operation="create",
            request_digest=request_digest,
        )
        if replay:
            session = _interactive_meeting_find_unlocked(store, str(replay.get("sessionId") or ""))
            if not session:
                raise DataIntegrityError("Meeting create idempotency record lost its session.")
            return _interactive_meeting_replay_response(session, replay)
    _interactive_meeting_admit_round(ai_turns_per_round)
    session_id = safe_id(None, "meeting-session")
    round_number = 1
    round_id = f"{session_id}-round-{round_number}"
    mission: dict | None = None
    try:
        mission = _interactive_meeting_create_discussion_mission(
            session_id=session_id,
            agenda=agenda,
            development_goal=development_goal,
            round_number=round_number,
        )
        now = utc_now()
        session = {
            "id": session_id,
            "agenda": redact_text(agenda, 2400),
            "developmentGoal": redact_text(development_goal, 2400),
            "participantAgentIds": participants,
            "aiTurnsPerRound": ai_turns_per_round,
            "status": "running",
            "roundCount": round_number,
            "turns": [],
            "discussionMissionIds": [mission["id"]],
            "activeDiscussionMissionId": mission["id"],
            "implementationMissionId": None,
            "proposal": None,
            "failureReason": None,
            "inflightRoundId": round_id,
            "idempotency": {},
            "createdAt": now,
            "updatedAt": now,
        }
        record = {
            "operation": "create",
            "requestDigest": request_digest,
            "sessionId": session_id,
            "resultKind": "interactive_meeting_created",
            "httpStatus": 202,
            "createdAt": now,
        }
        with INTERACTIVE_MEETING_SESSIONS_LOCK:
            store = _load_interactive_meeting_store_unlocked()
            duplicate = _interactive_meeting_idempotent_record(
                store["createIdempotency"],
                key=key,
                operation="create",
                request_digest=request_digest,
            )
            if duplicate:
                raise DataIntegrityError("Concurrent duplicate meeting create escaped reservation.")
            store["sessions"] = [session, *store["sessions"]][
                :INTERACTIVE_MEETING_MAX_SESSIONS
            ]
            store["createIdempotency"][key] = record
            store["createIdempotency"] = dict(
                list(store["createIdempotency"].items())[-200:]
            )
            _save_interactive_meeting_store_unlocked(store)
        append_audit({
            "type": "interactive_meeting.created",
            "meetingId": session_id,
            "roundId": round_id,
            "missionId": mission["id"],
            "participants": participants,
            "aiTurnsPerRound": ai_turns_per_round,
            "status": "running",
        })
        _interactive_meeting_start_round_thread(session_id, round_id)
        return {
            "ok": True,
            "kind": "interactive_meeting_created",
            "session": _interactive_meeting_session_read_model(session),
            "idempotentReplay": False,
            "_httpStatus": 202,
        }
    except Exception:
        if mission:
            _interactive_meeting_block_orphan_mission(
                safe_reference(mission.get("id")),
                "meeting_session_commit_failed",
            )
        if INTERACTIVE_MEETING_ROUND_LOCK.locked():
            INTERACTIVE_MEETING_ROUND_LOCK.release()
        raise


def append_interactive_meeting_user_message(session_id: str, payload: dict) -> dict:
    normalized_id = safe_reference(session_id)
    if not normalized_id:
        raise RequestError("Invalid meeting session id.", 422)
    key = _interactive_meeting_idempotency_key(payload)
    request_digest = _interactive_meeting_request_digest("message", payload)
    message = str(payload.get("message") or "").strip()
    if (
        len(message) < 1
        or len(message) > INTERACTIVE_MEETING_USER_MESSAGE_MAX_CHARS
    ):
        raise RequestError("Meeting message must contain 1-1600 characters.", 422)
    if contains_potential_secret(message):
        raise RequestError("Potential secret detected in meeting message.", 422)
    with INTERACTIVE_MEETING_SESSIONS_LOCK:
        store = _load_interactive_meeting_store_unlocked()
        session = _interactive_meeting_find_unlocked(store, normalized_id)
        if not session:
            raise RequestError("Meeting session not found.", 404)
        records = session.get("idempotency") if isinstance(session.get("idempotency"), dict) else {}
        replay = _interactive_meeting_idempotent_record(
            records,
            key=key,
            operation="message",
            request_digest=request_digest,
        )
        if replay:
            return _interactive_meeting_replay_response(session, replay)
        if session.get("status") != "awaiting_user":
            raise RequestError("Meeting session is not awaiting a user message.", 409)
        if int(session.get("roundCount") or 0) >= INTERACTIVE_MEETING_MAX_ROUNDS:
            raise RequestError("Meeting session has reached its three-round limit.", 409)
        agenda = str(session.get("agenda") or "")
        development_goal = str(session.get("developmentGoal") or agenda)
        ai_turns_per_round = int(
            session.get("aiTurnsPerRound")
            or len(session.get("participantAgentIds") or [])
        )
    _interactive_meeting_admit_round(ai_turns_per_round)
    mission: dict | None = None
    reservation_token = secrets.token_hex(16)
    round_number = int(session.get("roundCount") or 0) + 1
    round_id = f"{normalized_id}-round-{round_number}"
    try:
        reserved_at = utc_now()
        with INTERACTIVE_MEETING_SESSIONS_LOCK:
            store = _load_interactive_meeting_store_unlocked()
            current = _interactive_meeting_find_unlocked(store, normalized_id)
            if not current or current.get("status") != "awaiting_user":
                raise RequestError("Meeting session state changed before the new round was reserved.", 409)
            records = current.get("idempotency") if isinstance(current.get("idempotency"), dict) else {}
            replay = _interactive_meeting_idempotent_record(
                records,
                key=key,
                operation="message",
                request_digest=request_digest,
            )
            if replay:
                raise DataIntegrityError("Concurrent duplicate message escaped round admission.")
            if int(current.get("roundCount") or 0) + 1 != round_number:
                raise RequestError("Meeting round count changed before reservation.", 409)
            current["status"] = "running"
            current["roundCount"] = round_number
            current["inflightRoundId"] = round_id
            current["roundReservation"] = {
                "token": reservation_token,
                "operation": "message",
                "idempotencyKey": key,
                "requestDigest": request_digest,
                "createdAt": reserved_at,
            }
            current["failureReason"] = None
            current["updatedAt"] = reserved_at
            _save_interactive_meeting_store_unlocked(store)
        mission = _interactive_meeting_create_discussion_mission(
            session_id=normalized_id,
            agenda=agenda,
            development_goal=development_goal,
            round_number=round_number,
            user_message=message,
        )
        now = utc_now()
        user_turn = {
            "id": f"{round_id}-user",
            "roundId": round_id,
            "roundNumber": round_number,
            "role": "user",
            "speakerAgentId": "human",
            "speakerName": "ผู้ใช้",
            "speakerRole": "local_user",
            "message": redact_text(
                message,
                INTERACTIVE_MEETING_USER_MESSAGE_MAX_CHARS,
            ),
            "intent": "interjection",
            "createdAt": now,
        }
        with INTERACTIVE_MEETING_SESSIONS_LOCK:
            store = _load_interactive_meeting_store_unlocked()
            current = _interactive_meeting_find_unlocked(store, normalized_id)
            reservation = current.get("roundReservation") if isinstance((current or {}).get("roundReservation"), dict) else {}
            if (
                not current
                or current.get("status") != "running"
                or current.get("inflightRoundId") != round_id
                or reservation.get("token") != reservation_token
            ):
                raise RequestError("Meeting round reservation changed before Mission binding.", 409)
            records = current.get("idempotency") if isinstance(current.get("idempotency"), dict) else {}
            replay = _interactive_meeting_idempotent_record(
                records,
                key=key,
                operation="message",
                request_digest=request_digest,
            )
            if replay:
                raise DataIntegrityError("Concurrent duplicate message escaped round reservation.")
            current["turns"] = [*current.get("turns", []), user_turn]
            current["activeDiscussionMissionId"] = mission["id"]
            current["discussionMissionIds"] = [
                *current.get("discussionMissionIds", []),
                mission["id"],
            ]
            current["roundReservation"] = None
            current["failureReason"] = None
            current["updatedAt"] = now
            records[key] = {
                "operation": "message",
                "requestDigest": request_digest,
                "resultKind": "interactive_meeting_message_accepted",
                "httpStatus": 202,
                "createdAt": now,
            }
            current["idempotency"] = dict(list(records.items())[-100:])
            _save_interactive_meeting_store_unlocked(store)
            snapshot = copy.deepcopy(current)
        append_meeting_record({
            "id": user_turn["id"],
            "title": "User interjection",
            "agenda": agenda,
            "participants": snapshot.get("participantAgentIds"),
            "summary": user_turn["message"],
            "messages": [user_turn],
            "source": "backend.interactive_meeting",
            "status": "completed",
            "trigger": "interactive",
            "linkedMissionId": mission["id"],
            "linkedPropId": MISSION_STRATEGY_TABLE_PROP_ID,
        }, "meeting.user_turn")
        _interactive_meeting_start_round_thread(normalized_id, round_id)
        return {
            "ok": True,
            "kind": "interactive_meeting_message_accepted",
            "session": _interactive_meeting_session_read_model(snapshot),
            "idempotentReplay": False,
            "_httpStatus": 202,
        }
    except Exception:
        if mission:
            _interactive_meeting_block_orphan_mission(
                safe_reference(mission.get("id")),
                "meeting_message_round_commit_failed",
            )
        with INTERACTIVE_MEETING_SESSIONS_LOCK:
            try:
                store = _load_interactive_meeting_store_unlocked()
                current = _interactive_meeting_find_unlocked(store, normalized_id)
                reservation = current.get("roundReservation") if isinstance((current or {}).get("roundReservation"), dict) else {}
                if current and reservation.get("token") == reservation_token:
                    current["status"] = "awaiting_user"
                    current["roundCount"] = max(0, round_number - 1)
                    current["inflightRoundId"] = None
                    current["roundReservation"] = None
                    current["failureReason"] = None
                    current["updatedAt"] = utc_now()
                    _save_interactive_meeting_store_unlocked(store)
            except (DataIntegrityError, OSError):
                pass
        if INTERACTIVE_MEETING_ROUND_LOCK.locked():
            INTERACTIVE_MEETING_ROUND_LOCK.release()
        raise


def _interactive_meeting_latest_manager_turn(session: dict) -> dict | None:
    turns = session.get("turns") if isinstance(session.get("turns"), list) else []
    return next(
        (
            item
            for item in reversed(turns)
            if isinstance(item, dict)
            and item.get("role") == "agent"
            and item.get("speakerAgentId") == "manager"
            and item.get("intent") == "decision"
        ),
        None,
    )


def _interactive_meeting_proposal_digest(
    session: dict,
    proposal_text: str,
    turn_id: str,
    digest_version: str | None = None,
) -> str:
    manager_turn = next(
        (
            item
            for item in session.get("turns", [])
            if isinstance(item, dict) and item.get("id") == turn_id
        ),
        {},
    )
    structured_decision = {
        "proposal": str(manager_turn.get("proposal") or ""),
        "risks": list(manager_turn.get("risks") or []),
        "acceptanceChecks": list(manager_turn.get("acceptanceChecks") or []),
        "managerDecision": (
            manager_turn.get("managerDecision")
            if isinstance(manager_turn.get("managerDecision"), dict)
            else {}
        ),
    }
    proposal = session.get("proposal") if isinstance(session.get("proposal"), dict) else {}
    version = str(
        digest_version
        or proposal.get("digestVersion")
        or INTERACTIVE_MEETING_LEGACY_PROPOSAL_DIGEST_VERSION
    )
    common_parts = (
        str(session.get("id") or ""),
        turn_id,
        proposal_text,
        json.dumps(
            structured_decision,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ),
    )
    if version == INTERACTIVE_MEETING_LEGACY_PROPOSAL_DIGEST_VERSION:
        return payload_digest(version, *common_parts)
    if version != INTERACTIVE_MEETING_PROPOSAL_DIGEST_VERSION:
        raise DataIntegrityError("Interactive meeting proposal digest version is invalid.")
    return payload_digest(
        version,
        *common_parts,
        str(session.get("agenda") or ""),
        str(session.get("developmentGoal") or session.get("agenda") or ""),
        str(
            session.get("aiTurnsPerRound")
            or len(session.get("participantAgentIds") or [])
        ),
    )


def freeze_interactive_meeting_proposal(session_id: str, payload: dict) -> dict:
    normalized_id = safe_reference(session_id)
    if not normalized_id:
        raise RequestError("Invalid meeting session id.", 422)
    _interactive_meeting_require_full_access()
    key = _interactive_meeting_idempotency_key(payload)
    request_digest = _interactive_meeting_request_digest("proposal", payload)
    with INTERACTIVE_MEETING_SESSIONS_LOCK:
        store = _load_interactive_meeting_store_unlocked()
        session = _interactive_meeting_find_unlocked(store, normalized_id)
        if not session:
            raise RequestError("Meeting session not found.", 404)
        records = session.get("idempotency") if isinstance(session.get("idempotency"), dict) else {}
        replay = _interactive_meeting_idempotent_record(
            records,
            key=key,
            operation="proposal",
            request_digest=request_digest,
        )
        if replay:
            return _interactive_meeting_replay_response(session, replay)
        if session.get("status") != "awaiting_user":
            raise RequestError("Only a completed meeting round may freeze a proposal.", 409)
        manager_turn = _interactive_meeting_latest_manager_turn(session)
        if not manager_turn:
            raise RequestError("Manager final turn is required before freezing a proposal.", 409)
        proposal_text = str(manager_turn.get("message") or "").strip()
        submitted = str(payload.get("proposal") or "").strip()
        if submitted and submitted != proposal_text:
            raise RequestError("Proposal must exactly match the latest Manager decision.", 409)
        if contains_potential_secret(proposal_text):
            raise RequestError("Potential secret detected in Manager proposal.", 422)
        proposal_digest_value = _interactive_meeting_proposal_digest(
            session,
            proposal_text,
            str(manager_turn.get("id") or ""),
            INTERACTIVE_MEETING_PROPOSAL_DIGEST_VERSION,
        )
        now = utc_now()
        session["proposal"] = {
            "text": proposal_text,
            "digest": proposal_digest_value,
            "digestVersion": INTERACTIVE_MEETING_PROPOSAL_DIGEST_VERSION,
            "managerTurnId": manager_turn.get("id"),
            "managerAgentId": "manager",
            "proposal": manager_turn.get("proposal"),
            "risks": list(manager_turn.get("risks") or []),
            "acceptanceChecks": list(manager_turn.get("acceptanceChecks") or []),
            "managerDecision": manager_turn.get("managerDecision"),
            "frozenAt": now,
        }
        session["status"] = "proposed"
        session["updatedAt"] = now
        records[key] = {
            "operation": "proposal",
            "requestDigest": request_digest,
            "resultKind": "interactive_meeting_proposal_frozen",
            "httpStatus": 200,
            "createdAt": now,
        }
        session["idempotency"] = dict(list(records.items())[-100:])
        _save_interactive_meeting_store_unlocked(store)
        snapshot = copy.deepcopy(session)
    append_meeting_record({
        "id": f"{normalized_id}-proposal-{proposal_digest_value[:12]}",
        "title": "Manager proposal frozen",
        "agenda": snapshot.get("agenda"),
        "participants": snapshot.get("participantAgentIds"),
        "summary": proposal_text,
        "decisions": [proposal_text],
        "source": "backend.interactive_meeting",
        "status": "proposed",
        "trigger": "interactive",
        "linkedMissionId": snapshot.get("activeDiscussionMissionId"),
        "linkedPropId": MISSION_STRATEGY_TABLE_PROP_ID,
    }, "meeting.proposal")
    append_audit({
        "type": "interactive_meeting.proposal_frozen",
        "meetingId": normalized_id,
        "proposalDigest": proposal_digest_value,
        "managerTurnId": manager_turn.get("id"),
        "implementationMissionCreated": False,
    })
    return {
        "ok": True,
        "kind": "interactive_meeting_proposal_frozen",
        "session": _interactive_meeting_session_read_model(snapshot),
        "idempotentReplay": False,
    }


def _interactive_meeting_implementation_proposal_from_session(
    session: dict,
    approval_note: str,
) -> dict:
    """Reconstruct the exact implementation packet from one frozen Manager turn."""

    proposal = session.get("proposal") if isinstance(session.get("proposal"), dict) else {}
    proposal_text = str(proposal.get("text") or "")
    proposal_digest_value = str(proposal.get("digest") or "")
    proposal_turn_id = str(proposal.get("managerTurnId") or "")
    manager_turn = next(
        (
            item
            for item in session.get("turns", [])
            if isinstance(item, dict)
            and item.get("id") == proposal_turn_id
            and item.get("speakerAgentId") == "manager"
            and item.get("intent") == "decision"
        ),
        None,
    )
    if not isinstance(manager_turn, dict):
        raise DataIntegrityError(
            "Meeting implementation proposal lost its frozen Manager turn."
        )
    manager_decision = (
        manager_turn.get("managerDecision")
        if isinstance(manager_turn.get("managerDecision"), dict)
        else {}
    )
    structured_proposal = _redact_text_fail_closed(
        manager_turn.get("proposal"),
        INTERACTIVE_MEETING_PROPOSAL_MAX_CHARS,
        "Meeting implementation structured proposal",
    )
    risks = [
        _redact_text_fail_closed(
            item,
            INTERACTIVE_MEETING_LIST_ITEM_MAX_CHARS,
            "Meeting implementation risk",
        )
        for item in (
            manager_turn.get("risks")
            if isinstance(manager_turn.get("risks"), list)
            else []
        )
    ]
    acceptance_checks = [
        _redact_text_fail_closed(
            item,
            INTERACTIVE_MEETING_LIST_ITEM_MAX_CHARS,
            "Meeting implementation acceptance check",
        )
        for item in (
            manager_turn.get("acceptanceChecks")
            if isinstance(manager_turn.get("acceptanceChecks"), list)
            else []
        )
    ]
    decision_status = _redact_text_fail_closed(
        manager_decision.get("status"),
        40,
        "Meeting implementation Manager decision status",
    )
    decision_summary = _redact_text_fail_closed(
        manager_decision.get("summary"),
        INTERACTIVE_MEETING_MANAGER_DECISION_MAX_CHARS,
        "Meeting implementation Manager decision summary",
    )
    exact_frozen_fields = (
        proposal_text == str(manager_turn.get("message") or "")
        and proposal.get("proposal") == manager_turn.get("proposal")
        and proposal.get("risks") == manager_turn.get("risks")
        and proposal.get("acceptanceChecks") == manager_turn.get("acceptanceChecks")
        and proposal.get("managerDecision") == manager_turn.get("managerDecision")
    )
    if (
        not exact_frozen_fields
        or not structured_proposal
        or decision_status not in INTERACTIVE_MEETING_MANAGER_DECISION_STATUSES
        or decision_status == "not_applicable"
        or not decision_summary
        or len(risks) > INTERACTIVE_MEETING_RISK_MAX_ITEMS
        or len(acceptance_checks) > INTERACTIVE_MEETING_ACCEPTANCE_MAX_ITEMS
    ):
        raise DataIntegrityError(
            "Meeting implementation structured proposal no longer matches the digest-bound Manager turn."
        )
    agenda = _redact_text_fail_closed(
        session.get("agenda"),
        2400,
        "Meeting implementation agenda",
    )
    development_goal = _redact_text_fail_closed(
        session.get("developmentGoal") or session.get("agenda"),
        2400,
        "Meeting implementation development goal",
    )
    sanitized_approval_note = _redact_text_fail_closed(
        approval_note,
        1200,
        "Meeting implementation approval note",
    )
    return _validated_interactive_meeting_implementation_proposal({
        "schemaVersion": INTERACTIVE_MEETING_IMPLEMENTATION_PROPOSAL_SCHEMA,
        "meetingId": str(session.get("id") or ""),
        "proposalDigest": proposal_digest_value,
        "proposalTurnId": proposal_turn_id,
        "agenda": agenda,
        "developmentGoal": development_goal,
        "proposal": structured_proposal,
        "risks": risks,
        "acceptanceChecks": acceptance_checks,
        "managerDecision": {
            "status": decision_status,
            "summary": decision_summary,
        },
        "approvalNote": sanitized_approval_note,
    })


def _interactive_meeting_bind_implementation_mission(
    mission_id: str,
    *,
    session_id: str,
    proposal_digest_value: str,
    proposal_turn_id: str,
) -> dict:
    with MISSIONS_LOCK:
        missions = load_missions()
        index = next(
            (idx for idx, item in enumerate(missions) if item.get("id") == mission_id),
            None,
        )
        if index is None:
            raise DataIntegrityError("Meeting implementation Mission disappeared before binding.")
        mission = missions[index]
        expected_binding = {
            "schemaVersion": MEETING_APPROVAL_BINDING_SCHEMA,
            "meetingId": session_id,
            "proposalDigest": proposal_digest_value,
            "proposalTurnId": proposal_turn_id,
        }
        existing_binding = mission.get("meetingApprovalBinding")
        if existing_binding and existing_binding != expected_binding:
            raise DataIntegrityError("Meeting implementation Mission binding changed.")
        structured_proposal = (
            _validated_interactive_meeting_implementation_proposal(
                mission.get("meetingImplementationProposal")
            )
        )
        if any(
            structured_proposal.get(field_name) != expected_binding.get(field_name)
            for field_name in ("meetingId", "proposalDigest", "proposalTurnId")
        ):
            raise DataIntegrityError(
                "Meeting implementation Mission structured proposal binding changed."
            )
        mission["meetingApprovalBinding"] = expected_binding
        mission["executionMode"] = "approved_workspace"
        mission["autoEligible"] = False
        approval = mission.get("approval") if isinstance(mission.get("approval"), dict) else {}
        if approval.get("required") is not True:
            raise DataIntegrityError("Meeting implementation Mission must require approval.")
        if approval.get("state") == "pending":
            approval["payloadDigest"] = mission_payload_digest(mission)
            mission["approval"] = approval
        mission["updatedAt"] = utc_now()
        missions[index] = mission
        save_missions(missions)
        return copy.deepcopy(mission)


def _interactive_meeting_create_implementation_mission(
    session: dict,
    approval_note: str,
) -> dict:
    proposal = session.get("proposal") if isinstance(session.get("proposal"), dict) else {}
    proposal_text = str(proposal.get("text") or "")
    proposal_digest_value = str(proposal.get("digest") or "")
    proposal_turn_id = str(proposal.get("managerTurnId") or "")
    implementation_proposal = (
        _interactive_meeting_implementation_proposal_from_session(
            session,
            approval_note,
        )
    )
    agenda = implementation_proposal["agenda"]
    development_goal = implementation_proposal["developmentGoal"]
    structured_proposal = implementation_proposal["proposal"]
    risks = implementation_proposal["risks"]
    acceptance_checks = implementation_proposal["acceptanceChecks"]
    manager_decision = implementation_proposal["managerDecision"]
    decision_status = manager_decision["status"]
    decision_summary = manager_decision["summary"]
    prompt = _redact_text_fail_closed(
        "Implement this explicitly approved, digest-bound AI meeting proposal only inside the approved HQ roots: "
        "workspace, frontend, backend, runner, contracts, tests, docs, and assets-source. "
        "Keep runtime data, scripts, installer surfaces, .git, MetaTrader, trading actions, and all external side "
        "effects unchanged.\n\n"
        f"Meeting topic:\n{agenda}\n\n"
        f"User-owned development goal:\n{development_goal}\n\n"
        f"Manager visible decision message:\n{proposal_text}\n\n"
        f"Structured approved proposal:\n{structured_proposal}\n\n"
        f"Manager decision status:\n{decision_status}\n\n"
        f"Manager decision summary:\n{decision_summary}\n\n"
        f"User approval note and implementation boundary:\n{approval_note}\n\n"
        "Acceptance checks:\n"
        + ("\n".join(f"- {item}" for item in acceptance_checks) or "- Preserve current verified behavior")
        + "\n\nKnown risks:\n"
        + ("\n".join(f"- {item}" for item in risks) or "- None recorded"),
        INTERACTIVE_MEETING_IMPLEMENTATION_PROMPT_MAX_CHARS,
        "Trusted meeting implementation prompt",
    )
    mission = create_mission({
        "title": f"Implement AI meeting proposal: {proposal_text[:72]}",
        "prompt": prompt,
        "agentId": "ea_developer",
        "requester": "human",
        "toolId": "codex_cli_task",
        "targetId": "terminal_workstation",
        "risk": "high",
        "modelTier": "manager_quality",
        "reportType": "code_change_report",
        "meetingImplementationProposal": implementation_proposal,
        "idempotencyKey": f"meeting-implementation:{session['id']}:{proposal_digest_value[:24]}",
    }, status="waiting_approval", _trusted_meeting_implementation_prompt=prompt)
    return _interactive_meeting_bind_implementation_mission(
        mission["id"],
        session_id=str(session["id"]),
        proposal_digest_value=proposal_digest_value,
        proposal_turn_id=proposal_turn_id,
    )


def approve_interactive_meeting_proposal(session_id: str, payload: dict) -> dict:
    normalized_id = safe_reference(session_id)
    if not normalized_id:
        raise RequestError("Invalid meeting session id.", 422)
    _interactive_meeting_require_full_access()
    key = _interactive_meeting_idempotency_key(payload)
    request_digest = _interactive_meeting_request_digest("approve", payload)
    if str(payload.get("confirmMeetingId") or "") != normalized_id:
        raise RequestError("Approval must explicitly confirm the same meeting id.", 422)
    confirm_digest = str(payload.get("confirmProposalDigest") or "").strip()
    if not re.fullmatch(r"[0-9a-f]{64}", confirm_digest):
        raise RequestError("A lowercase SHA-256 confirmProposalDigest is required.", 422)
    approval_note = str(payload.get("note") or "").strip()
    if not approval_note:
        approval_note = (
            "Explicit local human approval for the separate digest-bound Agent Office code Mission "
            "within the displayed local workspace scope."
        )
    if len(approval_note) > 1200:
        raise RequestError("Meeting approval note must contain at most 1200 characters.", 422)
    if contains_potential_secret(approval_note):
        raise RequestError("Potential secret detected in meeting approval note.", 422)
    approval_note = redact_text(approval_note, 1200)
    reservation_token = secrets.token_hex(16)
    with INTERACTIVE_MEETING_SESSIONS_LOCK:
        store = _load_interactive_meeting_store_unlocked()
        session = _interactive_meeting_find_unlocked(store, normalized_id)
        if not session:
            raise RequestError("Meeting session not found.", 404)
        records = session.get("idempotency") if isinstance(session.get("idempotency"), dict) else {}
        replay = _interactive_meeting_idempotent_record(
            records,
            key=key,
            operation="approve",
            request_digest=request_digest,
        )
        if replay:
            return _interactive_meeting_replay_response(session, replay)
        if session.get("status") != "proposed":
            raise RequestError("Meeting session has no proposal awaiting approval.", 409)
        if isinstance(session.get("approvalReservation"), dict):
            raise RequestError("Meeting proposal approval is already in progress.", 409)
        proposal = session.get("proposal") if isinstance(session.get("proposal"), dict) else {}
        manager_turn = _interactive_meeting_latest_manager_turn(session)
        expected_digest = _interactive_meeting_proposal_digest(
            session,
            str(proposal.get("text") or ""),
            str(proposal.get("managerTurnId") or ""),
        )
        if (
            not manager_turn
            or manager_turn.get("id") != proposal.get("managerTurnId")
            or not secrets.compare_digest(str(proposal.get("digest") or ""), expected_digest)
            or not secrets.compare_digest(confirm_digest, expected_digest)
        ):
            raise RequestError("Meeting proposal approval is stale or digest-bound data changed.", 409)
        session["approvalReservation"] = {
            "token": reservation_token,
            "idempotencyKey": key,
            "requestDigest": request_digest,
            "proposalDigest": confirm_digest,
            "createdAt": utc_now(),
        }
        session["updatedAt"] = utc_now()
        _save_interactive_meeting_store_unlocked(store)
        snapshot = copy.deepcopy(session)
    mission: dict | None = None
    try:
        mission = _interactive_meeting_create_implementation_mission(
            snapshot,
            approval_note,
        )
        approval_state = str((mission.get("approval") or {}).get("state") or "")
        if approval_state == "pending":
            approval_result = approve_mission(mission["id"], {
                "decision": "approved",
                "actorId": "human",
                "confirmMissionId": mission["id"],
                "note": approval_note,
            })
            mission = approval_result.get("mission") if isinstance(approval_result.get("mission"), dict) else mission
        elif approval_state == "approved":
            approval_result = {
                "ok": True,
                "readyToExecute": True,
                "mission": mission,
            }
        else:
            approval_result = {
                "ok": False,
                "readyToExecute": False,
                "mission": mission,
                "kind": "approval_closed",
            }
        ready_to_execute = bool(
            approval_result.get("ok") is True
            and approval_result.get("readyToExecute") is True
            and (mission.get("approval") or {}).get("state") == "approved"
        )
        now = utc_now()
        with INTERACTIVE_MEETING_SESSIONS_LOCK:
            store = _load_interactive_meeting_store_unlocked()
            current = _interactive_meeting_find_unlocked(store, normalized_id)
            if not current:
                raise DataIntegrityError("Meeting session disappeared during approval.")
            current_proposal = current.get("proposal") if isinstance(current.get("proposal"), dict) else {}
            reservation = current.get("approvalReservation") if isinstance(current.get("approvalReservation"), dict) else {}
            if (
                current.get("status") != "proposed"
                or reservation.get("token") != reservation_token
                or not secrets.compare_digest(str(current_proposal.get("digest") or ""), confirm_digest)
            ):
                raise RequestError("Meeting proposal or approval reservation changed.", 409)
            current["implementationMissionId"] = mission["id"]
            current["approvalNote"] = approval_note
            current["status"] = "approved" if ready_to_execute else "blocked"
            current["failureReason"] = None if ready_to_execute else str(approval_result.get("kind") or "mission_approval_incomplete")
            current["approvalReservation"] = None
            current["updatedAt"] = now
            records = current.get("idempotency") if isinstance(current.get("idempotency"), dict) else {}
            records[key] = {
                "operation": "approve",
                "requestDigest": request_digest,
                "resultKind": "interactive_meeting_proposal_approved" if ready_to_execute else "interactive_meeting_implementation_blocked",
                "httpStatus": 200 if ready_to_execute else 409,
                "readyToExecute": ready_to_execute,
                "implementationMissionId": mission["id"],
                "createdAt": now,
            }
            current["idempotency"] = dict(list(records.items())[-100:])
            _save_interactive_meeting_store_unlocked(store)
            session_result = copy.deepcopy(current)
    except Exception:
        if mission:
            _interactive_meeting_block_orphan_mission(
                safe_reference(mission.get("id")),
                "meeting_approval_commit_failed",
            )
        with INTERACTIVE_MEETING_SESSIONS_LOCK:
            try:
                store = _load_interactive_meeting_store_unlocked()
                current = _interactive_meeting_find_unlocked(store, normalized_id)
                reservation = current.get("approvalReservation") if isinstance((current or {}).get("approvalReservation"), dict) else {}
                if current and reservation.get("token") == reservation_token:
                    current["approvalReservation"] = None
                    current["implementationMissionId"] = (
                        safe_reference((mission or {}).get("id")) if mission else None
                    )
                    current["status"] = "blocked" if mission else "proposed"
                    current["failureReason"] = (
                        "meeting_approval_commit_failed" if mission else None
                    )
                    current["updatedAt"] = utc_now()
                    _save_interactive_meeting_store_unlocked(store)
            except (DataIntegrityError, OSError):
                pass
        raise
    append_audit({
        "type": "interactive_meeting.proposal_approval_recorded",
        "meetingId": normalized_id,
        "proposalDigest": confirm_digest,
        "implementationMissionId": mission["id"],
        "missionApprovalState": (mission.get("approval") or {}).get("state"),
        "approvalNoteDigest": payload_digest(
            "interactive-meeting-approval-note-v1",
            approval_note,
        ),
        "approvalNoteChars": len(approval_note),
        "readyToExecute": ready_to_execute,
        "executed": False,
    })
    return {
        "ok": ready_to_execute,
        "kind": "interactive_meeting_proposal_approved" if ready_to_execute else "interactive_meeting_implementation_blocked",
        "session": _interactive_meeting_session_read_model(session_result),
        "implementationMissionId": mission["id"],
        "mission": mission,
        "readyToExecute": ready_to_execute,
        "needsMissionApproval": not ready_to_execute,
        "executed": False,
        "idempotentReplay": False,
        "_httpStatus": 200 if ready_to_execute else 409,
    }


def reject_interactive_meeting_proposal(session_id: str, payload: dict) -> dict:
    normalized_id = safe_reference(session_id)
    if not normalized_id:
        raise RequestError("Invalid meeting session id.", 422)
    _interactive_meeting_require_full_access()
    key = _interactive_meeting_idempotency_key(payload)
    request_digest = _interactive_meeting_request_digest("reject", payload)
    if str(payload.get("confirmMeetingId") or "") != normalized_id:
        raise RequestError("Rejection must explicitly confirm the same meeting id.", 422)
    confirm_digest = str(payload.get("confirmProposalDigest") or "").strip()
    if not re.fullmatch(r"[0-9a-f]{64}", confirm_digest):
        raise RequestError("A lowercase SHA-256 confirmProposalDigest is required.", 422)
    with INTERACTIVE_MEETING_SESSIONS_LOCK:
        store = _load_interactive_meeting_store_unlocked()
        session = _interactive_meeting_find_unlocked(store, normalized_id)
        if not session:
            raise RequestError("Meeting session not found.", 404)
        records = session.get("idempotency") if isinstance(session.get("idempotency"), dict) else {}
        replay = _interactive_meeting_idempotent_record(
            records,
            key=key,
            operation="reject",
            request_digest=request_digest,
        )
        if replay:
            return _interactive_meeting_replay_response(session, replay)
        if session.get("status") != "proposed":
            raise RequestError("Only a proposed meeting session may be rejected.", 409)
        if isinstance(session.get("approvalReservation"), dict):
            raise RequestError("Meeting proposal approval is already in progress.", 409)
        proposal = session.get("proposal") if isinstance(session.get("proposal"), dict) else {}
        expected_digest = _interactive_meeting_proposal_digest(
            session,
            str(proposal.get("text") or ""),
            str(proposal.get("managerTurnId") or ""),
        )
        if (
            not secrets.compare_digest(confirm_digest, str(proposal.get("digest") or ""))
            or not secrets.compare_digest(confirm_digest, expected_digest)
        ):
            raise RequestError("Meeting proposal rejection is stale or digest-bound data changed.", 409)
        now = utc_now()
        session["status"] = "rejected"
        session["failureReason"] = "rejected_by_human"
        session["updatedAt"] = now
        records[key] = {
            "operation": "reject",
            "requestDigest": request_digest,
            "resultKind": "interactive_meeting_proposal_rejected",
            "httpStatus": 200,
            "createdAt": now,
        }
        session["idempotency"] = dict(list(records.items())[-100:])
        _save_interactive_meeting_store_unlocked(store)
        snapshot = copy.deepcopy(session)
    append_meeting_record({
        "id": f"{normalized_id}-rejected-{confirm_digest[:12]}",
        "title": "AI meeting proposal rejected",
        "agenda": snapshot.get("agenda"),
        "participants": snapshot.get("participantAgentIds"),
        "summary": "The local user rejected the digest-bound Manager proposal.",
        "source": "backend.interactive_meeting",
        "status": "rejected",
        "trigger": "interactive",
        "linkedMissionId": snapshot.get("activeDiscussionMissionId"),
        "linkedPropId": MISSION_STRATEGY_TABLE_PROP_ID,
    }, "meeting.proposal.rejected")
    append_audit({
        "type": "interactive_meeting.proposal_rejected",
        "meetingId": normalized_id,
        "proposalDigest": confirm_digest,
        "implementationMissionCreated": False,
    })
    return {
        "ok": True,
        "kind": "interactive_meeting_proposal_rejected",
        "session": _interactive_meeting_session_read_model(snapshot),
        "idempotentReplay": False,
    }


def recover_interrupted_interactive_meeting_sessions() -> int:
    recovered = 0
    with INTERACTIVE_MEETING_SESSIONS_LOCK:
        store = _load_interactive_meeting_store_unlocked()
        for session in store.get("sessions", []):
            approval_reservation = (
                session.get("approvalReservation")
                if isinstance(session.get("approvalReservation"), dict)
                else None
            )
            if approval_reservation:
                proposal = session.get("proposal") if isinstance(session.get("proposal"), dict) else {}
                proposal_digest_value = str(proposal.get("digest") or "")
                mission = find_mission_by_idempotency(
                    f"meeting-implementation:{session.get('id')}:{proposal_digest_value[:24]}"
                )
                if mission:
                    _interactive_meeting_block_orphan_mission(
                        safe_reference(mission.get("id")),
                        "bridge_restart_during_meeting_approval",
                    )
                    session["implementationMissionId"] = mission.get("id")
                    session["status"] = "blocked"
                    session["failureReason"] = "bridge_restart_during_meeting_approval"
                else:
                    session["status"] = "proposed"
                    session["failureReason"] = None
                session["approvalReservation"] = None
                session["updatedAt"] = utc_now()
                recovered += 1
            if session.get("status") != "running" and not session.get("inflightRoundId"):
                continue
            session["status"] = "blocked"
            session["failureReason"] = "bridge_restart_during_round"
            session["inflightRoundId"] = None
            session["roundReservation"] = None
            session["updatedAt"] = utc_now()
            mission_id = safe_reference(session.get("activeDiscussionMissionId"))
            _interactive_meeting_finish_discussion_mission(
                mission_id,
                status="blocked",
                result="Interactive meeting round was interrupted by a Local Bridge restart.",
                error_code="bridge_restart_during_round",
            )
            recovered += 1
        if recovered:
            _save_interactive_meeting_store_unlocked(store)
    if recovered:
        append_audit({
            "type": "interactive_meeting.restart_recovery",
            "recoveredSessionCount": recovered,
            "autoResumed": False,
        })
    return recovered


def find_room_prop(prop_id: str) -> dict | None:
    room = read_json(ROOM_PATH, {})
    candidates = []
    if isinstance(room, dict):
        candidates.extend(room.get("props") or [])
        candidates.extend(room.get("hotspots") or [])
    return next((item for item in candidates if item.get("id") == prop_id), None)


def load_property_role_map() -> dict:
    return read_json(PROPERTY_ROLE_MAP_PATH, {"properties": {}, "routingRules": []})


def load_dashboard_connection_contract() -> dict:
    return read_json(DASHBOARD_CONNECTION_PATH, {"profiles": {}, "statusVocabulary": []})


def find_dashboard_connection_profile(prop_id: str) -> dict:
    role = find_property_role(prop_id)
    profile_id = str(role.get("connectionProfileId") or prop_id)
    contract = load_dashboard_connection_contract()
    profiles = contract.get("profiles") if isinstance(contract.get("profiles"), dict) else {}
    profile = profiles.get(profile_id) if isinstance(profiles, dict) else None
    return profile if isinstance(profile, dict) else {}


def keyword_matches(text: str, token: str) -> bool:
    token = str(token or "").strip().lower()
    if not token:
        return False
    if re.fullmatch(r"[a-z0-9_]+", token):
        return re.search(rf"(?<![a-z0-9_]){re.escape(token)}(?![a-z0-9_])", text) is not None
    return token in text


def find_property_role(prop_id: str) -> dict:
    role_map = load_property_role_map()
    properties = role_map.get("properties") if isinstance(role_map, dict) else {}
    role = properties.get(prop_id) if isinstance(properties, dict) else None
    return role if isinstance(role, dict) else {}


def routing_keywords_for_prop(prop_id: str) -> list[str]:
    role_map = load_property_role_map()
    keywords: list[str] = []
    for rule in role_map.get("routingRules", []):
        if isinstance(rule, dict) and rule.get("targetPropId") == prop_id:
            keywords.extend(str(item) for item in (rule.get("keywords") or []) if str(item).strip())
    return keywords


def load_runtime_reports(limit: int = 120) -> list[dict]:
    ensure_runtime_dir()
    reports = []
    for path in sorted(RUNTIME_REPORTS_DIR.glob("*.json"), key=lambda item: item.stat().st_mtime, reverse=True)[:limit]:
        payload = read_json(path, None)
        if isinstance(payload, dict):
            reports.append(payload)
    return reports


def _verified_metatrader_execution_record(
    source: dict,
    report_type: object,
    linked_mission_id: object,
) -> dict | None:
    """Resolve an MT execution claim only from backend-owned Mission and audit proof."""
    verification_id = safe_reference(source.get("backendVerificationId"))
    mission_id = safe_reference(linked_mission_id)
    tool_id = safe_reference(source.get("toolId"))
    platform = str(source.get("platform") or "").strip().lower()
    terminal_candidate_id = safe_reference(source.get("terminalCandidateId"))
    report_type_name = str(report_type or "")
    requires_v2_optimization_proof = report_type_name == "ea_experiment_report"
    allowed_tool_ids = {"discovery_lab_mt4", "run_optimization"}
    if (
        not verification_id
        or not mission_id
        or tool_id not in allowed_tool_ids
        or platform not in {"mt4", "mt5"}
        or not terminal_candidate_id
    ):
        return None
    if requires_v2_optimization_proof:
        expected_source_kind = f"{platform}_visible_run"
        if str(source.get("sourceKind") or "").strip().lower() != expected_source_kind:
            return None
    try:
        mission = find_mission(mission_id)
    except (DataIntegrityError, OSError):
        return None
    if (
        not isinstance(mission, dict)
        or mission.get("status") != "completed"
        or safe_reference(mission.get("toolId")) != tool_id
    ):
        return None
    requires_visual_backtest = report_type_name in {
        "backtest_report",
        "backtest_optimization_report",
        "optimization_report",
        "ea_experiment_report",
    }
    requires_optimization = report_type_name in {
        "backtest_optimization_report",
        "optimization_report",
        "ea_experiment_report",
    }
    sha256_pattern = re.compile(r"^[a-f0-9]{64}$")
    try:
        records = tail_jsonl(AUDIT_PATH, limit=400, max_bytes=2 * 1024 * 1024)
    except OSError:
        return None
    for event in reversed(records):
        if (
            event.get("type") != "metatrader.execution_verified"
            or safe_reference(event.get("verificationId")) != verification_id
            or safe_reference(event.get("missionId")) != mission_id
            or safe_reference(event.get("toolId")) != tool_id
            or str(event.get("platform") or "").strip().lower() != platform
            or safe_reference(event.get("terminalCandidateId")) != terminal_candidate_id
            or event.get("status") != "completed"
            or event.get("visibleApplicationProof") is not True
            or event.get("liveTrading") is not False
        ):
            continue
        compile_digest = str(event.get("compileArtifactSha256") or "").strip().lower()
        backtest_digest = str(event.get("visualBacktestImageSha256") or "").strip().lower()
        optimization_digest = str(event.get("optimizationArtifactSha256") or "").strip().lower()
        if not sha256_pattern.fullmatch(compile_digest):
            continue
        if requires_visual_backtest and not sha256_pattern.fullmatch(backtest_digest):
            continue
        if requires_optimization and not sha256_pattern.fullmatch(optimization_digest):
            continue
        if requires_v2_optimization_proof:
            source_run_id = safe_reference(source.get("runId"))
            source_round_id = safe_reference(source.get("roundId"))
            source_terminal_id = safe_reference(source.get("terminalId"))
            event_run_id = safe_reference(event.get("runId"))
            event_round_id = safe_reference(event.get("roundId"))
            event_terminal_id = safe_reference(event.get("terminalId"))
            if (
                not source_run_id
                or source_run_id != event_run_id
                or not source_round_id
                or source_round_id != event_round_id
                or not source_terminal_id
                or source_terminal_id != event_terminal_id
                or event.get("testShutdownTerminal") is not False
                or event.get("mtExecutionVerified") is not True
                or event.get("optimizationProofVerified") is not True
            ):
                continue

            source_visible_tester = (
                source.get("visibleTester")
                if isinstance(source.get("visibleTester"), dict)
                else {}
            )
            event_visible_tester = (
                event.get("visibleTester")
                if isinstance(event.get("visibleTester"), dict)
                else {}
            )
            tester_reference_fields = (
                "settingsScreenshotAttachmentId",
                "resultsScreenshotAttachmentId",
                "testerLogArtifactId",
            )
            event_tester_references = {
                field: safe_reference(event_visible_tester.get(field))
                for field in tester_reference_fields
            }
            if (
                event_visible_tester.get("verified") is not True
                or source_visible_tester.get("verified") is not True
                or not all(event_tester_references.values())
                or any(
                    safe_reference(source_visible_tester.get(field))
                    != event_tester_references[field]
                    for field in tester_reference_fields
                )
            ):
                continue

            source_result_report = (
                source.get("resultReport")
                if isinstance(source.get("resultReport"), dict)
                else {}
            )
            event_result_report = (
                event.get("resultReport")
                if isinstance(event.get("resultReport"), dict)
                else {}
            )
            source_manifest = (
                source.get("artifactManifest")
                if isinstance(source.get("artifactManifest"), dict)
                else {}
            )
            event_manifest = (
                event.get("artifactManifest")
                if isinstance(event.get("artifactManifest"), dict)
                else {}
            )
            event_result_artifact_id = safe_reference(event_result_report.get("artifactId"))
            event_result_sha256 = str(event_result_report.get("sha256") or "").strip().lower()
            event_manifest_artifact_id = safe_reference(event_manifest.get("artifactId"))
            event_manifest_sha256 = str(event_manifest.get("sha256") or "").strip().lower()
            if (
                not event_result_artifact_id
                or not sha256_pattern.fullmatch(event_result_sha256)
                or not event_manifest_artifact_id
                or not sha256_pattern.fullmatch(event_manifest_sha256)
                or safe_reference(source_result_report.get("artifactId")) != event_result_artifact_id
                or str(source_result_report.get("sha256") or "").strip().lower() != event_result_sha256
                or safe_reference(source_manifest.get("artifactId")) != event_manifest_artifact_id
                or str(source_manifest.get("sha256") or "").strip().lower() != event_manifest_sha256
            ):
                continue
        return event
    return None


def report_execution_evidence_read_model(
    value: object,
    report_type: object = None,
    linked_mission_id: object = None,
) -> dict:
    source = value if isinstance(value, dict) else {}
    claimed_source_kind = str(source.get("sourceKind") or "analysis_only").strip().lower()
    if claimed_source_kind not in {"analysis_only", "existing_report", "mt4_visible_run", "mt5_visible_run"}:
        claimed_source_kind = "analysis_only"
    verified_record = _verified_metatrader_execution_record(source, report_type, linked_mission_id)
    mt_execution_verified = verified_record is not None
    source_kind = (
        f"{str(source.get('platform')).strip().lower()}_visible_run"
        if mt_execution_verified
        else ("existing_report" if claimed_source_kind == "existing_report" else "analysis_only")
    )
    platform = str(source.get("platform") or "").strip().lower() if mt_execution_verified else None
    terminal_candidate_id = safe_reference(source.get("terminalCandidateId")) if mt_execution_verified else None
    compile_verified = mt_execution_verified
    report_type_name = str(report_type or "")
    requires_backtest = report_type_name in {
        "backtest_report",
        "backtest_optimization_report",
        "optimization_report",
        "ea_experiment_report",
    }
    requires_optimization = report_type_name in {
        "backtest_optimization_report",
        "optimization_report",
        "ea_experiment_report",
    }
    visual_backtest_verified = bool(mt_execution_verified and requires_backtest)
    optimization_verified = bool(mt_execution_verified and requires_optimization)
    record = verified_record if isinstance(verified_record, dict) else {}
    visible_tester_record = (
        record.get("visibleTester")
        if isinstance(record.get("visibleTester"), dict)
        else {}
    )
    result_report_record = (
        record.get("resultReport")
        if isinstance(record.get("resultReport"), dict)
        else {}
    )
    artifact_manifest_record = (
        record.get("artifactManifest")
        if isinstance(record.get("artifactManifest"), dict)
        else {}
    )

    def verified_reference(value: object) -> str | None:
        return safe_reference(value) if mt_execution_verified else None

    def verified_sha256(value: object) -> str | None:
        candidate = str(value or "").strip().lower()
        return candidate if mt_execution_verified and re.fullmatch(r"[a-f0-9]{64}", candidate) else None

    byte_size = result_report_record.get("byteSize")
    safe_byte_size = (
        int(byte_size)
        if mt_execution_verified
        and isinstance(byte_size, int)
        and not isinstance(byte_size, bool)
        and 0 <= byte_size <= 2 * 1024 * 1024 * 1024
        else None
    )
    manifest_items = (
        sanitize_json_value(artifact_manifest_record.get("items")[:100])
        if mt_execution_verified and isinstance(artifact_manifest_record.get("items"), list)
        else []
    )
    return {
        "sourceKind": source_kind,
        "toolId": safe_reference(source.get("toolId")) if mt_execution_verified else None,
        "runId": verified_reference(record.get("runId")),
        "roundId": verified_reference(record.get("roundId")),
        "platform": platform,
        "terminalId": verified_reference(record.get("terminalId")),
        "terminalCandidateId": terminal_candidate_id,
        "backendVerificationId": safe_reference(source.get("backendVerificationId")) if mt_execution_verified else None,
        "visibleTester": {
            "verified": bool(mt_execution_verified and visible_tester_record.get("verified") is True),
            "settingsScreenshotAttachmentId": verified_reference(
                visible_tester_record.get("settingsScreenshotAttachmentId")
            ),
            "resultsScreenshotAttachmentId": verified_reference(
                visible_tester_record.get("resultsScreenshotAttachmentId")
            ),
            "testerLogArtifactId": verified_reference(
                visible_tester_record.get("testerLogArtifactId")
            ),
        },
        "resultReport": {
            "artifactId": verified_reference(result_report_record.get("artifactId")),
            "sha256": verified_sha256(result_report_record.get("sha256")),
            "byteSize": safe_byte_size,
            "mediaType": (
                redact_text(str(result_report_record.get("mediaType") or ""), 120) or None
                if mt_execution_verified
                else None
            ),
        },
        "artifactManifest": {
            "artifactId": verified_reference(artifact_manifest_record.get("artifactId")),
            "sha256": verified_sha256(artifact_manifest_record.get("sha256")),
            "items": manifest_items,
        },
        "compileProofVerified": compile_verified,
        "visualBacktestProofVerified": visual_backtest_verified,
        "optimizationProofVerified": optimization_verified,
        "mtExecutionVerified": mt_execution_verified,
        "scopeLabelTh": (
            "ยืนยันผลจาก MT4/MT5 แบบมองเห็นโปรแกรม"
            if mt_execution_verified
            else "วิเคราะห์โค้ดหรือรายงานที่มีอยู่ ยังไม่ได้ยืนยันการรัน MT4/MT5 จริง"
        ),
    }


def _agent_transfer_storage(value: object) -> dict | None:
    """Validate and project a backend-owned cross-dashboard transfer record."""
    if not isinstance(value, dict):
        return None
    if str(value.get("mode") or "") != DASHBOARD_WORKFLOW_TRANSFER_MODE:
        return None
    source_report_id = safe_reference(value.get("sourceReportId"))
    source_prop_id = safe_reference(value.get("sourcePropId"))
    source_mission_id = safe_reference(value.get("sourceMissionId"))
    transfer_agent_id = safe_reference(value.get("transferAgentId"))
    source_owner_agent_id = safe_reference(value.get("sourceOwnerAgentId"))
    target_prop_id = safe_reference(value.get("targetPropId"))
    handoff_mission_id = safe_reference(value.get("handoffMissionId"))
    if (
        not source_report_id
        or source_prop_id not in DASHBOARD_WORKFLOW_PROP_IDS
        or not source_mission_id
        or transfer_agent_id not in EXPECTED_AGENT_IDS
        or source_owner_agent_id not in EXPECTED_AGENT_IDS
        or target_prop_id not in DASHBOARD_WORKFLOW_PROP_IDS
        or not handoff_mission_id
    ):
        return None
    return {
        "mode": DASHBOARD_WORKFLOW_TRANSFER_MODE,
        "sourceReportId": source_report_id,
        "sourcePropId": source_prop_id,
        "sourceMissionId": source_mission_id,
        "transferAgentId": transfer_agent_id,
        "sourceOwnerAgentId": source_owner_agent_id,
        "targetPropId": target_prop_id,
        "handoffMissionId": handoff_mission_id,
        "status": "recorded",
    }


def _plugin_procedure_storage(value: object) -> dict | None:
    if not isinstance(value, dict) or value.get("contractVersion") != "equipment-plugin-map-v1":
        return None
    procedure_id = safe_reference(value.get("pluginSkillId"))
    procedure_kind = str(value.get("procedureKind") or "").strip()
    invocation_mode = str(value.get("pluginInvocationMode") or "").strip()
    if (
        not procedure_id
        or procedure_kind not in {"custom_plugin_skill", "backend_procedure"}
        or invocation_mode not in {"codex_skill_guided", "backend_owned_procedure"}
    ):
        return None
    skill_installed = value.get("skillInstalled")
    if skill_installed not in {True, False, None}:
        skill_installed = None
    def safe_text_items(raw: object) -> list[str]:
        rows = raw if isinstance(raw, list) else []
        return [redact_text(str(item), 100) for item in rows[:80]]

    raw_entry_contract = value.get("entryContract")
    entry_contract = None
    if isinstance(raw_entry_contract, dict):
        container_field = safe_reference(raw_entry_contract.get("containerField"))
        minimum_items = clamp_int(raw_entry_contract.get("minimumItemsPerRun"), 1, 1, 6)
        maximum_items = clamp_int(raw_entry_contract.get("maximumItemsPerRun"), 6, minimum_items, 6)
        if container_field:
            entry_contract = {
                "containerField": container_field,
                "minimumItemsPerRun": minimum_items,
                "maximumItemsPerRun": maximum_items,
                "workerRequiredFields": safe_text_items(raw_entry_contract.get("workerRequiredFields")),
                "backendComputedFields": safe_text_items(raw_entry_contract.get("backendComputedFields")),
            }

    return {
        "contractVersion": "equipment-plugin-map-v1",
        "pluginSkillId": procedure_id,
        "pluginVersion": redact_text(str(value.get("pluginVersion") or ""), 100),
        "referencePluginSkillId": safe_reference(value.get("referencePluginSkillId")),
        "referencePluginVersion": redact_text(str(value.get("referencePluginVersion") or ""), 100) or None,
        "referenceSkillInstalled": value.get("referenceSkillInstalled") if value.get("referenceSkillInstalled") in {True, False} else None,
        "referenceInstalledVersion": redact_text(str(value.get("referenceInstalledVersion") or ""), 100) or None,
        "referenceVersionMatch": value.get("referenceVersionMatch") if value.get("referenceVersionMatch") in {True, False} else None,
        "procedureKind": procedure_kind,
        "pluginInvocationMode": invocation_mode,
        "skillInstalled": skill_installed,
        "installedVersion": redact_text(str(value.get("installedVersion") or ""), 100) or None,
        "versionMatch": bool(value.get("versionMatch", False)),
        "automationMode": redact_text(str(value.get("automationMode") or "mission_on_demand"), 80),
        "outputFields": safe_text_items(value.get("outputFields")),
        "entryContract": entry_contract,
        "evidenceRequired": safe_text_items(value.get("evidenceRequired")),
        "completionEvidenceRequired": safe_text_items(value.get("completionEvidenceRequired")),
        "screenshotPolicy": redact_text(str(value.get("screenshotPolicy") or ""), 100) or None,
        "adapterStatus": redact_text(str(value.get("adapterStatus") or ""), 100) or None,
        "selectedBy": safe_reference(value.get("selectedBy")),
        "selectedValue": redact_text(str(value.get("selectedValue") or ""), 80) or None,
    }


def _workflow_context_storage(value: object) -> dict | None:
    if not isinstance(value, dict) or value.get("schemaVersion") != "dashboard-workflow-lineage-v1":
        return None
    prop_id = safe_reference(value.get("propId"))
    action_id = safe_reference(value.get("actionId"))
    input_digest = str(value.get("inputDigest") or "")
    if (
        prop_id not in DASHBOARD_WORKFLOW_PROP_IDS
        or action_id not in DASHBOARD_WORKFLOW_ACTIONS
        or not re.fullmatch(r"[0-9a-f]{64}", input_digest)
    ):
        return None
    source = value.get("source") if isinstance(value.get("source"), dict) else None
    agent_transfer = _agent_transfer_storage(value.get("agentTransfer"))
    safe_source = None
    if source:
        safe_source = {
            "reportId": safe_reference(source.get("reportId")),
            "recordId": safe_reference(source.get("recordId")),
            "artifactId": safe_reference(source.get("artifactId")),
            "kind": redact_text(str(source.get("kind") or "report"), 40),
            "propId": safe_reference(source.get("propId")),
            "missionId": safe_reference(source.get("missionId")),
            "transferAgentId": safe_reference(source.get("transferAgentId")),
            "type": redact_text(str(source.get("type") or ""), 120),
            "status": redact_text(str(source.get("status") or ""), 40),
        }
        if safe_source["kind"] == "report":
            if not agent_transfer:
                return None
            if (
                safe_source["reportId"] != agent_transfer["sourceReportId"]
                or safe_source["propId"] != agent_transfer["sourcePropId"]
                or safe_source["missionId"] != agent_transfer["sourceMissionId"]
                or safe_source["transferAgentId"] != agent_transfer["transferAgentId"]
                or prop_id != agent_transfer["targetPropId"]
            ):
                return None
        elif safe_source["kind"] == "verified_catalog_record":
            if (
                action_id != "deep_research_system"
                or prop_id != "left_server_racks"
                or safe_source["propId"] != "codex_mcp_portal"
                or not safe_source["reportId"]
                or not safe_source["missionId"]
                or safe_source["transferAgentId"] is not None
                or agent_transfer is not None
            ):
                return None
        elif safe_source["kind"] == "verified_sheet_record":
            if (
                action_id != "deep_research_system"
                or prop_id != "left_server_racks"
                or safe_source["propId"] != "codex_mcp_portal"
                or not safe_source["reportId"]
                or not safe_source["recordId"]
                or safe_source["transferAgentId"] is not None
                or agent_transfer is not None
            ):
                return None
        else:
            return None
    inputs = value.get("inputs") if isinstance(value.get("inputs"), dict) else {}
    if action_id == "deep_research_system" and (
        "sourceRecordId" in inputs
        or bool(safe_source and safe_source.get("recordId"))
    ):
        selected_record_id = safe_reference(inputs.get("sourceRecordId"))
        if (
            not safe_source
            or safe_source.get("kind") not in {"report", "verified_catalog_record", "verified_sheet_record"}
            or not selected_record_id
            or safe_source.get("recordId") != selected_record_id
        ):
            return None
    trigger_source = str(value.get("triggerSource") or "frontend").strip().lower()
    if trigger_source not in {"frontend", "schedule", "backend"}:
        trigger_source = "backend"
    plugin_procedure = _plugin_procedure_storage(value.get("pluginProcedure"))
    execution_reservation = None
    raw_reservation = value.get("executionReservation")
    if raw_reservation is not None:
        if not isinstance(raw_reservation, dict):
            return None
        reservation_settings_key = str(raw_reservation.get("settingsKey") or "")
        reservation_date = str(raw_reservation.get("bangkokDate") or "")
        reservation_slot = str(raw_reservation.get("slotKey") or "")
        reservation_source = str(raw_reservation.get("source") or "")
        try:
            reservation_date_valid = (
                datetime.strptime(reservation_date, "%Y-%m-%d").date().isoformat()
                == reservation_date
            )
        except (TypeError, ValueError):
            reservation_date_valid = False
        scheduled_slot_match = re.fullmatch(
            rf"indicatorScoutSchedule:{re.escape(reservation_date)}:(\d{{2}})(\d{{2}})",
            reservation_slot,
        )
        scheduled_slot_valid = bool(
            scheduled_slot_match
            and int(scheduled_slot_match.group(1)) <= 23
            and int(scheduled_slot_match.group(2)) <= 59
        )
        manual_slot_valid = bool(
            re.fullmatch(
                rf"indicatorScoutSchedule:{re.escape(reservation_date)}:manual-[0-9a-f]{{16}}",
                reservation_slot,
            )
        )
        allowed_slot = bool(
            (reservation_source == "schedule" and scheduled_slot_valid)
            or (
                reservation_source == "manual_or_backend"
                and manual_slot_valid
            )
        )
        if not (
            prop_id == "left_audit_crystals"
            and action_id == "discover_new_indicators"
            and reservation_settings_key == "indicatorScoutSchedule"
            and reservation_date_valid
            and allowed_slot
            and raw_reservation.get("maximumRunsPerDay") == 1
            and reservation_source in {"schedule", "manual_or_backend"}
            and (
                (trigger_source == "schedule" and reservation_source == "schedule")
                or (
                    trigger_source in {"frontend", "backend"}
                    and reservation_source == "manual_or_backend"
                )
            )
        ):
            return None
        execution_reservation = {
            "settingsKey": "indicatorScoutSchedule",
            "bangkokDate": reservation_date,
            "slotKey": reservation_slot,
            "maximumRunsPerDay": 1,
            "source": reservation_source,
        }
    return {
        "schemaVersion": "dashboard-workflow-lineage-v1",
        "propId": prop_id,
        "actionId": action_id,
        "coordinationMode": DASHBOARD_WORKFLOW_COORDINATION_MODE,
        "source": safe_source,
        "agentTransfer": agent_transfer,
        "inputs": sanitize_json_value(inputs),
        "inputDigest": input_digest,
        "submittedAt": value.get("submittedAt"),
        "triggerSource": trigger_source,
        "executionReservation": execution_reservation,
        "pluginProcedure": plugin_procedure,
    }


def workflow_context_read_model(value: object) -> dict | None:
    context = _workflow_context_storage(value)
    if not context:
        return None
    return {
        "schemaVersion": context["schemaVersion"],
        "propId": context["propId"],
        "actionId": context["actionId"],
        "coordinationMode": context["coordinationMode"],
        "source": context["source"],
        "agentTransfer": context["agentTransfer"],
        "inputDigest": context["inputDigest"],
        "inputFields": sorted(str(key) for key in (context.get("inputs") or {}))[:40],
        "submittedAt": context.get("submittedAt"),
        "triggerSource": context.get("triggerSource"),
        "executionReservation": context.get("executionReservation"),
        "pluginProcedure": context.get("pluginProcedure"),
    }


