def _scheduled_portal_evidence_open_retry_candidate(
    mission: object,
    workflow_settings: object,
    today_bangkok: str,
) -> dict | None:
    """Recognize one exact, safely correctable Portal evidence-open failure."""

    row = mission if isinstance(mission, dict) else {}
    context = _workflow_context_storage(row.get("workflowContext"))
    approval = row.get("approval") if isinstance(row.get("approval"), dict) else {}
    execution = row.get("execution") if isinstance(row.get("execution"), dict) else {}
    receipt = (
        row.get("workflowOutputContract")
        if isinstance(row.get("workflowOutputContract"), dict)
        else {}
    )
    corrective_retry = (
        row.get("correctiveRetry")
        if isinstance(row.get("correctiveRetry"), dict)
        else {}
    )
    if (
        clamp_int(
            corrective_retry.get("attemptCount"),
            0,
            0,
            TRADING_SYSTEM_EVIDENCE_CORRECTIVE_RETRY_MAX_ATTEMPTS,
        )
        >= TRADING_SYSTEM_EVIDENCE_CORRECTIVE_RETRY_MAX_ATTEMPTS
        or TRADING_SYSTEM_EVIDENCE_CANDIDATE_BLOCK_START
        in str(row.get("detail") or "")
    ):
        return None
    if not (
        context
        and context.get("triggerSource") == "schedule"
        and context.get("propId") == "codex_mcp_portal"
        and context.get("actionId") == "discover_trading_systems"
        and _trusted_workflow_guard_intent(row) is not None
        and _current_day_scheduled_workflow_recovery_matches(
            row,
            context,
            workflow_settings,
            today_bangkok,
        )
        and row.get("status") == "failed"
        and row.get("phase") == "auto_guarded_invalid_output"
        and row.get("workStatus") == "invalid_output"
        and row.get("errorCode") == "invalid_output"
        and row.get("structuredOutputError")
        == TRADING_SYSTEM_EVIDENCE_OPEN_ERROR
        and row.get("executionMode") == "auto_guarded"
        and row.get("autoEligible") is True
        and approval.get("required") is False
        and approval.get("state") == "not_required"
        and execution.get("processStarted") is True
        and execution.get("workingDirectory") == "workspace"
        and execution.get("writeRoots") == []
        and execution.get("controlPlaneWritable") is False
        and execution.get("webSearchEnabled") is True
        and execution.get("webSearchUsed") is True
        and execution.get("webSearchEvidenceVerified") is False
        and row.get("webSearchUsed") is True
        and row.get("webSearchEvidenceVerified") is False
        and receipt.get("applicable") is True
        and receipt.get("valid") is False
        and receipt.get("failureCode")
        == "trading_system_output_contract_invalid"
        and receipt.get("procedureId") == TRADING_SYSTEM_WORKFLOW_PROCEDURE_ID
        and receipt.get("providedFields") == []
        and receipt.get("missingFields") == ["systems"]
        and receipt.get("entryErrors") == ["systems_not_array"]
        and int(receipt.get("contractValueChars") or 0) == 0
        and int(receipt.get("sourceUrlCount") or 0) == 0
    ):
        return None
    artifact_reference = safe_codex_artifact_reference(row.get("artifactPath"))
    urls = _trading_system_evidence_retry_urls_from_artifact(artifact_reference)
    block = _trading_system_evidence_candidate_block(urls)
    if not artifact_reference or not urls or not block:
        return None
    return {
        "artifactPath": artifact_reference,
        "urls": urls,
        "candidateBlock": block,
    }


