def _apply_scheduled_portal_trusted_prompt_repair(
    mission: dict,
    candidate: dict,
    *,
    requeued_at: str,
    failure_snapshot: dict | None = None,
) -> bool:
    """Atomically advance one exhausted v6 handoff to terminal-bounded v7."""

    if not _is_v6_portal_trusted_prompt_startup_recovery(mission):
        return False
    urls = candidate.get("urls") if isinstance(candidate.get("urls"), list) else []
    artifact_reference = safe_codex_artifact_reference(
        candidate.get("artifactPath")
    )
    replacement_detail = str(candidate.get("replacementDetail") or "").strip()
    if (
        len(urls) != 6
        or len(set(urls)) != 6
        or not artifact_reference
        or not replacement_detail
        or _trading_system_evidence_urls_from_candidate_block(
            replacement_detail
        )
        != urls
    ):
        return False
    snapshot = failure_snapshot if isinstance(failure_snapshot, dict) else mission
    snapshot_receipt = (
        snapshot.get("workflowOutputContract")
        if isinstance(snapshot.get("workflowOutputContract"), dict)
        else {}
    )
    prior_repair = copy.deepcopy(mission.get("outputContractRepair"))
    existing_retry = copy.deepcopy(mission.get("correctiveRetry"))
    previous = {
        "status": snapshot.get("status"),
        "phase": snapshot.get("phase"),
        "workStatus": snapshot.get("workStatus"),
        "errorCode": snapshot.get("errorCode"),
        "structuredOutputError": snapshot.get("structuredOutputError"),
        "reportIds": copy.deepcopy(snapshot.get("reportIds") or []),
        "artifactPath": artifact_reference,
        "workflowOutputContract": copy.deepcopy(snapshot_receipt),
        "correctiveOpenVerificationReceipt": copy.deepcopy(
            snapshot.get("correctiveOpenVerificationReceipt")
            if isinstance(
                snapshot.get("correctiveOpenVerificationReceipt"),
                dict,
            )
            else None
        ),
    }
    digest = payload_digest(urls)
    mission["detail"] = replacement_detail
    mission["status"] = "queued"
    mission["phase"] = "auto_guarded_trusted_prompt_repair_queued"
    mission["workStatus"] = "queued"
    mission["errorCode"] = None
    mission["runnerStatus"] = None
    mission["result"] = ""
    mission["blockedCapability"] = ""
    mission["startedAt"] = None
    mission["completedAt"] = None
    mission["updatedAt"] = requeued_at
    mission["heartbeatAt"] = requeued_at
    mission["attemptCount"] = 0
    mission["reportIds"] = []
    mission["evidence"] = []
    mission["workflowOutputContract"] = None
    mission.pop("correctiveOpenVerificationReceipt", None)
    mission["artifactPath"] = None
    mission["structuredOutputError"] = None
    mission["webSearchUsed"] = False
    mission["webSearchEvidenceVerified"] = False
    budget = (
        copy.deepcopy(mission.get("budget"))
        if isinstance(mission.get("budget"), dict)
        else {}
    )
    budget["rateReservePercent"] = AUTOMATION_MIN_REMAINING_PERCENT
    budget["timeoutSeconds"] = max(
        300,
        clamp_int(budget.get("timeoutSeconds"), 120, 15, 600),
    )
    budget["outputLimitChars"] = 20000
    mission["budget"] = budget
    mission["approval"] = _not_required_approval_record()
    mission["requiresHumanApproval"] = False
    mission["autoQueuedAt"] = requeued_at
    mission["execution"] = {}
    mission["correctiveRetry"] = {
        **existing_retry,
        "attemptCount": 1,
        "maximumAttempts": TRADING_SYSTEM_EVIDENCE_CORRECTIVE_RETRY_MAX_ATTEMPTS,
        "requeuedAt": requeued_at,
        "sourceArtifact": artifact_reference,
        "candidateUrlCount": 6,
        "candidateUrlDigest": digest,
        "automaticRetry": True,
        "scheduleSlotPreserved": True,
        "newDailyReservation": False,
        "newReport": False,
    }
    mission["trustedPromptRepair"] = {
        "schemaVersion": "trusted-prompt-repair-v1",
        "version": TRADING_SYSTEM_TRUSTED_PROMPT_REPAIR_VERSION,
        "kind": TRADING_SYSTEM_TRUSTED_PROMPT_REPAIR_KIND,
        "attemptCount": 1,
        "maximumAttempts": TRADING_SYSTEM_TRUSTED_PROMPT_REPAIR_MAX_ATTEMPTS,
        "requeuedAt": requeued_at,
        "sourceArtifact": artifact_reference,
        "candidateUrlCount": 6,
        "candidateUrlDigest": digest,
        "automaticRetry": True,
        "candidateBlockReplaced": True,
        "scheduleSlotPreserved": True,
        "newDailyReservation": False,
        "newReport": False,
        "previous": previous,
    }
    mission["outputContractRepair"] = {
        "version": TRADING_SYSTEM_TRUSTED_PROMPT_OUTPUT_REPAIR_VERSION,
        "kind": "trading_system_evidence_open_trusted_prompt_repair",
        "requeuedAt": requeued_at,
        "previous": {
            **previous,
            "priorRepair": prior_repair,
        },
        "scheduleSlotPreserved": True,
        "newDailyReservation": False,
    }
    _issue_backend_auto_safe_authorization(mission, issued_at=requeued_at)
    execution = (
        mission.get("execution")
        if isinstance(mission.get("execution"), dict)
        else {}
    )
    execution["automaticRetry"] = True
    execution["correctiveRetryKind"] = TRADING_SYSTEM_EVIDENCE_CORRECTIVE_RETRY_KIND
    execution["trustedPromptRepairKind"] = TRADING_SYSTEM_TRUSTED_PROMPT_REPAIR_KIND
    mission["execution"] = execution
    return True


